css:
.dsp-runway {
  /* re-theme with these four */
  --dsp-runway-bg: oklch(0.205 0.012 65);
  --dsp-runway-ink: oklch(0.95 0.012 85);
  --dsp-runway-accent: oklch(0.83 0.15 78);
  --dsp-runway-hot: oklch(0.68 0.19 33);
  /* derived */
  --dsp-runway-panel: color-mix(in oklch, var(--dsp-runway-bg), var(--dsp-runway-ink) 4%);
  --dsp-runway-raised: color-mix(in oklch, var(--dsp-runway-bg), var(--dsp-runway-ink) 8%);
  --dsp-runway-line: color-mix(in oklch, var(--dsp-runway-ink) 11%, transparent);
  --dsp-runway-hair: color-mix(in oklch, var(--dsp-runway-ink) 6%, transparent);
  --dsp-runway-mute: color-mix(in oklch, var(--dsp-runway-ink) 64%, var(--dsp-runway-bg));
  --dsp-runway-faint: color-mix(in oklch, var(--dsp-runway-ink) 42%, var(--dsp-runway-bg));
  --dsp-runway-ok: color-mix(in oklch, var(--dsp-runway-ink) 70%, var(--dsp-runway-bg));
  --dsp-runway-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dsp-runway-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dsp-runway-out: cubic-bezier(.2, .9, .25, 1);
  --dsp-runway-spring: linear(0, .06 2.4%, .25 6%, .56 11%, .86 17%, 1.04 23.5%, 1.09 29%, 1.06 36%, 1.01 46%, .995 60%, 1);
  --dsp-runway-now: 860;
  --dsp-runway-lane: 112px;
  width: 100%;
  height: var(--dsp-runway-h, 680px);
  container-type: inline-size;
  container-name: dsp-runway;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background: var(--dsp-runway-bg);
  color: var(--dsp-runway-ink);
  font: 13px/1.45 var(--dsp-runway-sans);
  color-scheme: dark;
  accent-color: var(--dsp-runway-accent);
  box-shadow: inset 0 0 0 1px var(--dsp-runway-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, ol) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(button:disabled, button[aria-disabled="true"]) { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dsp-runway-accent); outline-offset: 2px; border-radius: 6px; }
  & svg { flex: none; }
}

.dsp-runway__app {
  height: 100%;
  display: grid;
  grid-template-columns: 196px minmax(0, 1fr) 292px;
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "side head detail" "side kpis detail" "side main detail";
}

/* ---------------------------------------------------------------- sidebar */
.dsp-runway__side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 18px;
  padding: 18px 12px 14px; border-right: 1px solid var(--dsp-runway-line);
  background: color-mix(in oklch, var(--dsp-runway-bg), black 18%);
  overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dsp-runway-line) transparent;
}
.dsp-runway__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; background: var(--dsp-runway-accent); stroke: var(--dsp-runway-bg); fill: none; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  & span { display: grid; line-height: 1.2; min-width: 0; }
  & b { font-weight: 700; letter-spacing: -.01em; }
  & small { color: var(--dsp-runway-faint); font-size: 11px; }
}
.dsp-runway__nav {
  display: grid; gap: 2px;
  & button {
    display: flex; align-items: center; gap: 10px; height: 34px; padding: 0 10px; border-radius: 9px;
    color: var(--dsp-runway-mute); font-weight: 560; transition: background-color .18s, color .18s;
  }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & button:hover { background: var(--dsp-runway-hair); color: var(--dsp-runway-ink); }
  & button[aria-current="page"] { background: var(--dsp-runway-raised); color: var(--dsp-runway-ink); box-shadow: inset 2px 0 0 var(--dsp-runway-accent); }
}
.dsp-runway__filters { display: grid; gap: 8px; }
.dsp-runway__lbl { font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dsp-runway-faint); padding: 0 8px; margin-top: 4px; }
.dsp-runway__teams, .dsp-runway__metrics {
  display: grid; gap: 1px;
  & button {
    display: flex; align-items: center; gap: 8px; min-height: 28px; padding: 0 8px; border-radius: 7px; text-align: left;
    color: var(--dsp-runway-mute); transition: background-color .15s, color .15s;
  }
  & button:hover { background: var(--dsp-runway-hair); color: var(--dsp-runway-ink); }
  & button i { width: 14px; height: 14px; border-radius: 50%; flex: none; box-shadow: inset 0 0 0 1.5px var(--dsp-runway-faint); display: grid; place-items: center; transition: box-shadow .2s; }
  & button span { flex: 1; min-width: 0; }
  & button em { font: 600 11px var(--dsp-runway-mono); font-style: normal; color: var(--dsp-runway-faint); font-variant-numeric: tabular-nums; }
  & button[aria-checked="true"] { color: var(--dsp-runway-ink); }
  & button[aria-checked="true"] i { box-shadow: inset 0 0 0 4.5px var(--dsp-runway-accent); }
}
.dsp-runway__metrics {
  & button i { border-radius: 4px; }
  & button[aria-pressed="true"] { color: var(--dsp-runway-ink); }
  & button[aria-pressed="true"] i { box-shadow: inset 0 0 0 7px var(--dsp-runway-accent); }
  & button[aria-pressed="true"] i::after { content: ""; width: 7px; height: 4px; border: solid var(--dsp-runway-bg); border-width: 0 0 2px 2px; rotate: -45deg; translate: 0 -1px; }
}
.dsp-runway__switch {
  display: flex; align-items: center; gap: 9px; min-height: 30px; padding: 0 8px; border-radius: 7px; color: var(--dsp-runway-mute);
  & i { width: 26px; height: 15px; border-radius: 99px; background: var(--dsp-runway-line); position: relative; flex: none; transition: background-color .2s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 11px; height: 11px; border-radius: 50%; background: var(--dsp-runway-ink); transition: translate .32s var(--dsp-runway-spring); }
  &[aria-checked="true"] { color: var(--dsp-runway-ink); }
  &[aria-checked="true"] i { background: var(--dsp-runway-accent); }
  &[aria-checked="true"] i::after { translate: 11px 0; background: var(--dsp-runway-bg); }
  &:hover { background: var(--dsp-runway-hair); }
}
.dsp-runway__me {
  margin-top: auto; display: flex; align-items: center; gap: 9px; padding: 10px 8px 0; border-top: 1px solid var(--dsp-runway-line);
  & b { width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; font-size: 10.5px; font-weight: 700; background: color-mix(in oklch, var(--dsp-runway-accent) 22%, var(--dsp-runway-bg)); color: var(--dsp-runway-accent); flex: none; }
  & span { display: grid; font-size: 12px; font-weight: 600; line-height: 1.25; }
  & small { font-weight: 400; color: var(--dsp-runway-faint); font-size: 11px; }
}

/* ---------------------------------------------------------------- header */
.dsp-runway__head {
  grid-area: head; display: flex; align-items: center; gap: 16px; padding: 16px 20px 10px; min-width: 0;
}
.dsp-runway__title {
  flex: 1; min-width: 0;
  & h2 { font-size: clamp(17px, 1.2cqi + 6px, 21px); font-weight: 720; letter-spacing: -.022em; text-wrap: balance; }
  & p { color: var(--dsp-runway-mute); font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & p b { color: var(--dsp-runway-ink); font-weight: 600; }
}
.dsp-runway__clock {
  display: grid; justify-items: end; line-height: 1.1;
  & time { font: 650 23px var(--dsp-runway-sans); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--dsp-runway-faint); }
}
.dsp-runway__speed {
  display: flex; padding: 3px; border-radius: 10px; background: var(--dsp-runway-panel); box-shadow: inset 0 0 0 1px var(--dsp-runway-line);
  & button { display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dsp-runway-mute); white-space: nowrap; transition: background-color .18s, color .18s; }
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }
  & button:hover { color: var(--dsp-runway-ink); }
  & button[aria-checked="true"] { background: var(--dsp-runway-raised); color: var(--dsp-runway-ink); box-shadow: 0 1px 0 var(--dsp-runway-line); }
}

/* ---------------------------------------------------------------- kpis */
.dsp-runway__kpis {
  grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; padding: 0 20px 12px;
}
.dsp-runway__kpi {
  --c: var(--dsp-runway-ink);
  position: relative; display: grid; gap: 1px; padding: 10px 12px 10px 14px; border-radius: 11px; background: var(--dsp-runway-panel);
  box-shadow: inset 0 0 0 1px var(--dsp-runway-hair); overflow: hidden;
  animation: dsp-runway-rise .6s var(--dsp-runway-out) both; animation-delay: calc(var(--i) * 60ms + 80ms);
  &::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--c); opacity: .85; }
  & span { font-size: 11px; color: var(--dsp-runway-mute); font-weight: 560; }
  & b { font: 650 clamp(20px, 1.4cqi + 8px, 26px)/1.1 var(--dsp-runway-sans); font-variant-numeric: tabular-nums; letter-spacing: -.03em; color: var(--c); }
  & small { font-size: 11px; color: var(--dsp-runway-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &.is-hot { --c: var(--dsp-runway-hot); }
  &.is-warn { --c: var(--dsp-runway-accent); }
}
@keyframes dsp-runway-rise { from { opacity: 0; translate: 0 8px; } }

/* ---------------------------------------------------------------- main + views */
.dsp-runway__main { grid-area: main; min-height: 0; min-width: 0; position: relative; }
.dsp-runway__view {
  height: 100%; overflow: auto; padding: 0 20px 18px; scrollbar-width: thin; scrollbar-color: var(--dsp-runway-line) transparent;
  &[hidden] { display: none; }
}
.dsp-runway__view:not([hidden]) { animation: dsp-runway-view .42s var(--dsp-runway-out); }
@keyframes dsp-runway-view { from { opacity: 0; translate: 0 6px; } }

.dsp-runway__legend {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 14px; font-size: 11.5px; color: var(--dsp-runway-mute); padding: 2px 0 10px;
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 10px; height: 10px; border-radius: 50%; }
  & .ok { background: var(--dsp-runway-ok); }
  & .warn { background: var(--dsp-runway-accent); }
  & .hot { background: var(--dsp-runway-hot); }
  & .ring { box-shadow: inset 0 0 0 2px var(--dsp-runway-ok); }
  & em { margin-left: auto; font-style: normal; color: var(--dsp-runway-faint); font-size: 11px; }
}

/* lane geometry shared by the axis, the lanes and the histogram */
.dsp-runway__axis, .dsp-runway__lane, .dsp-runway__hist {
  display: grid; grid-template-columns: var(--dsp-runway-lane) minmax(0, 1fr); align-items: stretch;
}
.dsp-runway__lanehd { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dsp-runway-faint); align-self: end; padding-bottom: 6px; line-height: 1.25; }
.dsp-runway__axisrail, .dsp-runway__rail, .dsp-runway__histrail { position: relative; margin-inline: 8px; container-type: inline-size; }
.dsp-runway__axisrail {
  height: 30px;
  & span { position: absolute; bottom: 6px; translate: -50% 0; font: 500 10.5px var(--dsp-runway-mono); color: var(--dsp-runway-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }
  & span.is-now { color: var(--dsp-runway-ink); font-weight: 700; bottom: 14px; }
  & span.is-now small { display: block; text-align: center; font-weight: 500; color: var(--dsp-runway-accent); }
  & span.is-minor { opacity: .7; }
}
.dsp-runway__lanes { display: grid; gap: 6px; }
.dsp-runway__lane {
  --rows: 1;
  & .dsp-runway__lname { display: grid; align-content: center; gap: 1px; padding: 6px 8px 6px 0; border-right: 1px solid var(--dsp-runway-line); }
  & .dsp-runway__lname b { font-size: 12.5px; font-weight: 650; display: flex; align-items: center; gap: 7px; }
  & .dsp-runway__lname b::before { content: ""; width: 7px; height: 7px; border-radius: 2px; background: var(--pc); rotate: 45deg; }
  & .dsp-runway__lname small { font: 500 11px var(--dsp-runway-mono); color: var(--dsp-runway-faint); font-variant-numeric: tabular-nums; padding-left: 14px; }
}
.dsp-runway__rail {
  height: calc(var(--rows) * 18px + 22px);
  min-height: 48px;
  border-radius: 8px;
  transition: height .45s var(--dsp-runway-out);
  background:
    linear-gradient(to right, transparent calc(20% - 1px), color-mix(in oklch, var(--dsp-runway-ink) 70%, transparent) calc(20% - 1px) calc(20% + 1px), transparent calc(20% + 1px)),
    repeating-linear-gradient(to right, var(--dsp-runway-hair) 0 1px, transparent 1px 10%),
    linear-gradient(to right, color-mix(in oklch, var(--dsp-runway-hot) 15%, transparent) 0 20%, color-mix(in oklch, var(--dsp-runway-accent) 9%, transparent) 20% 30%, var(--dsp-runway-panel) 30%);
}
.dsp-runway__lane:nth-child(odd) .dsp-runway__rail { --dsp-runway-panel: color-mix(in oklch, var(--dsp-runway-bg), var(--dsp-runway-ink) 3%); }

/* one custom property on the root moves every ticket: x = (deadline - now + 120) / 600 of the rail */
.dsp-runway__tk {
  --p: clamp(0, (var(--d) - var(--dsp-runway-now) + 120) / 600, 1);
  --c: var(--dsp-runway-ok);
  position: absolute; left: 0; top: 0;
  width: 14px; height: 14px; margin: 11px 0 0 -7px; border-radius: 50%;
  translate: calc(var(--p) * 100cqi) calc(var(--row) * 18px);
  background: var(--c);
  transition: translate 1s linear, background-color .3s, box-shadow .3s, scale .3s var(--dsp-runway-spring);
  z-index: 1;
  &[data-state="warn"] { --c: var(--dsp-runway-accent); }
  &[data-state="hot"] { --c: var(--dsp-runway-hot); box-shadow: 0 0 10px -1px color-mix(in oklch, var(--dsp-runway-hot) 75%, transparent); }
  &[data-un="1"] { background: color-mix(in oklch, var(--dsp-runway-bg), var(--c) 18%); box-shadow: inset 0 0 0 2.5px var(--c); }
  &[data-un="1"][data-state="hot"]::after {
    content: ""; position: absolute; inset: -3px; border-radius: 50%; border: 1.5px solid var(--dsp-runway-hot);
    animation: dsp-runway-ping 1.8s cubic-bezier(.2, .7, .3, 1) infinite;
  }
  &:hover, &:focus-visible { scale: 1.3; z-index: 3; }
  &:focus-visible { outline-offset: 3px; border-radius: 50%; }
  &[aria-current="true"] { scale: 1.35; z-index: 4; outline: 2px solid var(--dsp-runway-ink); outline-offset: 2px; }
  &.is-new { animation: dsp-runway-pop .55s var(--dsp-runway-spring) both; }
  &.is-leaving { animation: dsp-runway-leave .42s var(--dsp-runway-out) forwards; pointer-events: none; }
}
@keyframes dsp-runway-ping { from { scale: .9; opacity: .9; } to { scale: 2.1; opacity: 0; } }
@keyframes dsp-runway-pop { from { opacity: 0; scale: .2; } }
@keyframes dsp-runway-leave { to { opacity: 0; scale: 1.9; filter: blur(2px); } }
.dsp-runway__lanes.is-intro .dsp-runway__tk { animation: dsp-runway-drop .7s var(--dsp-runway-spring) both; animation-delay: calc(var(--i) * 14ms + 120ms); }
@keyframes dsp-runway-drop { from { opacity: 0; scale: .3; } }

.dsp-runway__overs { display: flex; flex-wrap: wrap; gap: 3px; padding-left: 14px; margin-top: 3px; &:empty { display: none; } }
.dsp-runway__over {
  height: 17px; padding: 0 6px; border-radius: 99px; font: 600 10px var(--dsp-runway-mono);
  font-variant-numeric: tabular-nums; display: inline-flex; align-items: center; gap: 3px; white-space: nowrap;
  transition: filter .15s;
  &.is-left { background: color-mix(in oklch, var(--dsp-runway-hot) 28%, var(--dsp-runway-bg)); color: color-mix(in oklch, var(--dsp-runway-hot), white 38%); }
  &.is-right { background: var(--dsp-runway-raised); color: var(--dsp-runway-mute); }
  &:hover { filter: brightness(1.3); }
}

.dsp-runway__hist { margin-top: 10px; }
.dsp-runway__histrail {
  height: 74px; display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); align-items: end; gap: 0;
  border-bottom: 1px solid var(--dsp-runway-line);
  & .dsp-runway__bar { position: relative; height: 100%; display: flex; align-items: flex-end; justify-content: center; padding: 0 18%; cursor: default; }
  & .dsp-runway__bar i {
    display: block; width: 100%; height: calc(var(--v) * 54px + 2px); border-radius: 4px 4px 1px 1px;
    background: var(--c, var(--dsp-runway-ok)); opacity: .8; transform-origin: bottom;
    transition: height .5s var(--dsp-runway-out), opacity .15s;
    animation: dsp-runway-grow .8s var(--dsp-runway-out) both; animation-delay: calc(var(--i) * 40ms + 200ms);
  }
  & .dsp-runway__bar b { position: absolute; bottom: calc(var(--v) * 54px + 5px); font: 600 10.5px var(--dsp-runway-mono); color: var(--dsp-runway-mute); font-variant-numeric: tabular-nums; transition: bottom .5s var(--dsp-runway-out); }
  & .dsp-runway__bar:hover i { opacity: 1; }
  & .dsp-runway__bar.is-hot { --c: var(--dsp-runway-hot); }
  & .dsp-runway__bar.is-warn { --c: var(--dsp-runway-accent); }
}
@keyframes dsp-runway-grow { from { scale: 1 0; } }

/* ---------------------------------------------------------------- cards (age + policy) */
.dsp-runway__card {
  background: var(--dsp-runway-panel); border-radius: 12px; box-shadow: inset 0 0 0 1px var(--dsp-runway-hair); padding: 14px 16px; margin-bottom: 12px;
}
.dsp-runway__cardhd {
  margin-bottom: 10px;
  & h3 { font-size: 14px; font-weight: 680; letter-spacing: -.01em; text-wrap: balance; }
  & p { font-size: 12px; color: var(--dsp-runway-mute); text-wrap: pretty; max-width: 62ch; }
}
.dsp-runway__agechart svg { width: 100%; height: auto; display: block; overflow: visible; }
.dsp-runway__agechart {
  & .ax text { font: 500 10.5px var(--dsp-runway-mono); fill: var(--dsp-runway-faint); }
  & .ax line { stroke: var(--dsp-runway-hair); }
  & .lb { font: 600 12px var(--dsp-runway-sans); fill: var(--dsp-runway-ink); }
  & .tot { font: 600 11px var(--dsp-runway-mono); fill: var(--dsp-runway-mute); }
  & rect.seg { transform-box: fill-box; transform-origin: left; animation: dsp-runway-grow-x .7s var(--dsp-runway-out) both; animation-delay: calc(var(--i) * 45ms); transition: opacity .15s; cursor: default; }
  & svg:has(rect.seg:hover) rect.seg:not(:hover) { opacity: .45; }
}
@keyframes dsp-runway-grow-x { from { scale: 0 1; } }
.dsp-runway__agekey {
  display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 8px; font-size: 11.5px; color: var(--dsp-runway-mute);
  & li { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
}
.dsp-runway__agetable, .dsp-runway__poltable { width: 100%; }
.dsp-runway__agetable {
  border-collapse: collapse; font-size: 12.5px;
  & th { text-align: left; font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--dsp-runway-faint); padding: 0 8px 8px; border-bottom: 1px solid var(--dsp-runway-line); }
  & td { padding: 8px; border-bottom: 1px solid var(--dsp-runway-hair); font-variant-numeric: tabular-nums; }
  & .n { text-align: right; font-family: var(--dsp-runway-mono); }
  & tr:last-child td { border-bottom: 0; }
  & button { display: inline-flex; gap: 6px; align-items: baseline; text-align: left; color: var(--dsp-runway-accent); font-weight: 600; border-radius: 4px; }
  & button small { color: var(--dsp-runway-mute); font-weight: 400; }
  & button:hover { text-decoration: underline; text-underline-offset: 3px; }
}

.dsp-runway__polhd { display: flex; gap: 16px; align-items: flex-start; justify-content: space-between; }
.dsp-runway__btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 30px; padding: 0 12px; border-radius: 8px;
  font-size: 12px; font-weight: 620; white-space: nowrap; background: var(--dsp-runway-raised); box-shadow: inset 0 0 0 1px var(--dsp-runway-line);
  transition: background-color .15s, opacity .15s, scale .2s var(--dsp-runway-spring);
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--dsp-runway-raised), var(--dsp-runway-ink) 8%); }
