};
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/* ---------- deterministic data ---------- */
let seed = 7741;
const rnd = () => {
  seed = (seed + 0x6D2B79F5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const pick = (a) => a[Math.floor(rnd() * a.length)];
const weighted = (pairs) => {
  let r = rnd();
  for (const [v, w] of pairs) { if ((r -= w) < 0) return v; }
  return pairs[pairs.length - 1][0];
};
const gauss = () => Math.sqrt(-2 * Math.log(rnd() || 1e-9)) * Math.cos(2 * Math.PI * rnd());

const PRI = ['urgent', 'high', 'normal', 'low'];
const PLABEL = { urgent: 'Urgent', high: 'High', normal: 'Normal', low: 'Low' };
const PCOL = { urgent: 'var(--dsp-runway-hot)', high: 'var(--dsp-runway-accent)', normal: 'var(--dsp-runway-ok)', low: 'var(--dsp-runway-faint)' };
const METRICS = ['fr', 'nr', 'res'];
const MLABEL = { fr: 'First response', nr: 'Next reply', res: 'Resolution' };
const DEFAULTS = { urgent: { fr: 30, nr: 60, res: 240 }, high: { fr: 60, nr: 120, res: 480 }, normal: { fr: 240, nr: 360, res: 1440 }, low: { fr: 480, nr: 720, res: 2880 } };
const LADDER = [15, 30, 45, 60, 90, 120, 180, 240, 360, 480, 720, 960, 1440, 2160, 2880, 4320];
const targets = JSON.parse(JSON.stringify(DEFAULTS));

const TEAMS = ['Billing', 'Shipping', 'Integrations', 'Accounts'];
const AGENTS = { Billing: ['Ines Duarte', 'Callum Reyes'], Shipping: ['Priya Natarajan', 'Tomás Lindqvist'], Integrations: ['Ade Okafor', 'Mei Tanaka'], Accounts: ['Rosa Albescu', 'Jonah Pike'] };
const ME = 'Ines Duarte';
const SUBJECTS = {
  Billing: ['Invoice INV-20931 charged twice', 'VAT number missing from receipts', 'Credit note for a damaged parcel', 'Add four user seats mid-cycle', 'Downgrade plan before the renewal date', 'Card declined on annual renewal', 'Fuel surcharge missing from the export', 'Refund for a failed collection on 2 Oct'],
  Shipping: ['Collection booked for the wrong day', 'Tracking page shows yesterday’s ETA', 'Proof-of-delivery photo missing', 'Pallet dimensions rounding down', 'Customs form missing commodity codes', 'Label printer offline at the Leeds depot', 'Address check rejects Welsh place names', 'Driver app stuck on “syncing manifests”'],
  Integrations: ['Delivery webhook returning 401 since 09:40', 'Rate limit hit during peak picking', 'Bulk import rejects postcodes with spaces', 'Duplicate parcels after a CSV upload', 'Integration token expired overnight', 'Exception emails are not being sent', 'Order sync skipping split shipments', 'Manifest PDF cut off on A5 labels'],
  Accounts: ['SSO login loop for a new admin', 'Two-factor codes not arriving', 'Transfer account ownership to finance', 'Remove a former employee’s access', 'Pickup scheduler in the wrong timezone', 'Merge two warehouses into one account', 'Audit log export comes back empty', 'Cannot add a second depot address']
};
const CUSTOMERS = ['Fenwick Ceramics', 'Oakmoor Outdoor', 'Brindle & Co', 'Pellucid Skincare', 'Northgate Tools', 'Marram Surf Supply', 'Tallis Coffee Roasters', 'Quayside Books', 'Ember Lane Candles', 'Halvard Bikes', 'Copperleaf Tea', 'Wyvern Cycle Parts', 'Lumen Opticians', 'Saltash Kitchenware', 'Greyfriars Prints'];
const CHANNELS = ['Email', 'Chat', 'Phone', 'Web form'];
const ASKS = {
  urgent: 'Can someone pick this up straight away? It is blocking the team right now.',
  high: 'We need this sorted before tomorrow’s first collection, please.',
  normal: 'Not on fire, but it keeps catching the warehouse team out.',
  low: 'No rush at all — whenever someone has a moment.'
};
const NUDGE = 'Following up — we tried what you suggested and it is still happening. Screenshots attached.';

const START = 14 * 60 + 20;            /* Tue 6 Oct, 14:20 */
let now = START;
let nextId = 48190;
const deadline = (t) => t.start + targets[t.pri][t.metric];
const remain = (t) => deadline(t) - now;
const stateOf = (t) => { const r = remain(t); return r < 0 ? 'hot' : r < 60 ? 'warn' : 'ok'; };

function makeTicket(at, fresh) {
  const team = pick(TEAMS);
  const pri = weighted([['urgent', .12], ['high', .26], ['normal', .42], ['low', .2]]);
  const metric = fresh ? 'fr' : weighted([['fr', .42], ['nr', .36], ['res', .22]]);
  const target = DEFAULTS[pri][metric];
  const rem = fresh ? target : rnd() < .14 ? -Math.round(4 + rnd() * 150) : Math.round(target * (0.04 + rnd() * 0.94));
  const start = at + rem - target;
  const created = metric === 'nr' ? start - Math.round(80 + rnd() * 2400) : start;
  const unassigned = fresh || rnd() < (metric === 'fr' ? .55 : .12);
  return {
    id: nextId++, team, pri, metric, start, created,
    subject: pick(SUBJECTS[team]), customer: pick(CUSTOMERS), channel: pick(CHANNELS),
    assignee: unassigned ? null : pick(AGENTS[team]),
    msg: metric === 'nr' ? NUDGE : ASKS[pri]
  };
}
let tickets = [];
for (let i = 0; i < 46; i++) tickets.push(makeTicket(now, false));
const byId = (id) => tickets.find((t) => t.id === id);

/* last 7 days, per priority x clock, re-scored whenever a target changes */
const HIST = {};
PRI.forEach((p) => {
  HIST[p] = {};
  METRICS.forEach((m) => {
    const med = 0.42 + rnd() * 0.3, sd = 0.5 + rnd() * 0.2, n = 46 + Math.floor(rnd() * 40);
    HIST[p][m] = Array.from({ length: n }, () => Math.max(1, Math.round(DEFAULTS[p][m] * Math.exp(Math.log(med) + sd * gauss()))));
  });
});
const metRate = (p, m) => { const a = HIST[p][m]; return a.filter((v) => v <= targets[p][m]).length / a.length; };

/* ---------- formatting ---------- */
const pad = (n) => String(n).padStart(2, '0');
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const clock = (m) => { const x = ((Math.round(m) % 1440) + 1440) % 1440; return pad(Math.floor(x / 60)) + ':' + pad(x % 60); };
const dayOf = (m) => { const d = Math.floor(m / 1440); return { name: DAYS[(2 + d + 70) % 7], date: 6 + d }; };
const dayClock = (m) => (Math.floor(m / 1440) === Math.floor(now / 1440) ? 'today ' : dayOf(m).name + ' ') + clock(m);
const fmtDur = (m) => {
  m = Math.abs(Math.round(m));
  if (m < 60) return m + 'm';
  if (m < 1440) { const h = Math.floor(m / 60), r = m % 60; return r ? h + 'h ' + pad(r) + 'm' : h + 'h'; }
  const d = Math.floor(m / 1440), h = Math.floor((m % 1440) / 60);
  return h ? d + 'd ' + h + 'h' : d + 'd';
};
const fmtT = (m) => (m < 60 ? m + 'm' : m < 1440 ? (m % 60 ? Math.floor(m / 60) + 'h ' + (m % 60) + 'm' : m / 60 + 'h') : (m % 1440 ? Math.floor(m / 1440) + 'd ' + (m % 1440) / 60 + 'h' : m / 1440 + 'd'));
const relDue = (r) => (r < 0 ? fmtDur(r) + ' over' : 'in ' + fmtDur(r));

/* ---------- filters ---------- */
let team = 'all', unassignedOnly = false, speed = 1, view = 'runway', selId = null;
const metricOn = { fr: true, nr: true, res: true };
const passes = (t, ignoreTeam) => (ignoreTeam || team === 'all' || t.team === team) && metricOn[t.metric] && (!unassignedOnly || !t.assignee);
const visible = () => tickets.filter((t) => passes(t));

/* ---------- sidebar controls ---------- */
const teamsEl = $('.dsp-runway__teams');
['all'].concat(TEAMS).forEach((name) => {
  const b = document.createElement('button');
