const dots = new Map();
let railW = 0, introDone = false, zoneKey = '';
const zoneOf = (t) => { const r = remain(t); return r < -120 ? 'L' : r > 480 ? 'R' : 'M'; };
function dotLabel(t) {
  return `#${t.id}, ${PLABEL[t.pri]} ${MLABEL[t.metric].toLowerCase()}, due ${clock(deadline(t))}, ${t.assignee ? t.assignee : 'unassigned'}: ${t.subject}`;
