  PRI.forEach((p) => {
    const L = lanes[p];
    const list = vis.filter((t) => t.pri === p).sort((a, b) => deadline(a) - deadline(b));
    const left = [], right = [], rows = [];
    L.order = [];
    for (const t of list) {
      const z = zoneOf(t);
      if (z === 'L') { left.push(t); continue; }
      if (z === 'R') { right.push(t); continue; }
      const d = deadline(t);
      let row = rows.findIndex((last) => d - last >= gap);
      if (row < 0) { row = rows.length; rows.push(d); } else rows[row] = d;
      let b = dots.get(t.id);
      const fresh = !b;
      if (fresh) {
        b = document.createElement('button');
        b.type = 'button'; b.className = 'dsp-runway__tk'; b.tabIndex = -1; b.dataset.id = t.id;
        dots.set(t.id, b);
