      if (fresh && introDone && !RM) {
        b.classList.add('is-new');
        b.addEventListener('animationend', () => b.classList.remove('is-new'), { once: true });
      }
      seen.add(t.id);
      placed.push(t);
      L.order.push(t);
    }
    L.el.style.setProperty('--rows', Math.max(1, rows.length));
    L.count.textContent = list.length + ' open';
    L.overs.innerHTML =
      (left.length ? `<button type="button" class="dsp-runway__over is-left" data-go="${left[0].id}" title="${left.length} breached more than 2 hours ago — open the oldest">◂ ${left.length}</button>` : '') +
      (right.length ? `<button type="button" class="dsp-runway__over is-right" data-go="${right[0].id}" title="${right.length} due after 8 hours — open the next one">${right.length} ▸</button>` : '');
  });
  placed.sort((a, b) => deadline(a) - deadline(b)).forEach((t, i) => dots.get(t.id).style.setProperty('--i', i));
