  const breached = vis.filter((t) => remain(t) < 0).sort((a, b) => remain(a) - remain(b));
  const risk = vis.filter((t) => { const r = remain(t); return r >= 0 && r < 60; }).sort((a, b) => remain(a) - remain(b));
  const orphan = vis.filter((t) => !t.assignee && remain(t) < 60);
  setK('track', onRunway.length);
  setK('trackSub', `${vis.length - onRunway.length} more due after 8h`);
  setK('breached', breached.length);
  setK('breachedSub', breached.length ? `oldest ${fmtDur(remain(breached[0]))} over` : 'none right now');
  setK('risk', risk.length);
  setK('riskSub', risk.length ? `next #${risk[0].id} in ${fmtDur(remain(risk[0]))}` : 'nothing inside the hour');
  setK('orphan', orphan.length);
