  const pi = PRI.indexOf(t.pri);
  const list = lanes[t.pri].order;
  const i = list.findIndex((x) => x.id === t.id);
  let to = null;
  if (e.key === 'ArrowRight') to = list[i + 1];
  else if (e.key === 'ArrowLeft') to = list[i - 1];
  else if (e.key === 'Home') to = list[0];
  else if (e.key === 'End') to = list[list.length - 1];
  else if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
    const dir = e.key === 'ArrowUp' ? -1 : 1;
    for (let q = pi + dir; q >= 0 && q < PRI.length && !to; q += dir) {
      const o = lanes[PRI[q]].order;
      if (o.length) to = o.reduce((best, x) => Math.abs(deadline(x) - deadline(t)) < Math.abs(deadline(best) - deadline(t)) ? x : best, o[0]);
    }
