/* ---------- detail ---------- */
const body = $('.dsp-runway__dbody');
const nextList = () => visible().filter((t) => remain(t) >= 0 && t.id !== selId).sort((a, b) => remain(a) - remain(b)).slice(0, 5);
function nextHTML() {
