/* ---------- age view ---------- */
const BUCKETS = [['Under 1h', 0, 60], ['1–4h', 60, 240], ['4–8h', 240, 480], ['8–24h', 480, 1440], ['1–3d', 1440, 4320], ['Over 3d', 4320, 1e9]];
const bucketColor = (i) => `color-mix(in oklch, var(--dsp-runway-ok), var(--dsp-runway-hot) ${i * 20}%)`;
$('.dsp-runway__agekey').innerHTML = BUCKETS.map((b, i) => `<li style="--c:${bucketColor(i)}"><i></i>${b[0]}</li>`).join('');
function niceStep(max, target) {
  const raw = max / target, p = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / p;
  return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10) * p;
}
function renderAge() {
  const vis = visible();
  const teamsShown = team === 'all' ? TEAMS : [team];
  const rows = teamsShown.map((tm) => {
    const ts = vis.filter((t) => t.team === tm);
    const ages = ts.map((t) => now - t.created).sort((a, b) => a - b);
    const segs = BUCKETS.map((b) => ages.filter((a) => a >= b[1] && a < b[2]).length);
    const oldest = ts.slice().sort((a, b) => a.created - b.created)[0];
    const med = ages.length ? (ages.length % 2 ? ages[(ages.length - 1) / 2] : (ages[ages.length / 2 - 1] + ages[ages.length / 2]) / 2) : 0;
    return { tm, n: ts.length, segs, oldest, med };
  });
  const box = $('.dsp-runway__agechart');
  const svg = $('svg', box);
  svg.innerHTML = '';
  const W = Math.max(300, box.clientWidth), lw = W < 480 ? 86 : 104, rowH = 34, top = 6, H = top + rows.length * rowH + 24;
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const max = Math.max(4, ...rows.map((r) => r.n));
  const step = niceStep(max, 5), xmax = Math.ceil(max / step) * step;
  const x = (v) => lw + (v / xmax) * (W - lw - 36);
  const ax = svgEl('g', { class: 'ax' }, svg);
  for (let v = 0; v <= xmax; v += step) {
    svgEl('line', { x1: x(v), x2: x(v), y1: top - 2, y2: H - 20 }, ax);
    svgEl('text', { x: x(v), y: H - 6, 'text-anchor': 'middle' }, ax).textContent = v;
  }
  let i = 0;
  rows.forEach((r, ri) => {
    const y = top + ri * rowH + 6;
    svgEl('text', { class: 'lb', x: 0, y: y + 15 }, svg).textContent = r.tm;
    let acc = 0;
    r.segs.forEach((n, si) => {
      if (!n) return;
      const rect = svgEl('rect', { class: 'seg', x: x(acc), y, width: Math.max(1, x(acc + n) - x(acc) - 1.5), height: 22, rx: 3, fill: bucketColor(si), style: `--i:${i++}` }, svg);
      rect.dataset.tip = `${r.tm} · ${BUCKETS[si][0]}|${n} of ${r.n} open tickets (${Math.round((n / r.n) * 100)}%)`;
      acc += n;
    });
    svgEl('text', { class: 'tot', x: x(r.n) + 6, y: y + 15 }, svg).textContent = r.n;
  });
  $('.dsp-runway__agetable tbody').innerHTML = rows.map((r) => `<tr><td>${r.tm}</td><td class="n">${r.n}</td><td class="n">${r.n ? fmtDur(r.med) : '—'}</td><td>${r.oldest ? `<button type="button" data-go="${r.oldest.id}">#${r.oldest.id} <small>${fmtDur(now - r.oldest.created)} · ${esc(r.oldest.customer)}</small></button>` : '<span>—</span>'}</td></tr>`).join('');
}
$('.dsp-runway__agechart').addEventListener('pointerover', (e) => {
  const s = e.target.closest('rect.seg'); if (!s) return;
  const [a, b] = s.dataset.tip.split('|');
  showTip(s, `<b>${a}</b><small>${b}</small>`);
});
$('.dsp-runway__agechart').addEventListener('pointerout', hideTip);
$('.dsp-runway__agetable').addEventListener('click', (e) => {
  const b = e.target.closest('[data-go]'); if (!b) return;
  const t = byId(+b.dataset.go);
  if (t && !passes(t)) return;
  select(+b.dataset.go, true);
  const d = dots.get(selId); if (d) d.focus({ preventScroll: true });
});

/* ---------- policy view ---------- */
const polEl = $('.dsp-runway__poltable');
let polSel = { p: 'urgent', m: 'fr' };
function renderPolicy() {
  polEl.innerHTML = '<span></span>' + METRICS.map((m) => `<span class="h">${MLABEL[m]}</span>`).join('') +
    PRI.map((p) => `<span class="r" style="--pc:${PCOL[p]}">${PLABEL[p]}</span>` + METRICS.map((m) => {
      const v = targets[p][m], li = LADDER.indexOf(v), rate = metRate(p, m);
      const cur = polSel.p === p && polSel.m === m;
      return `<div class="dsp-runway__cell${v !== DEFAULTS[p][m] ? ' is-changed' : ''}" role="group" aria-label="${PLABEL[p]} ${MLABEL[m].toLowerCase()}">
        <button type="button" class="dsp-runway__step" data-p="${p}" data-m="${m}" data-dir="-1" aria-label="Shorten ${PLABEL[p]} ${MLABEL[m].toLowerCase()} target"${li <= 0 ? ' disabled title="15 minutes is the shortest target allowed"' : ''}><svg viewBox="0 0 12 12"><path d="M2.5 6h7"/></svg></button>
        <button type="button" class="dsp-runway__pick" data-p="${p}" data-m="${m}"${cur ? ' aria-current="true"' : ''} tabindex="${cur ? 0 : -1}" aria-label="${PLABEL[p]} ${MLABEL[m].toLowerCase()}: ${fmtT(v)}, ${Math.round(rate * 100)}% met last week"><b>${fmtT(v)}</b><small>${Math.round(rate * 100)}% met</small></button>
        <button type="button" class="dsp-runway__step" data-p="${p}" data-m="${m}" data-dir="1" aria-label="Lengthen ${PLABEL[p]} ${MLABEL[m].toLowerCase()} target"${li >= LADDER.length - 1 ? ' disabled title="3 days is the longest target allowed"' : ''}><svg viewBox="0 0 12 12"><path d="M2.5 6h7M6 2.5v7"/></svg></button>
        <span class="dsp-runway__met"><i style="--m:${rate.toFixed(3)};--mc:${rate >= 0.9 ? 'var(--dsp-runway-ok)' : rate >= 0.75 ? 'var(--dsp-runway-accent)' : 'var(--dsp-runway-hot)'}"></i></span>
      </div>`;
    }).join('')).join('');
  const changed = PRI.some((p) => METRICS.some((m) => targets[p][m] !== DEFAULTS[p][m]));
  const rs = $('.dsp-runway__reset');
  rs.disabled = !changed;
  rs.title = changed ? 'Put every target back to the policy defaults' : 'Targets already match the defaults';
  renderPolChart();
}
function renderPolChart(note) {
  const { p, m } = polSel, data = HIST[p][m], tgt = targets[p][m];
  const rate = metRate(p, m);
  const affected = tickets.filter((t) => t.pri === p && t.metric === m).length;
  $('.dsp-runway__polt').textContent = `${PLABEL[p]} · ${MLABEL[m]} — last 7 days`;
  $('.dsp-runway__pols').textContent = note || `${data.length} tickets · ${Math.round(rate * 100)}% inside ${fmtT(tgt)} · ${affected} open ticket${affected === 1 ? '' : 's'} run on this clock`;
  const box = $('.dsp-runway__polplot'), svg = $('svg', box);
  svg.innerHTML = '';
  const W = Math.max(300, box.clientWidth), H = 150, l = 28, b = 22, t = 18;
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const xmax = Math.max(tgt * 2.2, Math.max(...data) * 1.02);
  const nb = 28, bw = xmax / nb;
  const counts = Array(nb).fill(0);
  data.forEach((v) => { counts[Math.min(nb - 1, Math.floor(v / bw))]++; });
  const ymax = Math.max(4, ...counts);
  const x = (v) => l + (v / xmax) * (W - l - 8), y = (v) => H - b - (v / ymax) * (H - b - t);
  const ax = svgEl('g', { class: 'ax' }, svg);
  const ys = niceStep(ymax, 3);
  for (let v = 0; v <= ymax; v += ys) { svgEl('line', { x1: l, x2: W - 8, y1: y(v), y2: y(v) }, ax); svgEl('text', { x: l - 6, y: y(v) + 3, 'text-anchor': 'end' }, ax).textContent = v; }
  const xs = niceStep(xmax, W < 480 ? 4 : 7);
  for (let v = 0; v <= xmax; v += xs) svgEl('text', { x: x(v), y: H - 6, 'text-anchor': 'middle' }, ax).textContent = v === 0 ? '0' : fmtT(Math.round(v));
  counts.forEach((c, i) => {
    if (!c) return;
    const mid = (i + 0.5) * bw;
    svgEl('rect', { class: 'b ' + (mid <= tgt ? 'in' : 'out'), x: x(i * bw) + 1, y: y(c), width: Math.max(1, x(bw) - x(0) - 2), height: y(0) - y(c), rx: 2, style: `--i:${i}` }, svg);
  });
  svgEl('line', { class: 'tl', x1: x(tgt), x2: x(tgt), y1: t - 6, y2: H - b }, svg);
  const tt = svgEl('text', { class: 'tt', x: x(tgt) + 6, y: t - 2 }, svg);
  tt.textContent = `target ${fmtT(tgt)} · ${Math.round(rate * 100)}% met`;
  if (x(tgt) > W * 0.62) { tt.setAttribute('text-anchor', 'end'); tt.setAttribute('x', x(tgt) - 6); }
}
polEl.addEventListener('click', (e) => {
  const st = e.target.closest('.dsp-runway__step');
  const pk = e.target.closest('.dsp-runway__pick');
  if (pk) { polSel = { p: pk.dataset.p, m: pk.dataset.m }; renderPolicy(); $(`.dsp-runway__pick[data-p="${polSel.p}"][data-m="${polSel.m}"]`, polEl).focus(); return; }
  if (!st || st.disabled) return;
  const { p, m } = st.dataset, dir = +st.dataset.dir;
  const li = LADDER.indexOf(targets[p][m]);
  const before = targets[p][m];
  targets[p][m] = LADDER[Math.max(0, Math.min(LADDER.length - 1, li + dir))];
  polSel = { p, m };
  const n = tickets.filter((t) => t.pri === p && t.metric === m).length;
  layout();
  renderPolicy();
  const again = $(`.dsp-runway__step[data-p="${p}"][data-m="${m}"][data-dir="${dir}"]`, polEl);
  (again && !again.disabled ? again : $(`.dsp-runway__pick[data-p="${p}"][data-m="${m}"]`, polEl)).focus();
  renderPolChart(`${fmtT(before)} → ${fmtT(targets[p][m])}: ${Math.round(metRate(p, m) * 100)}% of last week would have met it · ` + (n ? `${n} open ticket${n === 1 ? '' : 's'} re-derived ${n === 1 ? 'its' : 'their'} deadline` : 'no open ticket runs on this clock right now'));
});
polEl.addEventListener('keydown', (e) => {
  const pk = e.target.closest('.dsp-runway__pick'); if (!pk) return;
  let pi = PRI.indexOf(pk.dataset.p), mi = METRICS.indexOf(pk.dataset.m);
  if (e.key === 'ArrowRight') mi = Math.min(2, mi + 1);
  else if (e.key === 'ArrowLeft') mi = Math.max(0, mi - 1);
  else if (e.key === 'ArrowDown') pi = Math.min(3, pi + 1);
  else if (e.key === 'ArrowUp') pi = Math.max(0, pi - 1);
  else return;
  e.preventDefault();
  polSel = { p: PRI[pi], m: METRICS[mi] };
  renderPolicy();
  $(`.dsp-runway__pick[data-p="${polSel.p}"][data-m="${polSel.m}"]`, polEl).focus();
});
$('.dsp-runway__reset').addEventListener('click', () => {
  PRI.forEach((p) => METRICS.forEach((m) => { targets[p][m] = DEFAULTS[p][m]; }));
  layout(); renderPolicy();
  toast('Every target is back on the policy defaults.');
});

/* ---------- simulation ---------- */
function simMinute() {
  now += 1;
  const n = tickets.length;
  if (rnd() < (n < 34 ? 16 : 9) / 60) {
    const t = makeTicket(now, true);
    tickets.push(t);
    setEvent(`<b>${clock(now)}</b> New #${t.id} · ${t.team} · ${PLABEL[t.pri].toLowerCase()} · ${esc(t.subject)}`);
  }
  if (rnd() < (n > 58 ? 14 : 8) / 60) {
    const pool = tickets.filter((t) => t.assignee && t.id !== selId && t.assignee !== ME);
    if (pool.length) {
      const w = pool.map((t) => 1 / (Math.max(remain(t), -60) + 90));
      let r = rnd() * w.reduce((a, b) => a + b, 0), k = 0;
      while ((r -= w[k]) > 0 && k < pool.length - 1) k++;
      const t = pool[k];
      tickets.splice(tickets.indexOf(t), 1);
      setEvent(`<b>${clock(now)}</b> ${esc(t.assignee)} replied to #${t.id} — clock stopped`);
    }
  }
  if (rnd() < 5 / 60) {
    const un = tickets.filter((t) => !t.assignee && t.id !== selId).sort((a, b) => remain(a) - remain(b))[0];
    if (un) { un.assignee = pick(AGENTS[un.team].filter((a) => a !== ME)); setEvent(`<b>${clock(now)}</b> ${esc(un.assignee)} picked up #${un.id}`); }
  }
}
function refreshAll() {
  if (view === 'runway') layout(); else { kpis(); teamCounts(); hist(); }
  if (view === 'age') renderAge();
  if (!byId(selId) || !passes(byId(selId))) { const nx = nextList()[0]; selId = nx ? nx.id : null; syncCurrent(); }
  renderDetail();
}
const nowLabel = $('.dsp-runway__axisrail .is-now small');
const clockEl = $('.dsp-runway__clock time'), dayEl = $('.dsp-runway__clock small');
function paintClock() {
  root.style.setProperty('--dsp-runway-now', now);
  const c = clock(now);
  clockEl.textContent = c;
  nowLabel.textContent = c;
  const d = dayOf(now), ds = `${d.name} ${d.date} Oct`;
  if (dayEl.textContent !== ds) dayEl.textContent = ds;
}
function tick() {
  const before = tickets.map((t) => t.id + (t.assignee ? 'a' : 'u')).join();
  for (let s = 0; s < speed; s++) simMinute();
  paintClock();
  const after = tickets.map((t) => t.id + (t.assignee ? 'a' : 'u')).join();
  const key = visible().map((t) => t.id + zoneOf(t)).join();
  if (after !== before || key !== zoneKey) {
    if (view === 'runway') layout(); else { kpis(); hist(); teamCounts(); }
    if (!byId(selId)) { renderDetail(); }
  } else {
    for (const [id, b] of dots) { const t = byId(id); if (t) paintDot(b, t); }
    hist(); kpis();
  }
  live();
}

/* ---------- boot ---------- */
paintClock();
syncMetricLock();
const firstRisk = visible().filter((t) => remain(t) >= 0).sort((a, b) => remain(a) - remain(b))[0];
selId = firstRisk ? firstRisk.id : null;
if (!RM) lanesEl.classList.add('is-intro');
layout();
renderDetail();
setTimeout(() => { introDone = true; lanesEl.classList.remove('is-intro'); }, 1600);

let onScreen = true;
const io = new IntersectionObserver((es) => { onScreen = es[es.length - 1].isIntersecting; });
io.observe(root);
const ro = new ResizeObserver(() => {
  const w = lanes.urgent.rail.clientWidth;
  if (w && Math.abs(w - railW) > 2 && view === 'runway') layout();
  if (view === 'age') renderAge();
  if (view === 'policy') renderPolChart();
});
ro.observe($('.dsp-runway__main'));
const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); io.disconnect(); ro.disconnect(); return; }
  if (document.hidden || !onScreen || !speed) return;
  tick();
}, 1000);

css:
.dsp-verbatim {
  /* re-theme with these four */
  --dsp-verbatim-bg: oklch(0.972 0.011 84);
  --dsp-verbatim-ink: oklch(0.255 0.022 48);
  --dsp-verbatim-pos: oklch(0.53 0.085 178);
  --dsp-verbatim-neg: oklch(0.6 0.155 36);
  /* derived */
  --dsp-verbatim-card: color-mix(in oklch, var(--dsp-verbatim-bg), white 62%);
  --dsp-verbatim-line: color-mix(in oklch, var(--dsp-verbatim-ink) 13%, transparent);
  --dsp-verbatim-hair: color-mix(in oklch, var(--dsp-verbatim-ink) 7%, transparent);
  --dsp-verbatim-mute: color-mix(in oklch, var(--dsp-verbatim-ink) 66%, var(--dsp-verbatim-bg));
  --dsp-verbatim-faint: color-mix(in oklch, var(--dsp-verbatim-ink) 46%, var(--dsp-verbatim-bg));
  --dsp-verbatim-r1: var(--dsp-verbatim-neg);
  --dsp-verbatim-r2: color-mix(in oklch, var(--dsp-verbatim-neg) 52%, var(--dsp-verbatim-bg));
  --dsp-verbatim-r3: color-mix(in oklch, var(--dsp-verbatim-ink) 17%, var(--dsp-verbatim-bg));
  --dsp-verbatim-r4: color-mix(in oklch, var(--dsp-verbatim-pos) 50%, var(--dsp-verbatim-bg));
  --dsp-verbatim-r5: var(--dsp-verbatim-pos);
  --dsp-verbatim-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dsp-verbatim-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dsp-verbatim-out: cubic-bezier(.16, 1, .3, 1);
  --dsp-verbatim-spring: linear(0, .07 2.5%, .27 6.5%, .6 12%, .9 18.5%, 1.05 25%, 1.08 31%, 1.04 39%, 1.005 50%, .998 64%, 1);
  width: 100%;
  height: var(--dsp-verbatim-h, 680px);
  container-type: inline-size;
  container-name: dsp-verbatim;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background: var(--dsp-verbatim-bg);
  color: var(--dsp-verbatim-ink);
  font: 13px/1.45 var(--dsp-verbatim-sans);
  color-scheme: light;
  accent-color: var(--dsp-verbatim-pos);
  box-shadow: inset 0 0 0 1px var(--dsp-verbatim-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ul, ol) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(button:disabled) { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dsp-verbatim-pos); outline-offset: 2px; border-radius: 6px; }
  & svg { flex: none; }
}
.dsp-verbatim__app {
  height: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 372px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "head head" "main reader";
}

/* ---------------------------------------------------------------- header */
.dsp-verbatim__head {
  grid-area: head; display: flex; align-items: center; gap: 18px; padding: 14px 20px; border-bottom: 1px solid var(--dsp-verbatim-line);
}
.dsp-verbatim__brand {
  display: flex; align-items: center; gap: 10px; min-width: 0;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 50%; background: var(--dsp-verbatim-ink); stroke: var(--dsp-verbatim-bg); fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & span { display: grid; line-height: 1.2; }
  & b { font-weight: 720; letter-spacing: -.01em; }
  & small { font-size: 11px; color: var(--dsp-verbatim-faint); }
}
.dsp-verbatim__tabs {
  display: flex; gap: 2px; margin-left: 8px;
  & button { position: relative; height: 32px; padding: 0 12px; font-weight: 620; color: var(--dsp-verbatim-mute); border-radius: 8px; transition: color .15s; }
  & button::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: -15px; height: 2px; border-radius: 2px; background: var(--dsp-verbatim-ink); scale: 0 1; transition: scale .35s var(--dsp-verbatim-out); }
  & button:hover { color: var(--dsp-verbatim-ink); }
  & button[aria-selected="true"] { color: var(--dsp-verbatim-ink); }
  & button[aria-selected="true"]::after { scale: 1 1; }
}
.dsp-verbatim__ctl { margin-left: auto; display: flex; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
.dsp-verbatim__seg, .dsp-verbatim__sort {
  display: flex; padding: 2px; border-radius: 9px; background: color-mix(in oklch, var(--dsp-verbatim-ink) 5%, var(--dsp-verbatim-bg)); box-shadow: inset 0 0 0 1px var(--dsp-verbatim-hair);
  & button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dsp-verbatim-mute); white-space: nowrap; transition: background-color .15s, color .15s, box-shadow .15s; }
  & button:hover { color: var(--dsp-verbatim-ink); }
  & button[aria-checked="true"] { background: var(--dsp-verbatim-card); color: var(--dsp-verbatim-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dsp-verbatim-ink) 14%, transparent), inset 0 0 0 1px var(--dsp-verbatim-hair); }
}

/* ---------------------------------------------------------------- main */
.dsp-verbatim__main { grid-area: main; min-height: 0; min-width: 0; }
.dsp-verbatim__view {
  height: 100%; overflow: auto; padding: 16px 20px 20px; display: grid; gap: 14px; align-content: start;
  scrollbar-width: thin; scrollbar-color: var(--dsp-verbatim-line) transparent;
  &[hidden] { display: none; }
}
.dsp-verbatim__view:not([hidden]) > * { animation: dsp-verbatim-up .6s var(--dsp-verbatim-out) both; }
.dsp-verbatim__view > :nth-child(2) { animation-delay: 70ms; }
.dsp-verbatim__view > :nth-child(3) { animation-delay: 140ms; }
@keyframes dsp-verbatim-up { from { opacity: 0; translate: 0 10px; } }

.dsp-verbatim__eyebrow {
  font-size: 10.5px; font-weight: 680; letter-spacing: .1em; text-transform: uppercase; color: var(--dsp-verbatim-faint); display: flex; align-items: baseline;
  & > span { margin-left: .5em; }
  & em { font-style: normal; font-weight: 450; letter-spacing: 0; text-transform: none; font-size: 11px; margin-left: auto; padding-left: 10px; }
}
.dsp-verbatim__score {
  display: grid; grid-template-columns: minmax(180px, .8fr) minmax(0, 1.6fr); gap: 22px; align-items: stretch;
  padding-bottom: 14px; border-bottom: 1px solid var(--dsp-verbatim-line);
}
.dsp-verbatim__big { display: grid; align-content: start; gap: 2px; }
.dsp-verbatim__num {
  font-size: clamp(46px, 5.4cqi, 72px); font-weight: 260; letter-spacing: -.055em; line-height: .95; font-variant-numeric: tabular-nums;
  & small { font-size: .42em; font-weight: 400; letter-spacing: 0; color: var(--dsp-verbatim-faint); margin-left: 2px; }
}
.dsp-verbatim__line {
  font-size: 12.5px; color: var(--dsp-verbatim-mute); text-wrap: pretty; max-width: 34ch;
  & b { font-weight: 650; color: var(--dsp-verbatim-ink); }
  & .up, & .down { white-space: nowrap; font-weight: 650; }
  & .up { color: var(--dsp-verbatim-pos); }
  & .down { color: var(--dsp-verbatim-neg); }
}
.dsp-verbatim__dist { display: grid; gap: 10px; align-content: start; }
.dsp-verbatim__bands {
  display: flex; height: 46px; gap: 3px;
  & button {
    --c: var(--dsp-verbatim-r3);
    position: relative; min-width: 34px; flex: var(--w) 1 0; border-radius: 6px; background: var(--c); color: var(--dsp-verbatim-ink);
    display: grid; align-content: center; justify-items: start; padding: 0 8px; text-align: left; overflow: hidden;
    transition: flex-grow .7s var(--dsp-verbatim-out), opacity .2s, translate .25s var(--dsp-verbatim-spring);
    animation: dsp-verbatim-band .8s var(--dsp-verbatim-out) both; animation-delay: calc(var(--i) * 60ms + 120ms);
  }
  & button b { font: 650 12px var(--dsp-verbatim-sans); display: flex; align-items: center; gap: 3px; white-space: nowrap; }
  & button b svg { width: 10px; height: 10px; fill: currentColor; }
  & button small { font: 500 11px var(--dsp-verbatim-mono); font-variant-numeric: tabular-nums; opacity: .85; white-space: nowrap; }
  & button[data-r="1"] { --c: var(--dsp-verbatim-r1); color: white; }
  & button[data-r="2"] { --c: var(--dsp-verbatim-r2); }
  & button[data-r="4"] { --c: var(--dsp-verbatim-r4); }
  & button[data-r="5"] { --c: var(--dsp-verbatim-r5); color: white; }
