.dsp-verbatim__panel { display: grid; gap: 10px; }
.dsp-verbatim__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 6px 16px; flex-wrap: wrap;
  & h3 { font-size: 14px; font-weight: 700; letter-spacing: -.01em; display: flex; gap: 10px; align-items: baseline; text-wrap: balance; }
  & h3 span { font: 600 10.5px var(--dsp-verbatim-mono); color: var(--dsp-verbatim-faint); }
}
.dsp-verbatim__hint { font-size: 11.5px; color: var(--dsp-verbatim-faint); text-wrap: pretty; }
