.dsp-verbatim__key {
  display: inline-flex; align-items: center; gap: 6px; border-radius: 6px;
  & i { width: 14px; height: 3px; border-radius: 2px; background: var(--dsp-verbatim-pos); }
  &.is-topic i { background: var(--dsp-verbatim-ink); height: 0; border-top: 2px dashed var(--dsp-verbatim-ink); }
  &.is-topic b { font-weight: 600; color: var(--dsp-verbatim-ink); }
  &.is-vol i { width: 10px; height: 10px; border-radius: 2px; background: color-mix(in oklch, var(--dsp-verbatim-ink) 14%, transparent); }
  &.is-vol { padding: 2px 6px; margin: -2px -6px; transition: background-color .15s, opacity .15s; }
  &.is-vol:hover { background: var(--dsp-verbatim-hair); }
  &.is-vol[aria-pressed="false"] { opacity: .5; text-decoration: line-through; }
}
.dsp-verbatim__key[hidden] { display: none; }
.dsp-verbatim__trend {
  position: relative;
  & svg { display: block; width: 100%; height: 190px; overflow: visible; }
  & .grid line { stroke: var(--dsp-verbatim-hair); }
  & .grid text, & .xl text { font: 500 10.5px var(--dsp-verbatim-mono); fill: var(--dsp-verbatim-faint); font-variant-numeric: tabular-nums; }
  & .vol rect { fill: color-mix(in oklch, var(--dsp-verbatim-ink) 9%, transparent); transform-box: fill-box; transform-origin: bottom; animation: dsp-verbatim-grow .7s var(--dsp-verbatim-out) both; animation-delay: calc(var(--i) * 18ms); transition: opacity .3s; }
  & .vol.is-off rect { opacity: 0; }
  & .tgt { stroke: var(--dsp-verbatim-neg); stroke-width: 1; stroke-dasharray: 3 4; opacity: .7; }
  & .tgtl { font: 600 10.5px var(--dsp-verbatim-sans); fill: var(--dsp-verbatim-neg); }
  & .area { fill: url(#dsp-verbatim-fade); opacity: 0; animation: dsp-verbatim-fadein .9s .5s var(--dsp-verbatim-out) forwards; }
  & .ln { fill: none; stroke: var(--dsp-verbatim-pos); stroke-width: 2.25; stroke-linejoin: round; stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dsp-verbatim-draw 1.1s .15s var(--dsp-verbatim-out) forwards; }
  & .tl { fill: none; stroke: var(--dsp-verbatim-ink); stroke-width: 1.75; stroke-dasharray: 5 4; stroke-linejoin: round; opacity: 0; animation: dsp-verbatim-fadein .5s .1s forwards; }
  & .pt { fill: var(--dsp-verbatim-card); stroke: var(--dsp-verbatim-pos); stroke-width: 2; }
  & .tpt { fill: var(--dsp-verbatim-ink); }
  & .xh { stroke: var(--dsp-verbatim-ink); stroke-width: 1; opacity: .35; }
  & .hit { fill: transparent; cursor: crosshair; }
}
@keyframes dsp-verbatim-draw { to { stroke-dashoffset: 0; } }
@keyframes dsp-verbatim-fadein { to { opacity: 1; } }
@keyframes dsp-verbatim-grow { from { scale: 1 0; } }

/* diverging drivers: zero line at --z (share of the scale left of neutral centre) */
.dsp-verbatim__drivers { --z: 30%; --lab: 168px; --stat: 92px; display: grid; gap: 4px; }
.dsp-verbatim__daxis {
  position: relative; height: 18px; margin-left: var(--lab); margin-right: var(--stat);
  & span { position: absolute; translate: -50% 0; font: 500 10.5px var(--dsp-verbatim-mono); color: var(--dsp-verbatim-faint); font-variant-numeric: tabular-nums; }
  & span.zero { color: var(--dsp-verbatim-ink); font-weight: 650; }
}
.dsp-verbatim__drows { display: grid; gap: 2px; }
.dsp-verbatim__drow {
  display: grid; grid-template-columns: var(--lab) minmax(0, 1fr) var(--stat); align-items: center; min-height: 40px;
  padding: 0; border-radius: 9px; text-align: left; transition: background-color .15s, opacity .3s;
  &:hover { background: var(--dsp-verbatim-hair); }
  & .nm { padding-left: 10px; display: grid; line-height: 1.25; min-width: 0; }
  & .nm b { font-weight: 620; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .nm small { font: 500 11px var(--dsp-verbatim-mono); color: var(--dsp-verbatim-faint); font-variant-numeric: tabular-nums; }
  & .track { position: relative; height: 20px; }
  & .track::before { content: ""; position: absolute; left: var(--z); top: -10px; bottom: -10px; width: 1px; background: var(--dsp-verbatim-ink); opacity: .55; }
  & .bar { position: absolute; inset: 0; animation: dsp-verbatim-open .9s var(--dsp-verbatim-out) both; animation-delay: calc(var(--i) * 55ms + 150ms); }
  & .bar i { position: absolute; top: 0; bottom: 0; left: var(--l); width: var(--w); background: var(--c); transition: left .6s var(--dsp-verbatim-out), width .6s var(--dsp-verbatim-out); }
  & .bar i:first-child { border-radius: 4px 0 0 4px; }
  & .bar i:last-child { border-radius: 0 4px 4px 0; }
  & .st { text-align: right; padding-right: 10px; display: grid; line-height: 1.2; }
  & .st b { font: 650 14px var(--dsp-verbatim-sans); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & .st small { font: 600 10.5px var(--dsp-verbatim-mono); font-variant-numeric: tabular-nums; }
  & .st .up { color: var(--dsp-verbatim-pos); }
  & .st .down { color: var(--dsp-verbatim-neg); }
  &[aria-pressed="true"] { background: var(--dsp-verbatim-card); box-shadow: inset 0 0 0 1.5px var(--dsp-verbatim-ink); }
}
.dsp-verbatim__drows:has(.dsp-verbatim__drow[aria-pressed="true"]) .dsp-verbatim__drow:not([aria-pressed="true"]) { opacity: .42; }
@keyframes dsp-verbatim-open { from { clip-path: inset(-2px calc(100% - var(--z)) -2px var(--z)); } to { clip-path: inset(-2px 0 -2px 0); } }

/* ---------------------------------------------------------------- agents */
.dsp-verbatim__agents {
  width: 100%; border-collapse: collapse; font-size: 12.5px;
  & th { text-align: left; font-size: 10.5px; font-weight: 680; letter-spacing: .08em; text-transform: uppercase; color: var(--dsp-verbatim-faint); padding: 0 8px 8px; border-bottom: 1px solid var(--dsp-verbatim-line); white-space: nowrap; }
  & th button { text-transform: inherit; letter-spacing: inherit; font-weight: inherit; display: inline-flex; gap: 4px; align-items: center; border-radius: 4px; }
  & th button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; border-top-color: currentColor; translate: 0 2px; opacity: 0; transition: rotate .25s var(--dsp-verbatim-out), opacity .15s; }
