  & th[aria-sort="descending"] button::after { opacity: 1; }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: 180deg; translate: 0 -2px; }
  & .n { text-align: right; }
  & th.n button { flex-direction: row-reverse; }
  & td { padding: 8px; border-bottom: 1px solid var(--dsp-verbatim-hair); font-variant-numeric: tabular-nums; }
  & td.n { font-family: var(--dsp-verbatim-mono); font-size: 12px; }
  & tbody tr { cursor: pointer; transition: background-color .15s; }
  & tbody tr:hover { background: var(--dsp-verbatim-hair); }
  & tbody tr[aria-selected="true"] { background: var(--dsp-verbatim-card); box-shadow: inset 3px 0 0 var(--dsp-verbatim-ink); }
  & tbody tr:focus-visible { outline-offset: -2px; }
  & .who { display: flex; align-items: center; gap: 9px; font-weight: 620; white-space: nowrap; }
  & .av { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-size: 10px; font-weight: 700; background: color-mix(in oklch, var(--h) 22%, var(--dsp-verbatim-bg)); color: color-mix(in oklch, var(--h), black 30%); }
  & .mini { display: flex; height: 8px; width: 120px; border-radius: 4px; overflow: hidden; gap: 1px; }
  & .mini i { background: var(--c); width: var(--w); }
  & .up { color: var(--dsp-verbatim-pos); }
  & .down { color: var(--dsp-verbatim-neg); }
  & .tag { font-size: 11.5px; color: var(--dsp-verbatim-mute); white-space: nowrap; }
}

/* ---------------------------------------------------------------- reader */
.dsp-verbatim__reader {
  grid-area: reader; min-height: 0; display: flex; flex-direction: column; border-left: 1px solid var(--dsp-verbatim-line);
  background: color-mix(in oklch, var(--dsp-verbatim-bg), var(--dsp-verbatim-ink) 3%);
}
.dsp-verbatim__rh {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; padding: 14px 16px 8px;
  & h3 { font-size: 13.5px; font-weight: 700; display: flex; align-items: center; gap: 8px; }
  & h3 b { font: 600 11px var(--dsp-verbatim-mono); padding: 1px 7px; border-radius: 99px; background: var(--dsp-verbatim-ink); color: var(--dsp-verbatim-bg); font-variant-numeric: tabular-nums; }
}
.dsp-verbatim__chips {
  display: flex; flex-wrap: wrap; gap: 6px; padding: 0 16px 8px;
  &:empty { display: none; }
  & button { display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 6px 0 10px; border-radius: 99px; font-size: 11.5px; font-weight: 600; background: var(--dsp-verbatim-ink); color: var(--dsp-verbatim-bg); animation: dsp-verbatim-chip .35s var(--dsp-verbatim-spring) both; }
  & button svg { width: 14px; height: 14px; padding: 3px; border-radius: 50%; background: color-mix(in oklch, var(--dsp-verbatim-bg) 22%, transparent); stroke: currentColor; stroke-width: 2.4; fill: none; stroke-linecap: round; }
  & button:hover svg { background: color-mix(in oklch, var(--dsp-verbatim-bg) 38%, transparent); }
}
@keyframes dsp-verbatim-chip { from { opacity: 0; scale: .7; } }
.dsp-verbatim__list {
  flex: 1; min-height: 0; overflow: auto; padding: 4px 12px 16px; display: grid; gap: 8px; align-content: start;
  scrollbar-width: thin; scrollbar-color: var(--dsp-verbatim-line) transparent;
}
.dsp-verbatim__c {
  --s: var(--dsp-verbatim-r3);
  position: relative; padding: 11px 12px 10px 14px; border-radius: 11px; background: var(--dsp-verbatim-card);
  box-shadow: 0 1px 0 var(--dsp-verbatim-hair), inset 0 0 0 1px var(--dsp-verbatim-hair); display: grid; gap: 6px;
  &::before { content: ""; position: absolute; left: 0; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--s); }
  &[data-r="1"] { --s: var(--dsp-verbatim-r1); }
  &[data-r="2"] { --s: var(--dsp-verbatim-r2); }
  &[data-r="4"] { --s: var(--dsp-verbatim-r4); }
  &[data-r="5"] { --s: var(--dsp-verbatim-r5); }
  &.is-in { animation: dsp-verbatim-up .5s var(--dsp-verbatim-out) both; animation-delay: calc(var(--i) * 40ms); }
  & header { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--dsp-verbatim-faint); }
  & header time { font-variant-numeric: tabular-nums; }
  & header span:last-child { margin-left: auto; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .stars { display: inline-flex; gap: 1px; }
  & .stars svg { width: 11px; height: 11px; fill: var(--dsp-verbatim-line); }
  & .stars svg.on { fill: var(--s); }
  & p { font-size: 13px; line-height: 1.5; text-wrap: pretty; }
  & mark { color: inherit; padding: 0 1px; background: linear-gradient(transparent 52%, color-mix(in oklch, var(--s) 30%, transparent) 52% 92%, transparent 92%); }
  & footer { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; font-size: 11px; color: var(--dsp-verbatim-faint); }
  & .tag { padding: 1px 7px; border-radius: 99px; background: var(--dsp-verbatim-hair); color: var(--dsp-verbatim-mute); font-weight: 600; }
  & .acts { margin-left: auto; display: flex; gap: 4px; }
}
.dsp-verbatim__mini {
  display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 8px; border-radius: 7px; font-size: 11.5px; font-weight: 620; color: var(--dsp-verbatim-mute);
  box-shadow: inset 0 0 0 1px var(--dsp-verbatim-line); transition: background-color .15s, color .15s, box-shadow .15s;
  & svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover:not(:disabled) { color: var(--dsp-verbatim-ink); background: var(--dsp-verbatim-hair); }
  &[aria-pressed="true"] { background: var(--dsp-verbatim-ink); color: var(--dsp-verbatim-bg); box-shadow: none; }
  &:disabled { color: var(--dsp-verbatim-pos); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dsp-verbatim-pos) 40%, transparent); }
}
.dsp-verbatim__more {
  height: 34px; border-radius: 9px; font-weight: 620; font-size: 12px; color: var(--dsp-verbatim-mute); box-shadow: inset 0 0 0 1px var(--dsp-verbatim-line);
  &:hover:not(:disabled) { color: var(--dsp-verbatim-ink); background: var(--dsp-verbatim-hair); }
  &:disabled { opacity: .55; }
}
.dsp-verbatim__none { padding: 28px 12px; text-align: center; color: var(--dsp-verbatim-faint); font-size: 12.5px; text-wrap: balance; }

/* ---------------------------------------------------------------- overlays */
.dsp-verbatim__tip {
  position: absolute; z-index: 30; left: 0; top: 0; min-width: 150px; padding: 8px 10px; border-radius: 9px; pointer-events: none;
  background: var(--dsp-verbatim-ink); color: var(--dsp-verbatim-bg); font-size: 11.5px; line-height: 1.45;
  box-shadow: 0 14px 30px -14px color-mix(in oklch, var(--dsp-verbatim-ink) 70%, transparent);
  & b { display: block; font-size: 12px; }
  & .r { display: flex; justify-content: space-between; gap: 14px; font-variant-numeric: tabular-nums; }
  & .r span { opacity: .7; }
  &:not([hidden]) { animation: dsp-verbatim-tip .15s var(--dsp-verbatim-out); }
}
@keyframes dsp-verbatim-tip { from { opacity: 0; scale: .97; } }
.dsp-verbatim__toast {
  position: absolute; z-index: 40; right: 16px; bottom: 16px; max-width: min(340px, calc(100% - 32px)); padding: 10px 14px; border-radius: 11px;
  background: var(--dsp-verbatim-ink); color: var(--dsp-verbatim-bg); font-size: 12.5px; box-shadow: 0 16px 36px -16px color-mix(in oklch, var(--dsp-verbatim-ink) 80%, transparent);
  opacity: 0; translate: 0 10px; pointer-events: none; transition: opacity .2s, translate .35s var(--dsp-verbatim-spring);
  &.is-on { opacity: 1; translate: 0 0; }
}

/* ---------------------------------------------------------------- container responses */
@container dsp-verbatim (max-width: 1080px) {
  .dsp-verbatim__app { grid-template-columns: minmax(0, 1fr) 320px; }
  .dsp-verbatim__drivers { --lab: 140px; --stat: 80px; }
  .dsp-verbatim__agents .dsp-verbatim__c-top, .dsp-verbatim__agents td:nth-child(6) { display: none; }
}
@container dsp-verbatim (max-width: 959px) {
  .dsp-verbatim__head { flex-wrap: wrap; row-gap: 10px; }
  .dsp-verbatim__ctl { margin-left: 0; flex-basis: 100%; justify-content: flex-start; }
  .dsp-verbatim__tabs { margin-left: auto; }
  .dsp-verbatim__score { grid-template-columns: minmax(0, 1fr); gap: 12px; }
  .dsp-verbatim__agents .dsp-verbatim__c-dist, .dsp-verbatim__agents td:nth-child(4) { display: none; }
}
@container dsp-verbatim (max-width: 759px) {
  .dsp-verbatim__app { display: block; overflow: auto; scrollbar-width: thin; }
  .dsp-verbatim__head { padding: 12px 14px; }
  .dsp-verbatim__view { height: auto; overflow: visible; padding: 14px; }
  .dsp-verbatim__reader { border-left: 0; border-top: 1px solid var(--dsp-verbatim-line); }
  .dsp-verbatim__list { overflow: visible; }
  .dsp-verbatim__drivers { --lab: 112px; --stat: 64px; }
  .dsp-verbatim__drow .nm small { display: none; }
  .dsp-verbatim__eyebrow em { display: none; }
}
@container dsp-verbatim (max-width: 459px) {
  .dsp-verbatim__brand small { display: none; }
  .dsp-verbatim__drivers { --lab: 92px; --stat: 54px; }
  .dsp-verbatim__drow .st small { display: none; }
  .dsp-verbatim__stats dd { font-size: 15px; }
  .dsp-verbatim__bands button small { display: none; }
  .dsp-verbatim__daxis span:not(.zero):not(.edge) { display: none; }
  .dsp-verbatim__agents th:nth-child(5), .dsp-verbatim__agents td:nth-child(5) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .dsp-verbatim *, .dsp-verbatim *::before, .dsp-verbatim *::after { animation-duration: .001ms !important; animation-delay: 0s !important; }
  .dsp-verbatim .dsp-verbatim__bands button, .dsp-verbatim .dsp-verbatim__drow .bar i { transition: none; }
  .dsp-verbatim .dsp-verbatim__bands button:hover { translate: none; }
  .dsp-verbatim .dsp-verbatim__toast { transition: opacity .2s; translate: 0 0; }
}

