const draw = (p) => { let r = rnd(); for (let i = 0; i < p.length; i++) { if ((r -= p[i]) < 0) return i; } return p.length - 1; };
const mix = (a, b, k) => a.map((v, i) => v * (1 - k) + b[i] * k);

const TOPICS = [
  { k: 'delivery', name: 'Delivery & tracking', w: .28, p: [.06, .05, .08, .31, .50] },
  { k: 'assembly', name: 'Assembly & parts', w: .16, p: [.08, .07, .11, .32, .42] },
  { k: 'returns', name: 'Returns & refunds', w: .17, p: [.06, .05, .09, .32, .48] },
  { k: 'quality', name: 'Product quality', w: .13, p: [.04, .04, .09, .33, .50] },
  { k: 'agent', name: 'Agent helpfulness', w: .16, p: [.02, .02, .04, .26, .66] },
  { k: 'billing', name: 'Billing & payment', w: .10, p: [.04, .04, .08, .32, .52] }
];
const TBY = Object.fromEntries(TOPICS.map((t) => [t.k, t]));
const BAD = [.16, .11, .13, .27, .33];
function topicP(t, w) {
