@property --dsp-floor-nowp {
  syntax: "<percentage>";
  inherits: true;
  initial-value: 0%;
}
.dsp-floor {
  /* re-theme with these four */
  --dsp-floor-bg: oklch(0.984 0.005 160);
  --dsp-floor-ink: oklch(0.25 0.035 165);
  --dsp-floor-accent: oklch(0.56 0.12 158);
  --dsp-floor-warn: oklch(0.63 0.19 33);
  /* derived */
  --dsp-floor-card: #fff;
  --dsp-floor-line: color-mix(in oklch, var(--dsp-floor-ink) 12%, transparent);
  --dsp-floor-hair: color-mix(in oklch, var(--dsp-floor-ink) 6%, transparent);
  --dsp-floor-mute: color-mix(in oklch, var(--dsp-floor-ink) 64%, var(--dsp-floor-bg));
  --dsp-floor-faint: color-mix(in oklch, var(--dsp-floor-ink) 44%, var(--dsp-floor-bg));
  --dsp-floor-s-handle: var(--dsp-floor-accent);
  --dsp-floor-s-acw: color-mix(in oklch, var(--dsp-floor-accent) 48%, var(--dsp-floor-bg));
  --dsp-floor-s-avail: color-mix(in oklch, var(--dsp-floor-ink) 15%, var(--dsp-floor-bg));
  --dsp-floor-s-break: color-mix(in oklch, color-mix(in oklch, var(--dsp-floor-warn), oklch(0.8 0.14 80) 65%) 62%, var(--dsp-floor-bg));
  --dsp-floor-s-meet: color-mix(in oklch, oklch(0.58 0.11 255) 70%, var(--dsp-floor-bg));
  --dsp-floor-s-off: transparent;
  --dsp-floor-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dsp-floor-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dsp-floor-out: cubic-bezier(.2, .85, .25, 1);
  --dsp-floor-spring: linear(0, .08 2.6%, .3 7%, .64 12.5%, .93 19%, 1.06 25.5%, 1.08 31.5%, 1.04 40%, 1.005 52%, .998 66%, 1);
  --dsp-floor-nowp: 0%;
  width: 100%;
  height: var(--dsp-floor-h, 680px);
  container-type: inline-size;
  container-name: dsp-floor;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background: var(--dsp-floor-bg);
  color: var(--dsp-floor-ink);
  font: 13px/1.45 var(--dsp-floor-sans);
  color-scheme: light;
  accent-color: var(--dsp-floor-accent);
  box-shadow: inset 0 0 0 1px var(--dsp-floor-line);
  transition: --dsp-floor-nowp 1.15s linear;
  &.is-jump { transition-duration: .35s; transition-timing-function: var(--dsp-floor-out); }
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, ol) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button, input, textarea) { font: inherit; color: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(button:disabled) { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dsp-floor-accent); outline-offset: 2px; border-radius: 6px; }
  & svg { flex: none; }
}
.dsp-floor__app {
  height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) 286px;
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "head head" "kpis kpis" "main main";
}

/* ---------------------------------------------------------------- header */
.dsp-floor__head { grid-area: head; display: flex; align-items: center; gap: 12px 20px; padding: 16px 20px 10px; flex-wrap: wrap; }
.dsp-floor__title {
  min-width: 0; margin-right: auto;
  & h2 { font-size: clamp(19px, 1.5cqi + 6px, 24px); font-weight: 760; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; }
}
.dsp-floor__eyebrow { display: flex; align-items: center; gap: 8px; font-size: 11.5px; color: var(--dsp-floor-mute); margin-bottom: 2px; }
.dsp-floor__live {
  display: inline-flex; align-items: center; gap: 5px; height: 18px; padding: 0 7px 0 6px; border-radius: 99px;
  background: color-mix(in oklch, var(--dsp-floor-accent) 14%, var(--dsp-floor-bg)); color: color-mix(in oklch, var(--dsp-floor-accent), black 25%);
  font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;
  & i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; animation: dsp-floor-blink 1.6s ease-in-out infinite; }
  &[data-live="off"] { background: color-mix(in oklch, var(--dsp-floor-warn) 16%, var(--dsp-floor-bg)); color: color-mix(in oklch, var(--dsp-floor-warn), black 30%); }
  &[data-live="off"] i { animation: none; }
}
@keyframes dsp-floor-blink { 50% { opacity: .25; } }
.dsp-floor__teams {
  display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dsp-floor-card); box-shadow: inset 0 0 0 1px var(--dsp-floor-line);
  & button { height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--dsp-floor-mute); white-space: nowrap; transition: background-color .18s, color .18s; }
  & button:hover { color: var(--dsp-floor-ink); }
  & button[aria-selected="true"] { background: var(--dsp-floor-ink); color: var(--dsp-floor-bg); }
}
.dsp-floor__time { display: flex; align-items: center; gap: 8px; }
.dsp-floor__scrub {
  display: grid; gap: 1px; font-size: 11px; color: var(--dsp-floor-mute);
  & b { font: 650 12px var(--dsp-floor-mono); color: var(--dsp-floor-ink); font-variant-numeric: tabular-nums; }
  & input { width: 132px; margin: 0; height: 16px; }
}
.dsp-floor__btn {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px; border-radius: 8px; font-size: 12px; font-weight: 620; white-space: nowrap;
  background: var(--dsp-floor-card); box-shadow: inset 0 0 0 1px var(--dsp-floor-line); transition: background-color .15s, opacity .15s, scale .2s var(--dsp-floor-spring);
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--dsp-floor-card), var(--dsp-floor-ink) 5%); }
  &:active:not(:disabled) { scale: .96; }
  &:disabled { opacity: .45; }
  &[aria-pressed="true"] { background: var(--dsp-floor-ink); color: var(--dsp-floor-bg); box-shadow: none; }
  &.is-primary { background: var(--dsp-floor-accent); color: white; box-shadow: none; }
}

/* ---------------------------------------------------------------- kpis */
.dsp-floor__kpis {
  grid-area: kpis; display: grid; grid-template-columns: minmax(0, 1.6fr) repeat(3, minmax(0, 1fr)); gap: 10px; padding: 0 20px 12px;
}
.dsp-floor__now, .dsp-floor__kpi {
  padding: 10px 12px; border-radius: 12px; background: var(--dsp-floor-card); box-shadow: inset 0 0 0 1px var(--dsp-floor-hair), 0 1px 2px var(--dsp-floor-hair);
}
.dsp-floor__now {
  display: grid; gap: 8px; align-content: center;
  & p { font-size: 12px; color: var(--dsp-floor-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & p b { font: 700 15px var(--dsp-floor-sans); color: var(--dsp-floor-ink); font-variant-numeric: tabular-nums; }
}
.dsp-floor__stack {
  display: flex; gap: 2px; height: 22px;
  & span { flex: var(--n) 1 0; min-width: 0; border-radius: 5px; background: var(--c); display: grid; place-items: center; font: 650 11px var(--dsp-floor-mono); color: var(--dsp-floor-ink); transition: flex-grow .6s var(--dsp-floor-out); overflow: hidden; }
  & span[data-s="handle"] { color: white; }
}
.dsp-floor__kpi {
  display: grid; gap: 0; align-content: center;
  & span { font-size: 11px; font-weight: 600; color: var(--dsp-floor-mute); }
  & b { font: 700 clamp(19px, 1.3cqi + 8px, 25px)/1.15 var(--dsp-floor-sans); letter-spacing: -.035em; font-variant-numeric: tabular-nums; }
  & small { font-size: 10.5px; color: var(--dsp-floor-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}

/* ---------------------------------------------------------------- main */
.dsp-floor__main {
  grid-area: main; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 286px; gap: 12px; padding: 0 20px 18px;
}
.dsp-floor__tl {
  min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 14px; background: var(--dsp-floor-card);
  box-shadow: inset 0 0 0 1px var(--dsp-floor-hair), 0 1px 3px var(--dsp-floor-hair); overflow: hidden;
}
.dsp-floor__tlbar { display: flex; align-items: center; justify-content: space-between; gap: 8px 14px; padding: 10px 12px 6px; flex-wrap: wrap; }
.dsp-floor__states, .dsp-floor__metric {
  display: flex; gap: 2px; flex-wrap: wrap;
  & button { height: 25px; padding: 0 9px; border-radius: 99px; font-size: 11.5px; font-weight: 620; color: var(--dsp-floor-mute); white-space: nowrap; transition: background-color .15s, color .15s; }
  & button:hover { color: var(--dsp-floor-ink); background: var(--dsp-floor-hair); }
  & button[aria-checked="true"] { background: color-mix(in oklch, var(--dsp-floor-accent) 15%, var(--dsp-floor-card)); color: color-mix(in oklch, var(--dsp-floor-accent), black 35%); }
}
.dsp-floor__metric {
  display: grid; grid-template-columns: repeat(4, auto); justify-content: stretch;
  & button { padding: 0 7px; font-size: 11px; }
  & .sh { display: none; }
}
/* the board narrows to 240px below 1060px: short labels keep the four choices on one line */
@container dsp-floor (max-width: 1060px) and (min-width: 760px) {
  .dsp-floor__metric { & .lg { display: none; } & .sh { display: inline; } }
}
.dsp-floor__legend {
  display: flex; gap: 10px; flex-wrap: wrap; font-size: 11px; color: var(--dsp-floor-mute);
  & li { display: inline-flex; align-items: center; gap: 5px; }
  & li::before { content: ""; width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & li.dev::before { height: 3px; border-radius: 2px; background: var(--dsp-floor-warn); }
}
.dsp-floor__scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dsp-floor-line) transparent; position: relative; }
.dsp-floor__axis, .dsp-floor__row {
  display: grid; grid-template-columns: var(--dsp-floor-who, 216px) minmax(0, 1fr) var(--dsp-floor-stw, 78px); align-items: center;
}
.dsp-floor__axis {
  position: sticky; top: 0; z-index: 3; height: 26px; background: color-mix(in oklch, var(--dsp-floor-card) 92%, transparent); backdrop-filter: blur(6px);
  border-bottom: 1px solid var(--dsp-floor-line);
  & .dsp-floor__axl, & .dsp-floor__axs { font-size: 10px; font-weight: 680; letter-spacing: .08em; text-transform: uppercase; color: var(--dsp-floor-faint); padding-left: 12px; }
  & .dsp-floor__axs { text-align: right; padding: 0 12px 0 0; }
}
.dsp-floor__axr {
  position: relative; height: 100%;
