function stats(a, T) {
  const o = { handle: 0, acw: 0, avail: 0, break: 0, meet: 0, handled: 0, work: 0, longest: 0 };
  a.segs.forEach((s, k) => {
    if (s.s >= T) return;
    const d = Math.min(T, s.e) - s.s;
    if (o[s.st] != null) o[s.st] += d;
    if (s.st === 'handle' && s.e <= T) {
      o.handled++;
      const nx = a.segs[k + 1];
      o.work += s.e - s.s + (nx && nx.st === 'acw' && nx.e <= T ? nx.e - nx.s : 0);
      o.longest = Math.max(o.longest, s.e - s.s);
    }
  });
  const busy = o.handle + o.acw, pool = busy + o.avail;
  o.occ = pool > 0 ? busy / pool : null;
  o.aht = o.handled ? o.work / o.handled : null;
  const schedMin = Math.max(0, Math.min(T, a.start + 510) - a.start);
  const devMin = a.dev.reduce((n, r) => n + Math.max(0, Math.min(T, r.e) - r.s), 0);
  o.devMin = devMin;
  o.adh = schedMin > 0 ? (schedMin - (a.excused ? 0 : devMin)) / schedMin : null;
  const cur = T < a.start || T >= a.end ? null : segAt(a, T);
  o.st = cur ? cur.st : 'off';
  o.since = cur ? T - cur.s : 0;
  o.curSeg = cur;
  const b = schedAt(a, T);
  o.out = !!(cur && b && cat(cur.st) !== (b.a === 'lunch' ? 'break' : b.a)) || (!cur && !!b);
  return o;
}

