/* ---------- KPIs ---------- */
const STACK = ['handle', 'acw', 'avail', 'break', 'meet'];
function kpis(S) {
  const list = shown();
  const cur = STACK.map((st) => list.filter((a) => S.get(a).st === st).length);
  const inn = cur.reduce((x, y) => x + y, 0);
  K.inn.textContent = inn;
  K.nowtxt.textContent = `${cur[0]} on contact · ${cur[1]} wrap-up · ${cur[2]} waiting · ${cur[3] + cur[4]} away`;
  const st = $('.dsp-floor__stack');
  if (!st.children.length) st.innerHTML = STACK.map((s) => `<span data-s="${s}" style="--c:${SCOL[s]}"></span>`).join('');
  $$('span', st).forEach((sp, k) => { sp.style.setProperty('--n', cur[k] || 0.0001); sp.textContent = cur[k] || ''; sp.title = `${STATE[STACK[k]]}: ${cur[k]}`; });
  st.setAttribute('aria-label', STACK.map((s, k) => `${STATE[s]} ${cur[k]}`).join(', '));
  let busy = 0, pool = 0, sm = 0, dm = 0, handled = 0, work = 0, out = 0;
  list.forEach((a) => {
    const o = S.get(a);
    busy += o.handle + o.acw; pool += o.handle + o.acw + o.avail; handled += o.handled; work += o.work;
    const schedMin = Math.max(0, Math.min(T, a.start + 510) - a.start);
