  K.adhsub.textContent = out ? `${out} off schedule at ${hm(T)}` : `everyone on plan at ${hm(T)}`;
  K.handled.textContent = handled;
  K.aht.textContent = handled ? `average handle ${ms(work / handled)}` : 'no contacts yet';
}

