/* ---------- leaderboard (FLIP reorder) ---------- */
const ranksEl = $('.dsp-floor__ranks');
const MV = {
  handled: { get: (o) => o.handled, fmt: (v) => v + '', better: 1 },
  aht: { get: (o) => o.aht, fmt: (v) => ms(v), better: -1 },
