  const list = shown().map((a) => ({ a, v: m.get(S.get(a)) }));
  list.sort((x, y) => (x.v == null) - (y.v == null) || (y.v - x.v) * m.better || x.a.name.localeCompare(y.a.name));
  const vals = list.filter((x) => x.v != null).map((x) => x.v);
  const best = m.better > 0 ? Math.max(...vals, 1e-9) : Math.min(...vals);
  const before = new Map($$('li', ranksEl).map((li) => [li.dataset.a, li.getBoundingClientRect().top]));
  const order = list.map((x) => x.a.i).join();
  if (ranksEl.dataset.order !== order || !ranksEl.children.length) {
    ranksEl.dataset.order = order;
    ranksEl.innerHTML = list.map((x) => `<li data-a="${x.a.i}"><button type="button" aria-label="${esc(x.a.name)}: show on the timeline"><span class="rk"></span><span class="nm">${esc(x.a.name)}</span><span class="v"></span><span class="bar"><i></i></span></button></li>`).join('');
  }
  list.forEach((x, k) => {
