const QUICK = [
  ['Back from break?', (a) => `Hi ${a.first}, your break finished a few minutes ago — can you go available when you’re ready?`],
  ['Queue is building', () => 'Queue is building on our side — please keep wrap-up short for the next hour.'],
  ['Need a hand?', (a) => `Saw you’ve been on this one a while, ${a.first} — want me to join or take a look?`]
];
function detail(a, quiet) {
  const box = $('.dsp-floor__more > div', rowOf(a));
  const o = stats(a, T);
  const hours = [];
  for (let h = 8; h < 19; h++) {
    let busy = 0, pool = 0;
    a.segs.forEach((s) => {
      const f = Math.max(s.s, h * 60), t = Math.min(s.e, (h + 1) * 60, T);
      if (t <= f) return;
