  }
  const tot = o.handle + o.acw + o.avail + o.break + o.meet || 1;
  const mix = [['handle', 'Handling'], ['acw', 'Wrap-up'], ['avail', 'Waiting'], ['break', 'Breaks'], ['meet', 'Meetings']];
  const onContact = o.st === 'handle';
