      <div class="bar">${mix.map(([k]) => `<i style="--n:${o[k] || 0.0001};--c:${SCOL[k]}"></i>`).join('')}</div>
      ${mix.map(([k, l]) => `<div style="--c:${SCOL[k]}"><span>${l}</span><b>${dur(o[k])} · ${Math.round((o[k] / tot) * 100)}%</b></div>`).join('')}
      <div><span style="--c:transparent">Longest contact</span><b>${o.longest ? Math.floor(o.longest) + 'm ' + pad(Math.round((o.longest % 1) * 60) % 60) + 's' : '—'}</b></div>
    </div>
    <div class="dsp-floor__acts"><h4>Supervisor</h4>
      <div class="row">
        <button type="button" class="dsp-floor__btn" data-act="msg" aria-expanded="false">Message ${esc(a.first)}</button>
        <button type="button" class="dsp-floor__btn" data-act="excuse" aria-pressed="${a.excused}"${hasDev ? '' : ` disabled title="${esc(a.first)} has no off-schedule time to excuse yet"`}>${a.excused ? 'Excused' : 'Excuse deviation'}</button>
        <button type="button" class="dsp-floor__btn" data-act="listen" aria-pressed="${!!a.listening}"${onContact ? '' : ` disabled title="${esc(a.first)} isn’t on a contact right now"`}>${a.listening ? 'Listening' : 'Listen in'}</button>
      </div>
      <form hidden>
        <div class="quick">${QUICK.map(([l], k) => `<button type="button" data-q="${k}" aria-pressed="false">${l}</button>`).join('')}</div>
        <textarea aria-label="Message to ${esc(a.name)}" placeholder="Write to ${esc(a.first)}…"></textarea>
        <p class="err" hidden>Write a message or pick a quick reply first.</p>
        <div class="row"><button type="submit" class="dsp-floor__btn is-primary">Send</button><button type="button" class="dsp-floor__btn" data-act="cancel">Cancel</button></div>
      </form>
      <p class="log">${a.log.length ? a.log.map((l) => `<b>${l[0]}</b> ${esc(l[1])}`).join('<br>') : `${hasDev ? `${dur(o.devMin)} off schedule so far${a.excused ? ' (excused)' : ''}.` : 'On plan all day so far.'}`}</p>
    </div></div>`;
  if (keep && quiet) { const f = $('form', box); f.hidden = false; $('textarea', f).value = keep.querySelector('textarea').value; $('[data-act="msg"]', box).setAttribute('aria-expanded', 'true'); }
