    if (v != null) svgEl('rect', { x: k * bw + 2, y: 4 + (H - 20) * (1 - v), width: bw - 4, height: (H - 20) * v, rx: 2, style: quiet ? 'animation:none' : `--i:${k}` }, svg).appendChild(svgEl('title', {})).textContent = `${pad(8 + k)}:00 — ${Math.round(v * 100)}% occupied`;
    if (k % 2 === 0) svgEl('text', { x: k * bw + bw / 2, y: H - 3, 'text-anchor': 'middle' }, svg).textContent = pad(8 + k);
  });
  svgEl('line', { x1: 0, x2: W, y1: 4 + (H - 20) * 0.15, y2: 4 + (H - 20) * 0.15 }, svg).appendChild(svgEl('title', {})).textContent = '85% occupancy ceiling';
}
rowsEl.addEventListener('click', (e) => {
  const b = e.target.closest('[data-act], [data-q]');
