css:
.dsp-erlang {
  /* re-theme with these four */
  --dsp-erlang-bg: oklch(0.976 0.007 235);
  --dsp-erlang-ink: oklch(0.29 0.055 255);
  --dsp-erlang-accent: oklch(0.68 0.17 52);
  --dsp-erlang-short: oklch(0.57 0.2 25);
  /* derived */
  --dsp-erlang-over: color-mix(in oklch, oklch(0.62 0.12 160) 85%, var(--dsp-erlang-ink));
  --dsp-erlang-card: color-mix(in oklch, var(--dsp-erlang-bg), white 70%);
  --dsp-erlang-line: color-mix(in oklch, var(--dsp-erlang-ink) 14%, transparent);
  --dsp-erlang-hair: color-mix(in oklch, var(--dsp-erlang-ink) 7%, transparent);
  --dsp-erlang-mute: color-mix(in oklch, var(--dsp-erlang-ink) 66%, var(--dsp-erlang-bg));
  --dsp-erlang-faint: color-mix(in oklch, var(--dsp-erlang-ink) 45%, var(--dsp-erlang-bg));
  --dsp-erlang-calls: color-mix(in oklch, var(--dsp-erlang-ink) 13%, var(--dsp-erlang-bg));
  --dsp-erlang-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dsp-erlang-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dsp-erlang-out: cubic-bezier(.2, .8, .2, 1);
  --dsp-erlang-spring: linear(0, .07 2.5%, .28 6.6%, .62 12%, .92 18.6%, 1.06 25%, 1.08 31%, 1.04 39%, 1.006 51%, .998 65%, 1);
  width: 100%;
  height: var(--dsp-erlang-h, 680px);
  container-type: inline-size;
  container-name: dsp-erlang;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background: var(--dsp-erlang-bg);
  color: var(--dsp-erlang-ink);
  font: 13px/1.45 var(--dsp-erlang-sans);
  color-scheme: light;
  accent-color: var(--dsp-erlang-accent);
  box-shadow: inset 0 0 0 1px var(--dsp-erlang-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, ol) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(button:disabled) { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dsp-erlang-accent); outline-offset: 2px; border-radius: 6px; }
  & svg { flex: none; }
}
.dsp-erlang__app {
  height: 100%; display: grid;
  grid-template-columns: 236px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side head" "side main";
}

/* ---------------------------------------------------------------- side */
.dsp-erlang__side {
  grid-area: side; min-height: 0; overflow: auto; padding: 16px 14px; display: flex; flex-direction: column; gap: 8px;
  border-right: 1px solid var(--dsp-erlang-line); background: color-mix(in oklch, var(--dsp-erlang-bg), var(--dsp-erlang-ink) 3%);
  scrollbar-width: thin; scrollbar-color: var(--dsp-erlang-line) transparent;
}
.dsp-erlang__brand {
  display: flex; align-items: center; gap: 10px; margin-bottom: 6px;
  & svg { width: 32px; height: 32px; padding: 5px; border-radius: 9px; background: var(--dsp-erlang-ink); stroke: var(--dsp-erlang-bg); fill: none; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & span { display: grid; line-height: 1.2; min-width: 0; }
  & b { font-weight: 720; letter-spacing: -.01em; }
  & small { font-size: 11px; color: var(--dsp-erlang-faint); }
}
.dsp-erlang__lbl { font: 650 10.5px var(--dsp-erlang-sans); letter-spacing: .09em; text-transform: uppercase; color: var(--dsp-erlang-faint); margin-top: 6px; }
.dsp-erlang__days {
  display: grid; gap: 1px;
  & button {
    display: grid; grid-template-columns: 34px 1fr auto; align-items: center; gap: 8px; height: 30px; padding: 0 8px; border-radius: 8px; text-align: left;
    color: var(--dsp-erlang-mute); transition: background-color .15s, color .15s;
  }
  & button b { font-weight: 650; }
  & button span { font: 500 11.5px var(--dsp-erlang-mono); font-variant-numeric: tabular-nums; }
  & button i { width: 7px; height: 7px; border-radius: 50%; background: var(--dsp-erlang-over); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dsp-erlang-over) 18%, transparent); }
  & button i.is-short { background: var(--dsp-erlang-short); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dsp-erlang-short) 18%, transparent); }
  & button:hover { background: var(--dsp-erlang-hair); color: var(--dsp-erlang-ink); }
  & button[aria-selected="true"] { background: var(--dsp-erlang-card); color: var(--dsp-erlang-ink); box-shadow: 0 0 0 1px var(--dsp-erlang-line), 0 2px 8px -4px color-mix(in oklch, var(--dsp-erlang-ink) 30%, transparent); }
}
.dsp-erlang__asmt {
  display: none; align-items: center; gap: 8px; height: 32px; padding: 0 10px; border-radius: 8px; font-weight: 620; font-size: 12.5px;
  box-shadow: inset 0 0 0 1px var(--dsp-erlang-line); background: var(--dsp-erlang-card);
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
  & em { font: 500 11px var(--dsp-erlang-mono); font-style: normal; color: var(--dsp-erlang-faint); margin-left: auto; white-space: nowrap; }
  &[aria-expanded="true"] { background: var(--dsp-erlang-ink); color: var(--dsp-erlang-bg); & em { color: inherit; opacity: .7; } }
}
.dsp-erlang__params { display: grid; gap: 8px; }
.dsp-erlang__sl {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 4px;
  & button { display: grid; gap: 0; padding: 6px 4px; border-radius: 8px; text-align: center; box-shadow: inset 0 0 0 1px var(--dsp-erlang-line); background: var(--dsp-erlang-card); transition: box-shadow .15s, background-color .15s; }
  & b { font: 650 13px var(--dsp-erlang-mono); }
  & small { font-size: 10px; color: var(--dsp-erlang-faint); white-space: nowrap; }
  & button:hover { box-shadow: inset 0 0 0 1px var(--dsp-erlang-faint); }
  & button[aria-checked="true"] { background: var(--dsp-erlang-ink); color: var(--dsp-erlang-bg); box-shadow: none; & small { color: inherit; opacity: .7; } }
}
.dsp-erlang__step {
  display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 0; border-top: 1px dashed var(--dsp-erlang-line);
  & > span { display: grid; line-height: 1.25; min-width: 0; }
  & b { font-size: 12px; font-weight: 640; }
  & small { font-size: 10.5px; color: var(--dsp-erlang-faint); }
  & > div { display: flex; align-items: center; gap: 2px; padding: 2px; border-radius: 9px; background: var(--dsp-erlang-card); box-shadow: inset 0 0 0 1px var(--dsp-erlang-line); }
  & button { width: 24px; height: 24px; border-radius: 7px; display: grid; place-items: center; color: var(--dsp-erlang-mute); transition: background-color .15s, color .15s; }
  & button:hover:not(:disabled) { background: var(--dsp-erlang-hair); color: var(--dsp-erlang-ink); }
  & button:disabled { opacity: .35; }
  & button svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
  & output { min-width: 46px; text-align: center; font: 650 12.5px var(--dsp-erlang-mono); font-variant-numeric: tabular-nums; }
}
.dsp-erlang__case {
  display: flex; align-items: center; gap: 10px; text-align: left; padding: 8px 0; border-top: 1px dashed var(--dsp-erlang-line);
  & i { width: 30px; height: 17px; border-radius: 99px; background: var(--dsp-erlang-line); position: relative; flex: none; transition: background-color .2s; }
  & i::after { content: ""; position: absolute; top: 2px; left: 2px; width: 13px; height: 13px; border-radius: 50%; background: white; box-shadow: 0 1px 2px color-mix(in oklch, var(--dsp-erlang-ink) 35%, transparent); transition: translate .35s var(--dsp-erlang-spring); }
  & span { display: grid; line-height: 1.25; }
  & b { font-size: 12px; font-weight: 640; }
  & small { font-size: 10.5px; color: var(--dsp-erlang-faint); }
  &[aria-checked="true"] i { background: var(--dsp-erlang-accent); }
  &[aria-checked="true"] i::after { translate: 13px 0; }
}

/* ---------------------------------------------------------------- head */
.dsp-erlang__head { grid-area: head; padding: 16px 20px 10px; display: grid; gap: 12px; }
.dsp-erlang__title {
  & h2 { font-size: clamp(18px, 1.3cqi + 6px, 22px); font-weight: 740; letter-spacing: -.025em; text-wrap: balance; }
  & p { font-size: 12px; color: var(--dsp-erlang-mute); text-wrap: pretty; }
}
.dsp-erlang__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-radius: 12px; background: var(--dsp-erlang-card); box-shadow: inset 0 0 0 1px var(--dsp-erlang-line);
  & > div { display: grid; gap: 0; padding: 9px 14px; border-left: 1px dashed var(--dsp-erlang-line); min-width: 0; }
  & > div:first-child { border-left: 0; }
  & span { font-size: 11px; font-weight: 600; color: var(--dsp-erlang-mute); white-space: nowrap; }
  & b { font: 650 clamp(18px, 1.2cqi + 8px, 23px)/1.2 var(--dsp-erlang-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & small { font-size: 10.5px; color: var(--dsp-erlang-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .is-short b { color: var(--dsp-erlang-short); }
  & .is-short.is-zero b { color: var(--dsp-erlang-over); }
  & .is-sl.is-miss b { color: var(--dsp-erlang-short); }
  & .is-sl.is-hit b { color: var(--dsp-erlang-over); }
  & b.is-bump { animation: dsp-erlang-bump .5s var(--dsp-erlang-out); }
}
@keyframes dsp-erlang-bump { 30% { translate: 0 -3px; } }

/* ---------------------------------------------------------------- main */
.dsp-erlang__main {
  grid-area: main; min-height: 0; overflow: auto; padding: 0 20px 18px; display: grid; gap: 12px; grid-template-rows: minmax(250px, 1fr) auto;
  scrollbar-width: thin; scrollbar-color: var(--dsp-erlang-line) transparent;
}
.dsp-erlang__chart { display: flex; flex-direction: column; min-height: 0; gap: 6px; }
.dsp-erlang__keys {
  display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11.5px; color: var(--dsp-erlang-mute);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & small { color: var(--dsp-erlang-faint); }
  & i { width: 14px; height: 10px; }
  & .k-calls i { background: var(--dsp-erlang-calls); border-radius: 2px; }
  & .k-req i { height: 0; border-top: 2px solid var(--dsp-erlang-ink); }
  & .k-sch i { height: 0; border-top: 2.5px solid var(--dsp-erlang-accent); }
  & .k-short i { background: color-mix(in oklch, var(--dsp-erlang-short) 30%, transparent); border-radius: 2px; }
  & .k-over i { background: color-mix(in oklch, var(--dsp-erlang-over) 22%, transparent); border-radius: 2px; }
}
.dsp-erlang__plot {
  position: relative; flex: 1; min-height: 220px; border-radius: 12px; background-color: var(--dsp-erlang-card);
  background-image: linear-gradient(var(--dsp-erlang-hair) 1px, transparent 1px), linear-gradient(90deg, var(--dsp-erlang-hair) 1px, transparent 1px);
  background-size: 12px 12px; box-shadow: inset 0 0 0 1px var(--dsp-erlang-line); cursor: crosshair;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  &:focus-visible { outline-offset: 3px; border-radius: 12px; }
  & .ax text { font: 500 10.5px var(--dsp-erlang-mono); fill: var(--dsp-erlang-faint); font-variant-numeric: tabular-nums; }
  & .ax .t { font: 650 10px var(--dsp-erlang-sans); letter-spacing: .06em; text-transform: uppercase; }
  & .ax line { stroke: var(--dsp-erlang-line); }
  & .calls rect { fill: var(--dsp-erlang-calls); transform-box: fill-box; transform-origin: bottom; animation: dsp-erlang-grow .7s var(--dsp-erlang-out) both; animation-delay: calc(var(--i) * 16ms); }
  & .calls line { stroke: color-mix(in oklch, var(--dsp-erlang-ink) 35%, transparent); stroke-width: 1; }
  & .gap { animation: dsp-erlang-fade .6s .5s both; }
  & .gap.short { fill: color-mix(in oklch, var(--dsp-erlang-short) 26%, transparent); }
  & .gap.over { fill: color-mix(in oklch, var(--dsp-erlang-over) 16%, transparent); }
  & .req { fill: none; stroke: var(--dsp-erlang-ink); stroke-width: 2; stroke-linejoin: round; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dsp-erlang-draw 1s .15s var(--dsp-erlang-out) forwards; }
  & .sch { fill: none; stroke: var(--dsp-erlang-accent); stroke-width: 2.6; stroke-linejoin: round; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dsp-erlang-draw 1s .3s var(--dsp-erlang-out) forwards; }
  &.is-quiet .calls rect, &.is-quiet .gap, &.is-quiet .req, &.is-quiet .sch { animation: none; stroke-dashoffset: 0; }
  & .sel { fill: color-mix(in oklch, var(--dsp-erlang-ink) 7%, transparent); stroke: var(--dsp-erlang-ink); stroke-width: 1; stroke-dasharray: 2 3; }
  & .hov { fill: color-mix(in oklch, var(--dsp-erlang-accent) 10%, transparent); }
  & .now { font: 650 10px var(--dsp-erlang-sans); fill: var(--dsp-erlang-short); }
}
@keyframes dsp-erlang-grow { from { scale: 1 0; } }
@keyframes dsp-erlang-draw { to { stroke-dashoffset: 0; } }
@keyframes dsp-erlang-fade { from { opacity: 0; } }

.dsp-erlang__lower { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); gap: 12px; }
.dsp-erlang__card { border-radius: 12px; background: var(--dsp-erlang-card); box-shadow: inset 0 0 0 1px var(--dsp-erlang-line); padding: 12px 14px; min-width: 0; }
.dsp-erlang__ch {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 8px;
  & h3 { font-size: 13.5px; font-weight: 700; letter-spacing: -.01em; font-variant-numeric: tabular-nums; }
  & small { font-size: 11px; color: var(--dsp-erlang-faint); text-align: right; }
}
.dsp-erlang__gaplist {
