  &:empty { display: none; }
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 4px 10px; padding: 8px 10px; border-radius: 9px; background: color-mix(in oklch, var(--dsp-erlang-short) 8%, var(--dsp-erlang-card)); box-shadow: inset 3px 0 0 var(--dsp-erlang-short); animation: dsp-erlang-in .45s var(--dsp-erlang-out) both; animation-delay: calc(var(--i) * 50ms); }
  & li b { font: 650 12px var(--dsp-erlang-mono); }
  & li small { display: block; font-size: 11px; color: var(--dsp-erlang-mute); }
  & li.is-ok { background: color-mix(in oklch, var(--dsp-erlang-over) 9%, var(--dsp-erlang-card)); box-shadow: inset 3px 0 0 var(--dsp-erlang-over); }
}
@keyframes dsp-erlang-in { from { opacity: 0; translate: 0 6px; } }
.dsp-erlang__btn {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 640; white-space: nowrap;
  background: var(--dsp-erlang-ink); color: var(--dsp-erlang-bg); transition: background-color .15s, scale .2s var(--dsp-erlang-spring);
  & svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }
  &:hover { background: color-mix(in oklch, var(--dsp-erlang-ink), white 14%); }
  &:active { scale: .96; }
}
.dsp-erlang__roster {
  display: grid; gap: 0;
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 8px; padding: 5px 0; border-top: 1px solid var(--dsp-erlang-hair); font-size: 12px; }
  & li:first-child { border-top: 0; }
