  & .tm b { font: 600 12px var(--dsp-erlang-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .tm small { font-size: 11px; color: var(--dsp-erlang-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .bar { width: 90px; height: 6px; border-radius: 3px; background: var(--dsp-erlang-hair); position: relative; }
  & .bar i { position: absolute; top: 0; bottom: 0; left: var(--l); width: var(--w); border-radius: 3px; background: var(--dsp-erlang-ink); opacity: .55; }
  & li.is-new .bar i { background: var(--dsp-erlang-accent); opacity: 1; }
  & li.is-new .tm b { color: color-mix(in oklch, var(--dsp-erlang-accent), black 25%); }
  & li.is-new { animation: dsp-erlang-in .45s var(--dsp-erlang-out); }
  & .ct { display: flex; align-items: center; gap: 2px; }
