    <div class="r"><span>Needed</span>${row.req} scheduled · ${row.ph} on phones</div>
    <div class="r"><span>Scheduled</span>${row.sch} · ${row.prod} on phones</div>
    <div class="r"><span>Gap</span><span class="${row.gap < 0 ? 'bad' : 'good'}">${row.gap > 0 ? '+' : ''}${row.gap}</span></div>
    <div class="r"><span>Projected</span><span class="${row.sl < P.sl ? 'bad' : 'good'}">${pct(row.sl)} in ${P.T}s · ASA ${secs(row.asa)}</span></div>`;
}
function placeTip(cx, cy) {
  const r0 = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let x = cx - r0.left + 16, y = cy - r0.top - h / 2;
  if (x + w > r0.width - 8) x = cx - r0.left - w - 16;
  y = Math.max(8, Math.min(r0.height - h - 8, y));
  tip.style.translate = `${Math.round(x)}px ${Math.round(y)}px`;
}
plot.addEventListener('pointermove', (e) => {
  if (!geo) return;
  const i = idxAt(e);
  if (i == null) { hideHover(); return; }
  hov = i;
  geo.hovR.setAttribute('x', geo.x(i)); geo.hovR.setAttribute('visibility', 'visible');
  tip.innerHTML = rowTip(M.rows[i]); tip.hidden = false;
  placeTip(e.clientX, e.clientY);
});
function hideHover() { hov = null; tip.hidden = true; if (geo) geo.hovR.setAttribute('visibility', 'hidden'); }
plot.addEventListener('pointerleave', hideHover);
plot.addEventListener('click', (e) => { const i = idxAt(e); if (i != null) { sel = i; paintSel(); inspector(); } });
plot.addEventListener('keydown', (e) => {
  const d = { ArrowRight: 1, ArrowLeft: -1 }[e.key];
  if (e.key === 'Home') sel = 0; else if (e.key === 'End') sel = NI - 1; else if (d) sel = Math.max(0, Math.min(NI - 1, sel + d)); else return;
  e.preventDefault();
  paintSel(); inspector();
  const rb = geo.selR.getBoundingClientRect();
  tip.innerHTML = rowTip(M.rows[sel]); tip.hidden = false;
  placeTip(rb.right, rb.top + 60);
});
plot.addEventListener('blur', () => { tip.hidden = true; });

/* ---------- inspector ---------- */
function inspector() {
  const row = M.rows[sel];
  K.iv.textContent = `${clock(row.i)}–${clock(row.i + 1)} · ${DAYS[day].k}`;
  $('.dsp-erlang__ivgrid').innerHTML = [
    ['Calls', row.c], ['Traffic', row.A.toFixed(1) + ' E'], ['Occupancy', row.prod ? pct(Math.min(1, row.A / row.prod)) : '—'],
    ['On phones needed', row.ph], ['Scheduled needed', row.req], ['Scheduled', `<b class="${row.gap < 0 ? 'bad' : 'good'}">${row.sch}</b>`],
    ['Service level', `<b class="${row.sl < P.sl ? 'bad' : 'good'}">${pct(row.sl)}</b>`], ['Avg speed of answer', secs(row.asa)], ['Gap', `<b class="${row.gap < 0 ? 'bad' : 'good'}">${row.gap > 0 ? '+' : ''}${row.gap}</b>`]
  ].map(([k, v]) => `<div><span>${k}</span>${String(v).startsWith('<b') ? v : `<b>${v}</b>`}</div>`).join('');
  curve(row);
}
const curveBox = $('.dsp-erlang__curve');
let cgeo = null;
function curve(row) {
  const svg = $('svg', curveBox);
  svg.innerHTML = '';
  const W = Math.max(220, curveBox.clientWidth), H = 120, l = 34, r = 10, t = 10, b = 20;
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const lo = Math.max(1, Math.floor(row.A) + 1), hi = Math.max(lo + 8, row.ph + 6, row.prod + 2);
  const pts = []; for (let n = lo; n <= hi; n++) pts.push({ n, s: serviceLevel(row.c, P.aht, n, P.T), a: asa(row.c, P.aht, n) });
  const x = (n) => l + ((n - lo) / (hi - lo)) * (W - l - r), y = (v) => t + (1 - v) * (H - t - b);
  const ax = svgEl('g', { class: 'ax' }, svg);
  [0, 0.5, 1].forEach((v) => { svgEl('line', { x1: l, x2: W - r, y1: y(v), y2: y(v) }, ax); svgEl('text', { x: l - 5, y: y(v) + 3, 'text-anchor': 'end' }, ax).textContent = v * 100 + '%'; });
  const st = Math.max(1, Math.ceil((hi - lo) / 6));
  for (let n = lo; n <= hi; n += st) svgEl('text', { x: x(n), y: H - 5, 'text-anchor': 'middle' }, ax).textContent = n;
  svgEl('line', { class: 'tg', x1: l, x2: W - r, y1: y(P.sl), y2: y(P.sl) }, svg);
  svgEl('path', { class: 'cv', d: pts.map((p, k) => `${k ? 'L' : 'M'}${x(p.n).toFixed(1)},${y(p.s).toFixed(1)}`).join(''), pathLength: 1 }, svg);
  pts.forEach((p) => svgEl('circle', { class: 'dot', cx: x(p.n), cy: y(p.s), r: 1.8 }, svg));
  if (row.ph >= lo && row.ph <= hi) svgEl('circle', { class: 'need', cx: x(row.ph), cy: y(serviceLevel(row.c, P.aht, row.ph, P.T)), r: 4.5 }, svg);
  const pc = Math.max(lo, Math.min(hi, row.prod));
  svgEl('circle', { class: 'cur', cx: x(pc), cy: y(row.prod < lo ? 0 : serviceLevel(row.c, P.aht, pc, P.T)), r: 5 }, svg);
  /* keep the label off the curve: it rises to the right, so sit level-right while it is steep,
     below-right once it flattens, and mirror to the left near the right edge */
  const sv = row.prod < lo ? 0 : row.sl, py = y(sv), right = x(pc) <= W * 0.7;
  const ly = right ? (sv < 0.5 ? py + 4 : py + 16) : (sv < 0.5 ? py + 4 : py - 9);
  const lab = svgEl('text', { class: 'lab', x: right ? x(pc) + 9 : x(pc) - 9, y: Math.max(t + 9, Math.min(H - b - 3, ly)), 'text-anchor': right ? 'start' : 'end' }, svg);
  lab.textContent = `${row.prod} on phones`;
  cgeo = { x, pts, lo, hi, W, l, r };
}
curveBox.addEventListener('pointermove', (e) => {
  if (!cgeo) return;
  const rb = curveBox.getBoundingClientRect(), px = ((e.clientX - rb.left) / rb.width) * cgeo.W;
  const n = Math.round(cgeo.lo + ((px - cgeo.l) / (cgeo.W - cgeo.l - cgeo.r)) * (cgeo.hi - cgeo.lo));
  const p = cgeo.pts.find((q) => q.n === n); if (!p) { tip.hidden = true; return; }
  tip.innerHTML = `<b>${p.n} agents on the phones</b><div class="r"><span>Answered in ${P.T}s</span>${pct(p.s)}</div><div class="r"><span>Avg speed of answer</span>${secs(p.a)}</div><div class="r"><span>Scheduled to get there</span>${Math.ceil(p.n / (1 - P.shr / 100))}</div>`;
  tip.hidden = false;
  placeTip(e.clientX, e.clientY);
});
curveBox.addEventListener('pointerleave', () => { tip.hidden = true; });

/* ---------- roster + gaps ---------- */
const MINUS = '<svg viewBox="0 0 12 12"><path d="M2.5 6h7"/></svg>', PLUS = '<svg viewBox="0 0 12 12"><path d="M2.5 6h7M6 2.5v7"/></svg>';
function roster() {
  const d = DAYS[day], wins = windows(M.rows);
  $('.dsp-erlang__gaplist').innerHTML = wins.length
    ? wins.slice(0, 3).map((w, k) => `<li style="--i:${k}"><div><b>${clock(w.s)}–${clock(w.e)}</b><small>short by up to ${w.max} · ${pct(w.slc / w.c)} answered in ${P.T}s</small></div><button type="button" class="dsp-erlang__btn" data-cover="${w.s}-${w.e}-${w.max}">${PLUS}Cover with ${w.max}</button></li>`).join('') +
      (wins.length > 3 ? `<li style="--i:3"><div><small>${wins.length - 3} more short window${wins.length - 3 > 1 ? 's' : ''} later in the day</small></div></li>` : '')
    : `<li class="is-ok"><div><b>Every half-hour covered</b><small>${DAYS[day].name} meets ${P.sl * 100}/${P.T} all day on this roster.</small></div></li>`;
  const list = d.roster.map((r, k) => ({ r, k })).sort((a, b) => a.r.s - b.r.s || a.k - b.k);
  $('.dsp-erlang__roster').innerHTML = list.map(({ r, k }) => {
    const e = Math.min(NI, r.s + r.len);
    return `<li class="${r.added ? 'is-new' : ''}" data-k="${k}"><span class="tm"><b>${clock(r.s)}–${clock(e)}</b><small>${(e - r.s) / 2}h${r.added ? ' · added' : ''}</small></span>
      <span class="bar" aria-hidden="true"><i style="--l:${(r.s / NI) * 100}%;--w:${((e - r.s) / NI) * 100}%"></i></span>
      <span class="ct"><button type="button" data-n="-1" aria-label="One fewer agent on ${clock(r.s)}–${clock(e)}"${r.n <= 0 ? ' disabled title="Nobody left on this shift"' : ''}>${MINUS}</button><output>${r.n}</output><button type="button" data-n="1" aria-label="One more agent on ${clock(r.s)}–${clock(e)}"${r.n >= 60 ? ' disabled title="60 is the most one shift can hold"' : ''}>${PLUS}</button></span></li>`;
  }).join('');
  K.paid.textContent = `${fmtN(M.paid)} paid hours · plan needs ${fmtN(M.needH)}`;
}
let undo = null;
$('.dsp-erlang__gaps').addEventListener('click', (e) => {
  const d = DAYS[day];
  const cv = e.target.closest('[data-cover]');
  if (cv) {
    const [s, en, n] = cv.dataset.cover.split('-').map(Number);
    const before = d.roster.map((r) => ({ ...r })), sl0 = M.slDay;
    const len = Math.min(16, Math.max(8, en - s), NI - s);
    d.roster.push({ s, len, n, added: true });
    sel = s;
    render(false);
    toast(`Added ${clock(s)}–${clock(Math.min(NI, s + len))} × ${n}. ${d.k} now projects ${pct(M.slDay)} (was ${pct(sl0)}).`, () => { d.roster = before; render(false); });
    return;
  }
  const st = e.target.closest('[data-n]');
  if (st && !st.disabled) {
    const li = st.closest('li'), r = d.roster[+li.dataset.k];
    r.n = Math.max(0, Math.min(60, r.n + +st.dataset.n));
    render(false);
    const again = $(`.dsp-erlang__roster li[data-k="${li.dataset.k}"] [data-n="${st.dataset.n}"]`);
    if (again && !again.disabled) again.focus();
  }
});

/* ---------- toast ---------- */
const toastEl = $('.dsp-erlang__toast');
let toastT = 0;
function toast(msg, undoFn) {
  toastEl.innerHTML = `<span></span>${undoFn ? '<button type="button">Undo</button>' : ''}`;
  toastEl.firstChild.textContent = msg;
  toastEl.classList.add('is-on');
  if (undoFn) $('button', toastEl).addEventListener('click', () => { undoFn(); toast('Roster restored.'); });
  clearTimeout(toastT);
  toastT = setTimeout(() => toastEl.classList.remove('is-on'), undoFn ? 6000 : 3000);
}
root.addEventListener('keydown', (e) => { if (e.key === 'Escape') { hideHover(); toastEl.classList.remove('is-on'); if (asmt.getAttribute('aria-expanded') === 'true') { asmt.setAttribute('aria-expanded', 'false'); asmt.focus(); } } });

/* ---------- render ---------- */
function render(animate) {
  const d = DAYS[day];
  M = model(d);
  if (sel == null) sel = (M.short.length ? M.short.reduce((a, r) => (r.gap < a.gap ? r : a)) : M.peak).i;
  $('.dsp-erlang__title h2').textContent = d.name;
  const p10 = d.p10.reduce((a, b) => a + b, 0), p90 = d.p90.reduce((a, b) => a + b, 0);
  setK('calls', fmtN(M.tot));
  setK('callsSub', P.busy ? `p90 plan · median ${fmtN(d.calls.reduce((a, b) => a + b, 0))}` : `p10 ${fmtN(p10)} – p90 ${fmtN(p90)}`);
  setK('peak', M.peak.req);
  setK('peakSub', `scheduled at ${clock(M.peak.i)} · ${M.peak.ph} on phones`);
  const sh = M.short.length;
  setK('short', sh);
  setK('shortSub', sh ? `${sh / 2}h under plan · worst ${Math.min(...M.short.map((r) => r.gap))}` : 'fully covered');
  $('.dsp-erlang__kpis .is-short').classList.toggle('is-zero', !sh);
  setK('sl', pct(M.slDay));
  setK('slSub', `target ${P.sl * 100}% in ${P.T}s · ASA ${secs(M.asaDay)}`);
  const slBox = $('.dsp-erlang__kpis .is-sl');
  slBox.classList.toggle('is-miss', M.slDay < P.sl); slBox.classList.toggle('is-hit', M.slDay >= P.sl);
  chart(animate);
  inspector();
  roster();
  paintDays();
}
paintSteps();
render(true);

let lastW = plot.clientWidth, lastH = plot.clientHeight;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const w = plot.clientWidth, h = plot.clientHeight;
  if (Math.abs(w - lastW) > 3 || Math.abs(h - lastH) > 3) { lastW = w; lastH = h; if (M) { chart(false); curve(M.rows[sel]); } }
});
ro.observe(plot);

css:
.dsp-reasons {
  /* re-theme with these four */
  --dsp-reasons-bg: oklch(0.2 0.014 52);
  --dsp-reasons-ink: oklch(0.94 0.014 78);
  --dsp-reasons-accent: oklch(0.82 0.13 80);
  --dsp-reasons-up: oklch(0.72 0.15 32);
  /* derived */
  --dsp-reasons-down: color-mix(in oklch, oklch(0.76 0.1 150) 80%, var(--dsp-reasons-ink));
  --dsp-reasons-panel: color-mix(in oklch, var(--dsp-reasons-bg), var(--dsp-reasons-ink) 4.5%);
  --dsp-reasons-raised: color-mix(in oklch, var(--dsp-reasons-bg), var(--dsp-reasons-ink) 9%);
  --dsp-reasons-line: color-mix(in oklch, var(--dsp-reasons-ink) 12%, transparent);
  --dsp-reasons-hair: color-mix(in oklch, var(--dsp-reasons-ink) 6%, transparent);
  --dsp-reasons-mute: color-mix(in oklch, var(--dsp-reasons-ink) 64%, var(--dsp-reasons-bg));
  --dsp-reasons-faint: color-mix(in oklch, var(--dsp-reasons-ink) 42%, var(--dsp-reasons-bg));
  --dsp-reasons-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dsp-reasons-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dsp-reasons-out: cubic-bezier(.22, 1, .36, 1);
  --dsp-reasons-morph: cubic-bezier(.65, 0, .25, 1);
  --dsp-reasons-spring: linear(0, .07 2.4%, .27 6.4%, .6 11.8%, .9 18.4%, 1.06 25%, 1.09 31%, 1.04 39.5%, 1.005 51%, .998 65%, 1);
  width: 100%;
  height: var(--dsp-reasons-h, 680px);
  container-type: inline-size;
  container-name: dsp-reasons;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background: radial-gradient(120% 80% at 0% 0%, color-mix(in oklch, var(--dsp-reasons-accent) 7%, transparent), transparent 55%), var(--dsp-reasons-bg);
  color: var(--dsp-reasons-ink);
  font: 13px/1.45 var(--dsp-reasons-sans);
  color-scheme: dark;
  accent-color: var(--dsp-reasons-accent);
  box-shadow: inset 0 0 0 1px var(--dsp-reasons-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, ol) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dsp-reasons-accent); outline-offset: 2px; border-radius: 6px; }
  & svg { flex: none; }
}
.dsp-reasons__app {
  height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) 312px;
  grid-template-rows: auto auto auto minmax(0, 1fr);
  grid-template-areas: "head head" "bar bar" "ins detail" "main detail";
}

/* ---------------------------------------------------------------- head */
.dsp-reasons__head { grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; padding: 18px 20px 12px; }
.dsp-reasons__title {
  min-width: 0;
  & p { display: flex; align-items: center; gap: 7px; font-size: 11.5px; color: var(--dsp-reasons-mute); margin-bottom: 3px; }
  & p svg { width: 15px; height: 15px; fill: var(--dsp-reasons-accent); }
  & h2 { font-size: clamp(20px, 1.8cqi + 6px, 28px); font-weight: 300; letter-spacing: -.035em; line-height: 1.05; text-wrap: balance; }
}
.dsp-reasons__views {
  display: flex; gap: 18px; border-bottom: 1px solid var(--dsp-reasons-line);
  & button { position: relative; padding: 4px 0 8px; font-weight: 600; color: var(--dsp-reasons-mute); transition: color .15s; }
  & button::after { content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; background: var(--dsp-reasons-accent); scale: 0 1; transition: scale .4s var(--dsp-reasons-out); }
  & button:hover { color: var(--dsp-reasons-ink); }
  & button[aria-selected="true"] { color: var(--dsp-reasons-ink); }
  & button[aria-selected="true"]::after { scale: 1 1; }
}
.dsp-reasons__bar { grid-area: bar; display: flex; flex-wrap: wrap; gap: 8px; padding: 0 20px 12px; }
.dsp-reasons__seg {
  display: flex; padding: 3px; border-radius: 10px; background: var(--dsp-reasons-panel); box-shadow: inset 0 0 0 1px var(--dsp-reasons-hair);
  & button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dsp-reasons-mute); white-space: nowrap; transition: background-color .15s, color .15s; }
  & button:hover { color: var(--dsp-reasons-ink); }
  & button[aria-checked="true"] { background: var(--dsp-reasons-raised); color: var(--dsp-reasons-ink); box-shadow: inset 0 0 0 1px var(--dsp-reasons-line); }
}
.dsp-reasons__insights {
  grid-area: ins; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; padding: 0 20px 10px;
  & button {
    display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 0 10px; align-items: center; padding: 9px 12px; border-radius: 12px; text-align: left;
    background: var(--dsp-reasons-panel); box-shadow: inset 0 0 0 1px var(--dsp-reasons-hair); transition: background-color .15s, box-shadow .15s, translate .3s var(--dsp-reasons-spring);
    animation: dsp-reasons-rise .6s var(--dsp-reasons-out) both; animation-delay: calc(var(--i) * 70ms);
  }
  & button:hover { background: var(--dsp-reasons-raised); translate: 0 -1px; }
  & button[aria-current="true"] { box-shadow: inset 0 0 0 1.5px var(--c); background: color-mix(in oklch, var(--c) 10%, var(--dsp-reasons-panel)); }
  & i { grid-row: 1 / 3; width: 10px; height: 26px; border-radius: 3px; background: var(--c); }
  & small { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--dsp-reasons-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  /* the name gives way before the number does */
  & b { display: flex; align-items: baseline; gap: .4em; min-width: 0; font-size: 12.5px; font-weight: 600; white-space: nowrap; }
  & b span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
  & b em { flex: none; }
  & em { font-style: normal; font-family: var(--dsp-reasons-mono); font-size: 11.5px; }
  & .up { color: var(--dsp-reasons-up); }
  & .down { color: var(--dsp-reasons-down); }
}
@keyframes dsp-reasons-rise { from { opacity: 0; translate: 0 8px; } }

/* ---------------------------------------------------------------- main */
.dsp-reasons__main { grid-area: main; min-height: 0; min-width: 0; padding: 0 12px 16px 20px; }
.dsp-reasons__view { height: 100%; &[hidden] { display: none; } }
.dsp-reasons__view[data-view="table"] { overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dsp-reasons-line) transparent; }
.dsp-reasons__plot {
  --lab: 168px;
  position: relative; height: 100%; min-height: 300px;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  & .wk text { font: 500 10.5px var(--dsp-reasons-mono); fill: var(--dsp-reasons-faint); font-variant-numeric: tabular-nums; }
  & .wk line { stroke: var(--dsp-reasons-hair); }
  & .wk .ev { font: 600 10px var(--dsp-reasons-sans); fill: var(--dsp-reasons-accent); }
  & .rk text { font: 600 11px var(--dsp-reasons-mono); fill: var(--dsp-reasons-faint); }
  & .ln { fill: none; stroke: var(--c); stroke-width: 3; stroke-linecap: round; transition: d .8s var(--dsp-reasons-morph), opacity .25s, stroke-width .25s; }
  & .ln.is-in { stroke-dasharray: 1; stroke-dashoffset: 1; animation: dsp-reasons-draw 1.3s var(--dsp-reasons-out) forwards; animation-delay: calc(var(--i) * 60ms); }
  & .hit { fill: none; stroke: transparent; stroke-width: 16; cursor: pointer; transition: d .8s var(--dsp-reasons-morph); }
  & .hit.is-sel { cursor: default; }
  & .dot { fill: var(--dsp-reasons-bg); stroke: var(--c); stroke-width: 2.25; transition: transform .8s var(--dsp-reasons-morph), opacity .25s; pointer-events: none; }
  & .dot.is-in { animation: dsp-reasons-pop .5s var(--dsp-reasons-spring) both; animation-delay: calc(var(--i) * 25ms + 300ms); }
  & .dot.is-end { fill: var(--c); }
  & .cross { stroke: var(--dsp-reasons-ink); stroke-width: 1; opacity: .25; pointer-events: none; }
}
@keyframes dsp-reasons-draw { to { stroke-dashoffset: 0; } }
@keyframes dsp-reasons-pop { from { opacity: 0; scale: .2; } }
/* one line in focus: everything else steps back */
.dsp-reasons__plot:has(.hit:hover) .ln, .dsp-reasons__plot:has(.hit:hover) .dot,
.dsp-reasons__plot[data-hl] .ln, .dsp-reasons__plot[data-hl] .dot { opacity: .16; }
.dsp-reasons__plot .ln.is-on, .dsp-reasons__plot .dot.is-on { opacity: 1 !important; }
.dsp-reasons__plot .ln.is-on { stroke-width: 4.5; }
.dsp-reasons__plot .ln.is-sel { stroke-width: 4.5; filter: drop-shadow(0 0 6px color-mix(in oklch, var(--c) 60%, transparent)); }
.dsp-reasons__labels {
  position: absolute; top: 0; right: 0; width: var(--lab); height: 100%; pointer-events: none;
  & button {
    position: absolute; left: 0; top: 0; width: 100%; height: 26px; margin-top: -13px; translate: 0 var(--y); pointer-events: auto;
