/* ---------- twelve weeks of contacts by reason and channel ---------- */
const NW = 12, ISO0 = 29;                         /* W29 starts Mon 13 Jul 2026 */
const DAY = 86400000, W0 = Date.UTC(2026, 6, 13);
const wkDate = (w) => new Date(W0 + w * 7 * DAY).toLocaleDateString('en-GB', { timeZone: 'UTC', day: 'numeric', month: 'short' });
const CH = ['Phone', 'Chat', 'Email'];
const EVENTS = { 4: 'App update broke log-in', 7: 'Fixed tariff launched', 8: 'Price cap news', 9: 'Storm Hollis' };
const HUE = [32, 68, 105, 150, 190, 225, 262, 300, 335, 12];
const OWNERS = ['Billing operations', 'Metering team', 'Payments & debt', 'Digital self-serve'];
const R = [
  ['bill', 'High bill query', 1150, 9.6, .22, [.62, .23, .15], (w) => 1 + (w >= 8 ? (w - 7) * 0.13 : 0), [['Estimated reading too high', .34], ['Direct debit went up', .27], ['Price cap change', .22], ['Standing charge', .17]], 0],
  ['read', 'Meter reading', 980, 3.1, .08, [.35, .25, .40], (w) => 1 + ([3, 7, 11].includes(w) ? 0.42 : 0) - 0.012 * w, [['Submitting a reading', .52], ['Reading rejected', .26], ['Smart meter not sending', .22]], 1],
  ['plan', 'Payment plan & debt', 610, 14.2, .27, [.74, .16, .10], (w) => 1 + 0.05 * w, [['Set up a plan', .41], ['Missed payment', .29], ['Hardship fund', .18], ['Plan review', .12]], 2],
  ['smart', 'Smart meter booking', 880, 6.4, .12, [.44, .38, .18], (w) => 1.28 - 0.062 * w, [['Book an install', .48], ['Reschedule', .31], ['Engineer no-show', .21]], 1],
  ['move', 'Moving home', 760, 8.1, .10, [.40, .30, .30], (w) => 1 + 0.32 * Math.exp(-((w - 4) ** 2) / 6) - 0.022 * w, [['Moving out', .46], ['Moving in', .39], ['Final bill', .15]], 0],
  ['tariff', 'Tariff switch', 500, 7.2, .09, [.38, .44, .18], (w) => 1 + (w >= 7 && w <= 9 ? 1.45 - (w - 7) * 0.38 : w > 9 ? 0.32 : 0), [['Fixed 12-month tariff', .52], ['Exit fees', .27], ['Green tariff', .21]], 3],
  ['dd', 'Direct debit change', 640, 5.2, .11, [.45, .35, .20], (w) => 1 + 0.018 * w, [['Change amount', .55], ['Change date', .28], ['New bank details', .17]], 2],
  ['refund', 'Refund of credit', 450, 6.8, .18, [.40, .30, .30], (w) => 1 - 0.022 * w, [['Request a refund', .58], ['Refund not received', .42]], 0],
  ['outage', 'Power cut', 250, 4.1, .05, [.86, .10, .04], (w) => 1 + (w === 9 ? 3.7 : w === 10 ? 1.15 : 0), [['Report a power cut', .71], ['Restoration time', .29]], 1],
