/* ---------- state ---------- */
let metric = 'vol', ch = 'all', range = 12, sel = 0, view = 'flow', tsort = { k: 'now', dir: -1 };
const weeks = () => Array.from({ length: range }, (_, k) => NW - range + k);
const vol = (r, w) => (ch === 'all' ? r.v[w].reduce((a, b) => a + b, 0) : r.v[w][+ch]);
