const MNAME = { vol: 'contacts', hrs: 'handling hours', rep: 'repeat contacts' };
function ranksAt(w) {
  const order = R.slice().sort((a, b) => val(b, w) - val(a, w) || a.i - b.i);
  const out = {}; order.forEach((r, k) => { out[r.i] = k + 1; });
  return out;
}
let RK = [];
const rankOf = (r, k) => RK[k][r.i];
const pctChg = (a, b) => (b ? (a - b) / b : 0);
/* largest-remainder split: integer parts that always add back up to the whole */
const split = (total, w) => {
  const sum = w.reduce((a, b) => a + b, 0) || 1, raw = w.map((x) => (x / sum) * total), out = raw.map(Math.floor);
