  raw.map((x, k) => [x - Math.floor(x), k]).sort((a, b) => b[0] - a[0]).forEach(([, k]) => { if (left > 0) { out[k]++; left--; } });
  return out;
};

/* ---------- bump chart ---------- */
const plot = $('.dsp-reasons__plot');
const svg = $('svg', plot);
const labelsEl = $('.dsp-reasons__labels');
let G = null, built = 0;
function geom() {
  const W = Math.max(280, plot.clientWidth), H = Math.max(260, plot.clientHeight);
  const lab = parseFloat(getComputedStyle(plot).getPropertyValue('--lab')) || 160;
  const l = 26, r = lab + 16, t = 30, b = 12;
  const n = range;
  return { W, H, l, r, t, b, x: (k) => l + (k / (n - 1)) * (W - l - r), y: (rk) => t + ((rk - 1) / (R.length - 1)) * (H - t - b) };
}
function pathFor(r, g) {
  let d = '';
  RK.forEach((rk, k) => {
    const x = g.x(k), y = g.y(rk[r.i]);
    if (!k) d = `M${x.toFixed(1)},${y.toFixed(1)}`;
    else { const px = g.x(k - 1), py = g.y(RK[k - 1][r.i]), mx = (px + x) / 2; d += `C${mx.toFixed(1)},${py.toFixed(1)} ${mx.toFixed(1)},${y.toFixed(1)} ${x.toFixed(1)},${y.toFixed(1)}`; }
  });
  return d;
}
function build() {
  svg.innerHTML = '';
  const g = G = geom();
  svg.setAttribute('viewBox', `0 0 ${g.W} ${g.H}`);
  const wk = svgEl('g', { class: 'wk' }, svg);
  weeks().forEach((w, k) => {
    svgEl('line', { x1: g.x(k), x2: g.x(k), y1: g.t - 8, y2: g.H - g.b + 4 }, wk);
    if (range <= 6 || (range - 1 - k) % (g.W < 560 ? 3 : 2) === 0) svgEl('text', { x: g.x(k), y: 12, 'text-anchor': 'middle' }, wk).textContent = 'W' + (ISO0 + w);
