  const rk = svgEl('g', { class: 'rk' }, svg);
  for (let n = 1; n <= R.length; n++) svgEl('text', { x: 4, y: g.y(n) + 4 }, rk).textContent = n;
  svg.appendChild(svgEl('line', { class: 'cross', x1: 0, x2: 0, y1: g.t - 8, y2: g.H - g.b, visibility: 'hidden' }));
  const anim = !RM;
  R.forEach((r) => {
    const gg = svgEl('g', { 'data-r': r.i, style: `--c:${r.c}` }, svg);
    const ln = svgEl('path', { class: 'ln' + (anim ? ' is-in' : ''), pathLength: 1, style: `--i:${r.i}` }, gg);
    ln.style.d = `path("${pathFor(r, g)}")`;
    if (anim) ln.addEventListener('animationend', () => { ln.classList.remove('is-in'); ln.removeAttribute('pathLength'); }, { once: true });
    else ln.removeAttribute('pathLength');
