      const c = svgEl('circle', { class: 'dot' + (k === range - 1 ? ' is-end' : '') + (anim ? ' is-in' : ''), r: k === range - 1 ? 4.5 : 3.2, style: `--i:${k}` }, gg);
      c.style.transform = `translate(${g.x(k).toFixed(1)}px, ${g.y(RK[k][r.i]).toFixed(1)}px)`;
