  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; background: var(--dsp-wall-raised); stroke: var(--dsp-wall-ok); fill: none; stroke-width: 1.8; stroke-linecap: round; }
  & span { display: grid; line-height: 1.2; }
  & b { font-weight: 700; letter-spacing: -.01em; }
  & small { font-size: 11px; color: var(--dsp-wall-faint); }
}
.dsp-wall__clock {
  display: flex; align-items: baseline; gap: 8px; margin-right: auto;
