.dsp-wall__dot { width: 8px; height: 8px; border-radius: 50%; background: var(--dsp-wall-ok); align-self: center; box-shadow: 0 0 0 0 color-mix(in oklch, var(--dsp-wall-ok) 50%, transparent); animation: dsp-wall-beat 2s infinite; }
.dsp-wall[data-paused] .dsp-wall__dot { background: var(--dsp-wall-faint); animation: none; }
