.dsp-wall__ctl { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.dsp-wall__thr {
  display: flex; align-items: center; gap: 2px; padding: 3px 3px 3px 10px; border-radius: 10px; background: var(--dsp-wall-tile); box-shadow: inset 0 0 0 1px var(--dsp-wall-hair);
  & span { font-size: 11px; color: var(--dsp-wall-faint); margin-right: 6px; white-space: nowrap; }
  & button { height: 26px; padding: 0 9px; border-radius: 7px; font: 600 12px var(--dsp-wall-mono); color: var(--dsp-wall-mute); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--dsp-wall-ink); }
  & button[aria-checked="true"] { background: var(--dsp-wall-raised); color: var(--dsp-wall-ink); box-shadow: inset 0 0 0 1px var(--dsp-wall-line); }
}
.dsp-wall__btn {
