  background: var(--dsp-wall-tile); box-shadow: inset 0 0 0 1px var(--dsp-wall-line); transition: background-color .15s, opacity .15s, scale .2s var(--dsp-wall-spring);
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
