  &:disabled { opacity: .45; }
  &[aria-pressed="true"] { background: var(--dsp-wall-ink); color: var(--dsp-wall-bg); box-shadow: none; }
  &.is-alarm { background: var(--dsp-wall-alarm); color: white; box-shadow: none; }
}
.dsp-wall__btn[hidden] { display: none; }

/* ---------------------------------------------------------------- tiles */
.dsp-wall__tiles {
  grid-area: tiles; min-height: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: minmax(0, 1fr); gap: 12px;
}
.dsp-wall__tiles:has(.dsp-wall__tile.is-big) { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); grid-template-rows: repeat(3, minmax(0, 1fr)); }
.dsp-wall__tile {
  --s: var(--dsp-wall-ok);
  position: relative; min-height: 0; min-width: 0; display: flex; flex-direction: column; gap: 8px; padding: 14px 14px 12px; border-radius: 14px;
  background: linear-gradient(180deg, color-mix(in oklch, var(--s) 7%, var(--dsp-wall-tile)), var(--dsp-wall-tile) 55%);
  box-shadow: inset 0 0 0 1px var(--dsp-wall-hair); overflow: hidden;
  animation: dsp-wall-in .6s var(--dsp-wall-out) both; animation-delay: calc(var(--i) * 70ms);
  transition: background-color .4s;
  &[data-s="warn"] { --s: var(--dsp-wall-warn); }
  &[data-s="alarm"] { --s: var(--dsp-wall-alarm); }
