  &::before {
    content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 2px; pointer-events: none; opacity: 0;
    background: conic-gradient(from var(--dsp-wall-angle), transparent 0 62%, var(--dsp-wall-alarm) 78%, color-mix(in oklch, var(--dsp-wall-alarm), white 30%) 82%, transparent 90%);
