}
@keyframes dsp-wall-in { from { opacity: 0; translate: 0 12px; } }
@keyframes dsp-wall-spin { to { --dsp-wall-angle: 360deg; } }
.dsp-wall__th {
  display: flex; align-items: center; gap: 8px;
  & .ic { width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; background: var(--dsp-wall-raised); }
  & .ic svg { width: 15px; height: 15px; fill: none; stroke: var(--dsp-wall-ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & h3 { font-size: 14px; font-weight: 650; letter-spacing: -.01em; }
  & .pill { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 8px; border-radius: 99px; font-size: 10.5px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; background: color-mix(in oklch, var(--s) 18%, transparent); color: var(--s); margin-left: auto; white-space: nowrap; }
