  & dd { font: 600 16px var(--dsp-wall-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; white-space: nowrap; }
  & dd small { font-size: 11px; color: var(--dsp-wall-faint); font-weight: 500; }
  & dd.is-warn { color: var(--dsp-wall-warn); }
  & dd.is-alarm { color: var(--dsp-wall-alarm); }
  & dd.is-ok { color: var(--dsp-wall-ok); }
}
.dsp-wall__trend {
  flex: 1; min-height: 44px; display: flex; flex-direction: column; gap: 3px;
  & p { display: flex; justify-content: space-between; font: 500 10px var(--dsp-wall-mono); color: var(--dsp-wall-faint); }
  & svg { flex: 1; width: 100%; min-height: 24px; display: block; }
  & .l { fill: none; stroke: var(--s); stroke-width: 1.6; vector-effect: non-scaling-stroke; stroke-linejoin: round; }
