.dsp-wall__lane { position: relative; flex: 0 0 96px; min-height: 46px; border-radius: 9px; background: color-mix(in oklch, var(--dsp-wall-bg) 55%, transparent); box-shadow: inset 0 0 0 1px var(--dsp-wall-hair); }
.dsp-wall__lane canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.dsp-wall__lane span { position: absolute; bottom: 4px; font: 500 9.5px var(--dsp-wall-mono); color: var(--dsp-wall-faint); pointer-events: none; }
.dsp-wall__ack {
