  { k: 'voice', name: 'Voice', lam: 5.3 / 60, aht: 300, n: 27, T: 60, free: 'Agents free', ab: [75, 0.006], hist: [0.83, 150] },
  { k: 'chat', name: 'Chat', lam: 7.1 / 60, aht: 240, n: 32, T: 60, free: 'Chat slots free', ab: [100, 0.004], hist: [0.86, 190] },
  { k: 'msg', name: 'Messaging', lam: 3.15 / 60, aht: 200, n: 10, T: 120, free: 'Agents free', ab: [240, 0.002], hist: [0.88, 85] },
  { k: 'cb', name: 'Callbacks', lam: 1.35 / 60, aht: 360, n: 8, T: 180, free: 'Agents free', ab: [600, 0.001], hist: [0.84, 36] }
].map((c) => ({ ...c, queue: [], serving: [], ans: 0, within: 0, abn: 0, cells: [], live: { ans: 0, within: 0 }, ack: null, surge: 0, status: 'ok', last: {}, series: [] }));

/* ---------- today so far: half-hours from 08:00, 12 complete by 14:00 ---------- */
const DAY0 = 8 * 3600, NCELL = 24;
let t = 14 * 3600 + 2 * 60 + 11;
const cellOf = (s) => Math.floor((s - DAY0) / 1800);
let curCell = cellOf(t);
CHS.forEach((c) => {
  for (let i = 0; i < curCell; i++) {
    const h = 8 + i / 2, shape = 0.55 + 0.45 * Math.exp(-((h - 10) ** 2) / 3) + 0.3 * Math.exp(-((h - 13) ** 2) / 4);
    const v = Math.round(c.hist[1] * shape * (0.9 + rnd() * 0.2));
    const sl = Math.min(0.98, Math.max(0.55, c.hist[0] + (rnd() - 0.5) * 0.16 - (h > 9.5 && h < 10.5 ? 0.1 : 0)));
    const w = Math.round(v * sl);
