});

/* ---------- simulation ---------- */
let cid = 0, thr = 120, paused = false, tickAt = performance.now();
const pops = [];
const events = [];
function addEvent(c, html, col) { events.unshift({ t, c, html, col }); if (events.length > 9) events.length = 9; evDirty = true; }
let evDirty = true;
function step(quiet) {
  t += 1;
  const cell = cellOf(t);
  if (!quiet && cell !== curCell && cell < NCELL) {
    CHS.forEach((c) => { c.cells[curCell] = { ...c.live }; c.live = { ans: 0, within: 0 }; });
    curCell = cell; heatDirty = true;
  }
  CHS.forEach((c) => {
    c.serving = c.serving.map((x) => x - 1).filter((x) => x > 0);
    let n = poisson(c.lam);
    if (c.surge > 0) { const add = Math.min(c.surge, 1 + Math.floor(rnd() * 2)); n += add; c.surge -= add; }
    for (let i = 0; i < n; i++) c.queue.push({ id: ++cid, t: t - rnd(), who: pick(PEOPLE), intent: pick(INTENTS[c.k]), born: performance.now(), y: 0.15 + rnd() * 0.7 });
    c.queue = c.queue.filter((q) => {
      const w = t - q.t;
      if (w > c.ab[0] && rnd() < c.ab[1] * (1 + (w - c.ab[0]) / 60)) {
        c.abn++;
        if (!quiet) pops.push({ ch: c.k, w, y: q.y, at: performance.now(), bad: true });
        addEvent(c, `<b>${esc(q.who)}</b> hung up after ${mmss(w)} · ${esc(q.intent)}`, 'var(--dsp-wall-alarm)');
        return false;
      }
      return true;
    });
    while (c.serving.length < c.n && c.queue.length) answer(c, c.queue.shift(), pick(AGENTS), quiet);
