  if (!quiet) pops.push({ ch: c.k, w, y: q.y, at: performance.now(), bad: false });
  if (w >= 30 || (w >= 10 && rnd() < 0.25)) addEvent(c, `<b>${esc(by)}</b> answered ${esc(q.who)} after ${mmss(w)} · ${esc(q.intent)}`, w > thr ? 'var(--dsp-wall-alarm)' : w > thr / 2 ? 'var(--dsp-wall-warn)' : 'var(--dsp-wall-ok)');
