/* warm the floor up so the wall opens mid-shift, not empty */
CHS.forEach((c) => { for (let i = 0; i < Math.round(c.n * 0.86); i++) c.serving.push(expo(c.aht)); });
const warm = { ans: CHS.map((c) => c.ans), within: CHS.map((c) => c.within), abn: CHS.map((c) => c.abn) };
t -= 900;
for (let i = 0; i < 900; i++) step(true);
CHS.forEach((c, k) => { c.ans = warm.ans[k] + c.live.ans; c.within = warm.within[k] + c.live.within; });
/* open on a believable moment: a short queue on voice and chat, messaging over its alarm line */
const OPEN = { voice: [96, 71, 52, 40, 22, 9, 3], chat: [38, 25, 12, 4], msg: [138, 121, 97, 80, 66, 41, 30, 14, 6], cb: [44, 12] };
CHS.forEach((c) => {
  c.queue = OPEN[c.k].map((w) => ({ id: ++cid, t: t - w, who: pick(PEOPLE), intent: pick(INTENTS[c.k]), born: 0, y: 0.12 + rnd() * 0.76 }));
  while (c.serving.length < c.n) c.serving.push(expo(c.aht));
