  if (surgeBtn.disabled) return;
  CHS[0].surge = 12;
  surgeBtn.disabled = true;
  surgeBtn.title = 'A surge is already running';
  $('span', surgeBtn).textContent = 'Surging…';
  addEvent(CHS[0], '<b>Surge test</b> — 12 extra calls queued to voice', 'var(--dsp-wall-warn)');
  paintEvents();
  toast('Surge test: twelve extra calls arrive on voice over the next few seconds.');
});
const pauseBtn = $('.dsp-wall__pause');
pauseBtn.addEventListener('click', () => {
  paused = !paused;
  pauseBtn.setAttribute('aria-pressed', String(paused));
  $('span', pauseBtn).textContent = paused ? 'Resume' : 'Pause';
  pauseBtn.querySelector('svg').innerHTML = paused ? '<path d="M8 5.5l10 6.5-10 6.5z"/>' : '<path d="M9 6v12M15 6v12"/>';
  if (paused) root.dataset.paused = ''; else { delete root.dataset.paused; tickAt = performance.now(); }
  startLoop();
});
const toastEl = $('.dsp-wall__toast');
let toastT = 0;
function toast(m) { toastEl.textContent = m; toastEl.classList.add('is-on'); clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('is-on'), 3200); }
root.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  const big = CHS.find((c) => c.el.classList.contains('is-big'));
  if (big) { expand(big); $('.dsp-wall__exp', big.el).focus(); }
  toastEl.classList.remove('is-on');
});

/* ---------- clock ---------- */
function frame() {
  clockEl.textContent = hms(t);
  paintTiles();
  paintHeat();
  paintEvents();
  if (CHS[0].surge === 0 && surgeBtn.disabled && !CHS[0].queue.some((q) => t - q.t < 3)) {
    surgeBtn.disabled = false; surgeBtn.title = 'Queue twelve extra calls on voice over ten seconds'; $('span', surgeBtn).textContent = 'Surge test';
  }
}
sizeCanvases();
frame();
draw(performance.now());
startLoop();

const io = new IntersectionObserver((es) => { onScreen = es[es.length - 1].isIntersecting; if (onScreen) startLoop(); });
io.observe(root);
const ro = new ResizeObserver(() => { if (!root.isConnected) return; sizeCanvases(); draw(performance.now()); });
CHS.forEach((c) => ro.observe(c.cv));
const onVis = () => { if (!root.isConnected) { stopAll(); return; } if (!document.hidden) { tickAt = performance.now(); startLoop(); } };
document.addEventListener('visibilitychange', onVis);
function stopAll() {
  clearInterval(timer);
  if (raf) cancelAnimationFrame(raf);
  raf = 0;
  io.disconnect(); ro.disconnect();
  document.removeEventListener('visibilitychange', onVis);
}
const timer = setInterval(() => {
  if (!root.isConnected) { stopAll(); return; }
  if (paused || document.hidden || !onScreen) return;
  step(false);
  tickAt = performance.now();
  frame();
  if (RM) draw(tickAt);
}, 1000);

css:
.dsp-macros {
  /* re-theme with these four */
  --dsp-macros-bg: oklch(0.972 0.012 115);
  --dsp-macros-ink: oklch(0.27 0.03 140);
  --dsp-macros-accent: oklch(0.6 0.14 42);
  --dsp-macros-bad: oklch(0.56 0.17 27);
  /* derived */
  --dsp-macros-card: color-mix(in oklch, var(--dsp-macros-bg), white 72%);
  --dsp-macros-rail: color-mix(in oklch, var(--dsp-macros-ink) 92%, var(--dsp-macros-accent));
  --dsp-macros-line: color-mix(in oklch, var(--dsp-macros-ink) 13%, transparent);
  --dsp-macros-hair: color-mix(in oklch, var(--dsp-macros-ink) 7%, transparent);
  --dsp-macros-mute: color-mix(in oklch, var(--dsp-macros-ink) 65%, var(--dsp-macros-bg));
  --dsp-macros-faint: color-mix(in oklch, var(--dsp-macros-ink) 45%, var(--dsp-macros-bg));
  --dsp-macros-good: color-mix(in oklch, oklch(0.58 0.11 150) 85%, var(--dsp-macros-ink));
  --dsp-macros-t1: oklch(0.58 0.1 245);
  --dsp-macros-t2: oklch(0.62 0.12 150);
  --dsp-macros-t3: oklch(0.7 0.13 85);
  --dsp-macros-t4: oklch(0.58 0.11 330);
  --dsp-macros-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dsp-macros-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dsp-macros-out: cubic-bezier(.2, .85, .25, 1);
  --dsp-macros-spring: linear(0, .07 2.5%, .28 6.6%, .62 12%, .92 18.6%, 1.06 25%, 1.08 31%, 1.04 39%, 1.006 51%, .998 65%, 1);
  width: 100%;
  height: var(--dsp-macros-h, 680px);
  container-type: inline-size;
  container-name: dsp-macros;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  background: var(--dsp-macros-bg);
  color: var(--dsp-macros-ink);
  font: 13px/1.45 var(--dsp-macros-sans);
  color-scheme: light;
  accent-color: var(--dsp-macros-accent);
  box-shadow: inset 0 0 0 1px var(--dsp-macros-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, ol, dl, dd) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dsp-macros-accent); outline-offset: 2px; border-radius: 6px; }
  & svg { flex: none; }
}
.dsp-macros__app {
  position: relative; height: 100%; display: grid;
  grid-template-columns: 76px minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "rail head" "rail kpis" "rail main";
}

/* ---------------------------------------------------------------- rail */
.dsp-macros__rail {
  grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 14px 8px; background: var(--dsp-macros-rail); color: var(--dsp-macros-bg);
  & button { width: 60px; display: grid; justify-items: center; gap: 3px; padding: 8px 2px; border-radius: 11px; font-size: 10.5px; font-weight: 600; color: color-mix(in oklch, var(--dsp-macros-bg) 62%, transparent); transition: background-color .18s, color .18s; }
  & button svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linejoin: round; stroke-linecap: round; }
  & button:hover { color: var(--dsp-macros-bg); background: color-mix(in oklch, var(--dsp-macros-bg) 8%, transparent); }
  & button[aria-current="page"] { color: var(--dsp-macros-ink); background: var(--dsp-macros-bg); }
  & :focus-visible { outline-color: var(--dsp-macros-bg); }
}
.dsp-macros__logo {
  width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; background: var(--dsp-macros-accent); margin-bottom: 10px;
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--dsp-macros-bg); stroke-width: 2; stroke-linecap: round; }
}

/* ---------------------------------------------------------------- head + kpis */
.dsp-macros__head { grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 10px 18px; padding: 16px 20px 10px; flex-wrap: wrap; }
.dsp-macros__title {
  & p { font-size: 11.5px; color: var(--dsp-macros-mute); }
  & h2 { font-size: clamp(19px, 1.5cqi + 6px, 25px); font-weight: 720; letter-spacing: -.03em; line-height: 1.15; text-wrap: balance; }
}
.dsp-macros__teams, .dsp-macros__seg {
  display: flex; gap: 4px; flex-wrap: wrap;
  & button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--dsp-macros-mute); box-shadow: inset 0 0 0 1px var(--dsp-macros-line); background: var(--dsp-macros-card); transition: background-color .15s, color .15s, box-shadow .15s; white-space: nowrap; }
  & button i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & button:hover { color: var(--dsp-macros-ink); box-shadow: inset 0 0 0 1px var(--dsp-macros-faint); }
  & button[aria-checked="true"] { background: var(--dsp-macros-ink); color: var(--dsp-macros-bg); box-shadow: none; }
}
.dsp-macros__seg button { height: 26px; font-size: 11.5px; }
.dsp-macros__kpis {
  grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; margin: 0 20px 12px; border-radius: 13px; background: var(--dsp-macros-card); box-shadow: inset 0 0 0 1px var(--dsp-macros-hair);
  & div { display: grid; gap: 0; padding: 10px 14px; border-left: 1px solid var(--dsp-macros-hair); min-width: 0; animation: dsp-macros-up .5s var(--dsp-macros-out) both; animation-delay: calc(var(--i) * 55ms); }
  & div:first-child { border-left: 0; }
  & span { font-size: 11px; font-weight: 600; color: var(--dsp-macros-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & b { font: 700 clamp(19px, 1.2cqi + 9px, 24px)/1.2 var(--dsp-macros-sans); letter-spacing: -.035em; font-variant-numeric: tabular-nums; }
  & small { font-size: 10.5px; color: var(--dsp-macros-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .bad { color: var(--dsp-macros-bad); }
  & .good { color: var(--dsp-macros-good); }
}
@keyframes dsp-macros-up { from { opacity: 0; translate: 0 8px; } }

/* ---------------------------------------------------------------- main */
.dsp-macros__main { grid-area: main; min-height: 0; min-width: 0; padding: 0 20px 18px; }
.dsp-macros__view { height: 100%; &[hidden] { display: none; } }
.dsp-macros__v-macros { display: grid; grid-template-columns: minmax(0, 1.12fr) minmax(0, 1fr); gap: 12px; }
.dsp-macros__plotcard, .dsp-macros__tablecard {
  min-height: 0; min-width: 0; display: flex; flex-direction: column; gap: 8px; padding: 12px 14px; border-radius: 14px; background: var(--dsp-macros-card); box-shadow: inset 0 0 0 1px var(--dsp-macros-hair);
}
.dsp-macros__v-kb .dsp-macros__tablecard { height: 100%; }
.dsp-macros__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 6px 12px; flex-wrap: wrap;
  & h3 { font-size: 13.5px; font-weight: 700; letter-spacing: -.01em; text-wrap: balance; }
}
.dsp-macros__hint { font-size: 11px; color: var(--dsp-macros-faint); text-wrap: pretty; }
.dsp-macros__plot {
  position: relative; flex: 1; min-height: 220px; cursor: crosshair; touch-action: none; user-select: none; border-radius: 10px;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  & .q { fill: transparent; }
  & .q.fix { fill: color-mix(in oklch, var(--dsp-macros-bad) 6%, transparent); }
  & .q.gem { fill: color-mix(in oklch, var(--dsp-macros-good) 6%, transparent); }
  & .ql { font: 650 10px var(--dsp-macros-sans); letter-spacing: .08em; text-transform: uppercase; fill: var(--dsp-macros-faint); }
  & .ql.fix { fill: color-mix(in oklch, var(--dsp-macros-bad), var(--dsp-macros-bg) 25%); }
  & .ax text { font: 500 10px var(--dsp-macros-mono); fill: var(--dsp-macros-faint); font-variant-numeric: tabular-nums; }
  & .ax line { stroke: var(--dsp-macros-hair); }
  & .ax .t { font: 600 10.5px var(--dsp-macros-sans); fill: var(--dsp-macros-mute); }
  & .split { stroke: var(--dsp-macros-ink); stroke-width: 1; stroke-dasharray: 4 4; opacity: .4; }
  & .dot { fill: var(--c); fill-opacity: .82; stroke: var(--dsp-macros-card); stroke-width: 1.5; cursor: pointer; transition: opacity .25s, r .3s var(--dsp-macros-spring), fill-opacity .2s; transform-box: fill-box; transform-origin: center; }
  & .dot.is-in { animation: dsp-macros-pop .6s var(--dsp-macros-spring) both; animation-delay: calc(var(--i) * 18ms + 120ms); }
  & .dot:hover, & .dot.is-focus { fill-opacity: 1; stroke: var(--dsp-macros-ink); stroke-width: 2; }
  & .dot.is-pin { stroke: var(--dsp-macros-accent); stroke-width: 2.5; }
  &[data-brushed] .dot:not(.is-sel) { opacity: .18; }
  &:focus-visible { outline-offset: 4px; }
}
@keyframes dsp-macros-pop { from { opacity: 0; scale: 0; } }
.dsp-macros__brush {
  position: absolute; left: 0; top: 0; pointer-events: none; border-radius: 4px;
  background: color-mix(in oklch, var(--dsp-macros-accent) 12%, transparent); box-shadow: inset 0 0 0 1.5px var(--dsp-macros-accent);
  &[hidden] { display: none; }
}
.dsp-macros__legend {
  display: flex; gap: 12px; flex-wrap: wrap; font-size: 11px; color: var(--dsp-macros-mute);
  & li { display: inline-flex; align-items: center; gap: 5px; }
  & li::before { content: ""; width: 9px; height: 9px; border-radius: 50%; background: var(--c); }
}
.dsp-macros__tbar { align-items: center; }
.dsp-macros__chip {
  display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 6px 0 10px; border-radius: 99px; font-size: 11.5px; font-weight: 650;
  background: color-mix(in oklch, var(--dsp-macros-accent) 16%, var(--dsp-macros-card)); color: color-mix(in oklch, var(--dsp-macros-accent), black 30%);
  & svg { width: 14px; height: 14px; padding: 3px; border-radius: 50%; stroke: currentColor; stroke-width: 2.4; fill: none; stroke-linecap: round; background: color-mix(in oklch, var(--dsp-macros-accent) 18%, transparent); }
  &[hidden] { display: none; }
  animation: dsp-macros-chip .35s var(--dsp-macros-spring);
}
@keyframes dsp-macros-chip { from { opacity: 0; scale: .7; } }
.dsp-macros__search {
  display: flex; align-items: center; gap: 6px; height: 28px; padding: 0 9px; border-radius: 8px; margin-left: auto; background: var(--dsp-macros-bg); box-shadow: inset 0 0 0 1px var(--dsp-macros-line);
  & svg { width: 14px; height: 14px; fill: none; stroke: var(--dsp-macros-faint); stroke-width: 2; stroke-linecap: round; }
  & input { border: 0; background: none; outline: none; width: 130px; font-size: 12px; }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--dsp-macros-accent); }
}
.dsp-macros__tscroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dsp-macros-line) transparent; margin: 0 -6px; }
.dsp-macros__table {
  width: 100%; border-collapse: collapse; font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dsp-macros-card); text-align: left; font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--dsp-macros-faint); padding: 2px 6px 7px; border-bottom: 1px solid var(--dsp-macros-line); white-space: nowrap; }
  & th button { text-transform: inherit; letter-spacing: inherit; font-weight: inherit; display: inline-flex; align-items: center; gap: 4px; border-radius: 4px; }
  & th button::after { content: ""; border: 4px solid transparent; border-top-color: currentColor; translate: 0 2px; opacity: 0; transition: rotate .25s var(--dsp-macros-out); }
  & th[aria-sort="descending"] button, & th[aria-sort="ascending"] button { color: var(--dsp-macros-ink); }
  & th[aria-sort="descending"] button::after { opacity: 1; }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: 180deg; translate: 0 -2px; }
  & .n { text-align: right; }
  & th.n button { flex-direction: row-reverse; }
  & td { padding: 6px; border-bottom: 1px solid var(--dsp-macros-hair); font-variant-numeric: tabular-nums; }
  & td.n { font-family: var(--dsp-macros-mono); font-size: 11.5px; }
  & tbody tr { cursor: pointer; transition: background-color .15s; }
  & tbody tr:hover, & tbody tr.is-hl { background: color-mix(in oklch, var(--dsp-macros-accent) 6%, transparent); }
  & tbody tr:focus-visible { outline-offset: -2px; }
  & .nm { display: flex; align-items: center; gap: 7px; min-width: 0; }
  & .nm i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); flex: none; }
  & .nm span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; font-weight: 560; }
  /* the name column takes whatever the numbers leave and truncates; numbers never clip */
  & th:first-child, & td:first-child { width: 100%; max-width: 0; }
  & td.n, & th.n { width: 1%; white-space: nowrap; }
  & .nm svg { width: 12px; height: 12px; fill: var(--dsp-macros-accent); }
  & .bad { color: var(--dsp-macros-bad); font-weight: 650; }
  & tbody tr.is-in { animation: dsp-macros-up .35s var(--dsp-macros-out) both; animation-delay: calc(var(--i) * 18ms); }
  & .empty td { text-align: center; color: var(--dsp-macros-faint); padding: 26px 6px; cursor: default; max-width: none; }
}

/* help centre */
.dsp-macros__funkey {
  display: flex; gap: 14px; font-size: 11px; color: var(--dsp-macros-mute);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 10px; height: 10px; border-radius: 3px; }
  & .v { background: color-mix(in oklch, var(--dsp-macros-ink) 14%, var(--dsp-macros-card)); }
  & .h { background: color-mix(in oklch, var(--dsp-macros-good) 45%, var(--dsp-macros-card)); }
  & .d { background: var(--dsp-macros-good); }
}
.dsp-macros__arts {
  flex: 1; min-height: 0; overflow: auto; display: grid; gap: 2px; align-content: start; scrollbar-width: thin; scrollbar-color: var(--dsp-macros-line) transparent; margin: 0 -6px; padding: 0 6px;
  & > li { border-bottom: 1px solid var(--dsp-macros-hair); animation: dsp-macros-up .4s var(--dsp-macros-out) both; animation-delay: calc(var(--i) * 25ms); }
  & .row { width: 100%; display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(160px, 1fr) 70px 64px 16px; align-items: center; gap: 12px; padding: 8px 4px; text-align: left; border-radius: 8px; transition: background-color .15s; }
  & .row:hover { background: color-mix(in oklch, var(--dsp-macros-accent) 5%, transparent); }
  & .t { display: grid; min-width: 0; line-height: 1.3; }
  & .t b { font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .t small { font-size: 11px; color: var(--dsp-macros-faint); }
  & .t small em { font-style: normal; color: var(--dsp-macros-accent); font-weight: 650; }
  & .fun { position: relative; height: 16px; border-radius: 4px; overflow: hidden; background: var(--dsp-macros-hair); }
  & .fun i { position: absolute; left: 0; top: 0; bottom: 0; width: calc(var(--w) * 100%); border-radius: 4px; transform-origin: left; animation: dsp-macros-grow .7s var(--dsp-macros-out) both; animation-delay: calc(var(--i) * 25ms + 100ms); }
  & .fun .v { background: color-mix(in oklch, var(--dsp-macros-ink) 14%, var(--dsp-macros-card)); }
  & .fun .h { background: color-mix(in oklch, var(--dsp-macros-good) 45%, var(--dsp-macros-card)); }
  & .fun .d { background: var(--dsp-macros-good); }
  & .num { text-align: right; font: 600 12px var(--dsp-macros-mono); font-variant-numeric: tabular-nums; }
  & .num small { display: block; font: 500 10px var(--dsp-macros-sans); color: var(--dsp-macros-faint); }
  & .chev { width: 14px; height: 14px; stroke: var(--dsp-macros-faint); fill: none; stroke-width: 2; transition: rotate .3s var(--dsp-macros-spring); }
  & .row[aria-expanded="true"] .chev { rotate: 180deg; }
  & .more { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--dsp-macros-out); }
  & .more > div { min-height: 0; overflow: hidden; }
  & li:has(.row[aria-expanded="true"]) .more { grid-template-rows: 1fr; }
  & .in { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 14px; padding: 4px 8px 12px; font-size: 12px; }
  & .in h4 { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--dsp-macros-faint); margin-bottom: 4px; }
  & .terms { display: flex; flex-wrap: wrap; gap: 4px; }
  & .terms span { padding: 2px 8px; border-radius: 99px; background: var(--dsp-macros-hair); font-size: 11.5px; }
  & .terms b { font: 600 10.5px var(--dsp-macros-mono); color: var(--dsp-macros-faint); margin-left: 4px; }
  & .acts { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
  & .ex { margin-top: 8px; padding: 8px 10px; border-radius: 8px; background: var(--dsp-macros-bg); box-shadow: inset 0 0 0 1px var(--dsp-macros-hair); color: var(--dsp-macros-mute); text-wrap: pretty; }
  & .ex[hidden] { display: none; }
}
@keyframes dsp-macros-grow { from { scale: 0 1; } }
.dsp-macros__btn {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 11px; border-radius: 8px; font-size: 12px; font-weight: 620; white-space: nowrap;
  background: var(--dsp-macros-card); box-shadow: inset 0 0 0 1px var(--dsp-macros-line); transition: background-color .15s, scale .2s var(--dsp-macros-spring);
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { background: color-mix(in oklch, var(--dsp-macros-card), var(--dsp-macros-ink) 5%); }
  &:active { scale: .96; }
  &[aria-pressed="true"] { background: var(--dsp-macros-ink); color: var(--dsp-macros-bg); box-shadow: none; }
  &.is-danger { color: var(--dsp-macros-bad); }
}

/* ---------------------------------------------------------------- drawer */
.dsp-macros__scrim {
  position: absolute; inset: 0; z-index: 20; background: color-mix(in oklch, var(--dsp-macros-ink) 22%, transparent); cursor: pointer;
  animation: dsp-macros-fade .3s both;
  &[hidden] { display: none; }
}
