  const ql = (txt, xx, yy, anchor, cls) => { svgEl('text', { class: 'ql ' + (cls || ''), x: xx, y: yy, 'text-anchor': anchor }, svg).textContent = txt; };
  ql('Fix first', W - r - 6, t + 14, 'end', 'fix');
  ql('Rewrite or retire', l + 6, t + 14, 'start');
  ql('Hidden gems', l + 6, H - b - 8, 'start');
  ql('Workhorses', W - r - 6, H - b - 8, 'end');
  const ms = M.filter(inTeam).slice().sort((a, b2) => b2.hrs - a.hrs);
  ms.forEach((m, k) => {
    const c = svgEl('circle', { class: 'dot' + (animate && !RM ? ' is-in' : '') + (m.pin ? ' is-pin' : '') + (brushed && brushed.has(m.id) ? ' is-sel' : ''), cx: x(m.uses), cy: y(m.reopen), r: (3.5 + Math.sqrt(m.hrs) * 0.9).toFixed(1), style: `--c:${TCOL[m.team]};--i:${k}`, 'data-id': m.id }, svg);
    c.appendChild(svgEl('title', {})).textContent = m.name;
  });
  if (brushed) plot.dataset.brushed = ''; else delete plot.dataset.brushed;
  G = { x, y, W, H, l, r, t, b };
  $('.dsp-macros__legend').innerHTML = TEAMS.filter(([tm]) => team === 'all' || tm === team).map(([tm, c]) => `<li style="--c:${c}">${tm}</li>`).join('');
}
const tip = $('.dsp-macros__tip');
function placeTip(cx, cy) {
  const r0 = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let px = cx - r0.left + 14, py = cy - r0.top - h - 12;
  if (px + w > r0.width - 8) px = cx - r0.left - w - 14;
  if (py < 8) py = cy - r0.top + 18;
  tip.style.translate = `${Math.round(px)}px ${Math.round(py)}px`;
}
function macroTip(m, cx, cy) {
  tip.innerHTML = `<b>${esc(m.name)}</b><div class="r"><span>${m.team} · ${QNAME[quadrant(m, avgReopen())]}</span></div><div class="r"><span>Uses</span>${fmtN(m.uses)}</div><div class="r"><span>Reopened</span>${pct(m.reopen)}</div><div class="r"><span>CSAT after</span>${pct(m.csat, 0)}</div><div class="r"><span>Time saved</span>${m.hrs.toFixed(1)} h</div>`;
  tip.hidden = false; placeTip(cx, cy);
}
plot.addEventListener('pointermove', (e) => {
  if (drag) return;
  const d = e.target.closest('.dot');
  if (!d) { tip.hidden = true; hlRow(null); return; }
  const m = M.find((x) => x.id === +d.dataset.id);
  macroTip(m, e.clientX, e.clientY);
  hlRow(m.id);
});
plot.addEventListener('pointerleave', () => { tip.hidden = true; hlRow(null); });
function hlRow(id) { $$('.dsp-macros__table tbody tr').forEach((tr) => tr.classList.toggle('is-hl', +tr.dataset.id === id)); }

/* drag to brush */
let drag = null;
plot.addEventListener('pointerdown', (e) => {
  if (e.button !== 0 || e.target.closest('.dot')) return;
  const rb = plot.getBoundingClientRect();
  drag = { x0: e.clientX - rb.left, y0: e.clientY - rb.top, rb, moved: false };
  plot.setPointerCapture(e.pointerId);
  tip.hidden = true;
});
plot.addEventListener('pointermove', (e) => {
  if (!drag) return;
  const x1 = e.clientX - drag.rb.left, y1 = e.clientY - drag.rb.top;
  if (Math.abs(x1 - drag.x0) + Math.abs(y1 - drag.y0) > 4) drag.moved = true;
  if (!drag.moved) return;
  brushEl.hidden = false;
  const x = Math.min(drag.x0, x1), y = Math.min(drag.y0, y1);
  brushEl.style.translate = `${x}px ${y}px`;
  brushEl.style.width = Math.abs(x1 - drag.x0) + 'px';
  brushEl.style.height = Math.abs(y1 - drag.y0) + 'px';
  drag.box = [x, y, x + Math.abs(x1 - drag.x0), y + Math.abs(y1 - drag.y0)];
});
function endDrag() {
  if (!drag) return;
  const d = drag; drag = null;
  brushEl.hidden = true;
  if (!d.moved || !d.box) return;
  const sc = d.rb.width / G.W;
  const set = new Set(M.filter(inTeam).filter((m) => { const px = G.x(m.uses) * sc, py = G.y(m.reopen) * (d.rb.height / G.H); return px >= d.box[0] && px <= d.box[2] && py >= d.box[1] && py <= d.box[3]; }).map((m) => m.id));
  brushed = set.size ? set : null;
  render(false);
  if (!set.size) toast('Nothing inside that box — selection cleared.');
}
plot.addEventListener('pointerup', endDrag);
plot.addEventListener('pointercancel', () => { drag = null; brushEl.hidden = true; });
plot.addEventListener('click', (e) => {
  const d = e.target.closest('.dot');
  if (d) { openDrawer(+d.dataset.id, plot); }
});
plot.addEventListener('keydown', (e) => {
  const ms = M.filter(inTeam);
  if (!ms.length) return;
  const byX = ms.slice().sort((a, b) => a.uses - b.uses), byY = ms.slice().sort((a, b) => a.reopen - b.reopen);
  const cur = ms.find((m) => m.id === focusIdx) || byX[0];
  let nx = null;
  if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') nx = byX[Math.max(0, Math.min(byX.length - 1, byX.indexOf(cur) + (e.key === 'ArrowRight' ? 1 : -1)))];
  else if (e.key === 'ArrowUp' || e.key === 'ArrowDown') nx = byY[Math.max(0, Math.min(byY.length - 1, byY.indexOf(cur) + (e.key === 'ArrowUp' ? 1 : -1)))];
  else if ((e.key === 'Enter' || e.key === ' ') && focusIdx >= 0) { e.preventDefault(); openDrawer(focusIdx, plot); return; }
  else if (e.key === 'Escape' && brushed) { brushed = null; render(false); return; }
  else return;
  e.preventDefault();
  if (focusIdx < 0) nx = cur;
  focusIdx = nx.id;
  $$('.dot', svg).forEach((c) => c.classList.toggle('is-focus', +c.dataset.id === focusIdx));
  const c = $(`.dot[data-id="${focusIdx}"]`, svg), rb = c.getBoundingClientRect();
  macroTip(nx, rb.left + rb.width / 2, rb.top);
  hlRow(nx.id);
});
plot.addEventListener('blur', () => { focusIdx = -1; $$('.dot.is-focus', svg).forEach((c) => c.classList.remove('is-focus')); tip.hidden = true; hlRow(null); });

/* ---------- table ---------- */
const tbody = $('.dsp-macros__table tbody');
const PIN = '<svg viewBox="0 0 12 12" aria-label="Pinned"><path d="M7.5 1l3.5 3.5-2 .7-2.2 2.2.3 2.6-1 1L4.4 9.3 1.6 12 1 11.4l2.7-2.8L1 6l1-1 2.6.3L6.8 3l.7-2z"/></svg>';
function table(animate) {
  const ms = M.filter((m) => inTeam(m) && (!brushed || brushed.has(m.id)) && (!query || m.name.toLowerCase().includes(query)));
  const k = sortK.k;
  ms.sort((a, b) => (k === 'name' ? a.name.localeCompare(b.name) : a[k] - b[k]) * sortK.dir);
  const avg = avgReopen();
  tbody.innerHTML = ms.length ? ms.map((m, i) => `<tr data-id="${m.id}" tabindex="${i === 0 ? 0 : -1}" class="${animate && !RM && i < 14 ? 'is-in' : ''}" style="--i:${i};--c:${TCOL[m.team]}" aria-label="${esc(m.name)}: ${fmtN(m.uses)} uses, ${pct(m.reopen)} reopened. Open details">
      <td><span class="nm"><i></i><span>${esc(m.name)}</span>${m.pin ? PIN : ''}</span></td>
      <td class="n">${fmtN(m.uses)}</td>
      <td class="n ${m.reopen >= avg && m.uses >= SPLIT_USES ? 'bad' : ''}">${pct(m.reopen)}</td>
      <td class="n">${pct(m.csat, 0)}</td>
      <td class="n">${m.hrs.toFixed(1)}h</td></tr>`).join('')
    : `<tr class="empty"><td colspan="5">No macros match${query ? ` “${esc(query)}”` : ''}. Clear the search or the selection.</td></tr>`;
  $('[data-k="tcount"]').textContent = `${ms.length} macro${ms.length === 1 ? '' : 's'}${brushed ? ' in your selection' : team === 'all' ? '' : ' · ' + team}`;
  const chip = $('[data-act="clear"]');
  chip.hidden = !brushed;
  if (brushed) $('[data-k="selchip"]').textContent = `Clear selection of ${brushed.size}`;
  $$('.dsp-macros__table th[aria-sort]').forEach((th) => { const s = $('button', th).dataset.s; th.setAttribute('aria-sort', s === k ? (sortK.dir < 0 ? 'descending' : 'ascending') : 'none'); });
}
$('.dsp-macros__table thead').addEventListener('click', (e) => {
  const b = e.target.closest('button[data-s]'); if (!b) return;
  const k = b.dataset.s;
  sortK = { k, dir: sortK.k === k ? -sortK.dir : k === 'name' ? 1 : -1 };
  const before = new Map($$('tr[data-id]', tbody).map((tr) => [tr.dataset.id, tr.getBoundingClientRect().top]));
  table(false);
  if (!RM) $$('tr[data-id]', tbody).forEach((tr) => { const b0 = before.get(tr.dataset.id); if (b0 == null) return; const dy = b0 - tr.getBoundingClientRect().top; if (dy) tr.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.2,.85,.25,1)' }); });
});
tbody.addEventListener('click', (e) => { const tr = e.target.closest('tr[data-id]'); if (tr) openDrawer(+tr.dataset.id, tr); });
tbody.addEventListener('keydown', (e) => {
  const tr = e.target.closest('tr[data-id]'); if (!tr) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openDrawer(+tr.dataset.id, tr); return; }
  if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
  e.preventDefault();
  const rows = $$('tr[data-id]', tbody), n = rows[Math.max(0, Math.min(rows.length - 1, rows.indexOf(tr) + (e.key === 'ArrowDown' ? 1 : -1)))];
  rows.forEach((x) => { x.tabIndex = -1; }); n.tabIndex = 0; n.focus();
});
tbody.addEventListener('pointerover', (e) => { const tr = e.target.closest('tr[data-id]'); $$('.dot', svg).forEach((c) => c.classList.toggle('is-focus', tr && +c.dataset.id === +tr.dataset.id)); });
tbody.addEventListener('pointerleave', () => $$('.dot.is-focus', svg).forEach((c) => c.classList.remove('is-focus')));
$('[data-act="clear"]').addEventListener('click', () => { brushed = null; render(false); plot.focus(); });
const search = $('.dsp-macros__search input');
search.addEventListener('input', () => { query = search.value.trim().toLowerCase(); table(false); });

/* ---------- drawer ---------- */
const drawer = $('.dsp-macros__drawer'), scrim = $('.dsp-macros__scrim');
let returnFocus = null;
function openDrawer(id, from) {
  const m = M.find((x) => x.id === id); if (!m) return;
  drawerFor = id; returnFocus = from || null;
  tip.hidden = true;
  const avg = avgReopen(), q = quadrant(m, avg);
  const body = esc(`Hi {{ticket.requester.first_name}},\n\n${m.line}\n\nIf anything still looks off, just reply here and I’ll pick it up.\n\n{{current_user.first_name}}\nSaltmarsh Scheduling support`).replace(/\{\{([^}]+)\}\}/g, '<mark>$1</mark>');
  const why = q === 'fix' ? `Used ${fmtN(m.uses)} times with <b>${pct(m.reopen)}</b> reopening against a ${pct(avg)} average — every point here costs about ${Math.round(m.uses / 100)} extra tickets a month.`
    : q === 'retire' ? `Rarely used and <b>${pct(m.reopen)}</b> reopen. Rewrite it around the question customers actually ask, or retire it.`
    : q === 'gem' ? `Only ${fmtN(m.uses)} uses, but it closes cleanly. Pin it or suggest it on matching tickets.`
    : `A dependable closer: ${fmtN(m.uses)} uses, <b>${pct(m.reopen)}</b> reopen and ${m.hrs.toFixed(0)} hours saved this month.`;
  drawer.innerHTML = `
    <button type="button" class="dsp-macros__x" data-act="close" aria-label="Close macro detail"><svg viewBox="0 0 14 14"><path d="M3 3l8 8M11 3l-8 8"/></svg></button>
    <div><p class="dsp-macros__meta" style="--c:${TCOL[m.team]}"><i></i>${m.team} · edited ${m.edited}<span class="dsp-macros__quad ${q}">${QNAME[q]}</span></p><h3>${esc(m.name)}</h3></div>
    <div class="dsp-macros__stats"><div><span>Uses</span><b>${fmtN(m.uses)}</b></div><div><span>Reopened</span><b class="${q === 'fix' || q === 'retire' ? 'bad' : ''}">${pct(m.reopen)}</b></div><div><span>CSAT after</span><b>${pct(m.csat, 0)}</b></div><div><span>Saved / use</span><b>${m.saved.toFixed(1)}m</b></div></div>
    <p class="dsp-macros__why">${why}</p>
    <div><h4>What the customer receives</h4><div class="dsp-macros__body">${body}</div></div>
    <div class="dsp-macros__dacts">
      <button type="button" class="dsp-macros__btn" data-act="pin" aria-pressed="${m.pin}">${m.pin ? 'Pinned to top' : 'Pin to top'}</button>
      <button type="button" class="dsp-macros__btn" data-act="flag" aria-pressed="${m.flag}">${m.flag ? 'Flagged for rewrite' : 'Flag for rewrite'}</button>
      <button type="button" class="dsp-macros__btn is-danger" data-act="archive">Archive</button>
