    toast(m.pin ? `“${m.name}” now sits at the top of every agent’s macro list.` : `“${m.name}” unpinned.`);
    render(false);
  } else if (a.dataset.act === 'flag') {
    m.flag = !m.flag; a.setAttribute('aria-pressed', String(m.flag)); a.textContent = m.flag ? 'Flagged for rewrite' : 'Flag for rewrite';
    toast(m.flag ? `Flagged — the ${m.team} content owner gets it in Monday’s review.` : 'Flag removed.');
  } else if (a.dataset.act === 'archive') {
    const idx = M.indexOf(m);
