/* ---------- help centre ---------- */
const artsEl = $('.dsp-macros__arts');
const CHEV = '<svg class="chev" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 6l4 4 4-4"/></svg>';
function kb() {
  const as = ARTS.filter(inTeam).map((a) => ({ ...a, deflected: a.views * a.ss, rate: a.ss }));
  as.sort((a, b) => b[artSort] - a[artSort]);
  artsEl.innerHTML = as.map((a, i) => `<li style="--i:${i}" data-id="${a.id}">
    <button type="button" class="row" aria-expanded="${openArt === a.id}">
