      <span class="fun" role="img" aria-label="${fmtN(a.views)} views, ${pct(a.read, 0)} read to the end, ${pct(a.ss, 0)} raised no ticket"><i class="v" style="--w:1;--i:${i}"></i><i class="h" style="--w:${a.read};--i:${i}"></i><i class="d" style="--w:${a.ss};--i:${i}"></i></span>
      <span class="num v30">${fmtN(a.views)}<small>views</small></span>
      <span class="num">${pct(a.ss, 0)}<small>self-serve</small></span>${CHEV}
    </button>
    <div class="more"><div>${openArt === a.id ? artDetail(a) : ''}</div></div></li>`).join('');
}
function artDetail(a) {
  return `<div class="in">
    <div><h4>Searches that land here</h4><div class="terms">${a.terms.map(([t, n]) => `<span>${esc(t)}<b>${fmtN(n)}</b></span>`).join('')}</div>
      <div class="acts">
        <button type="button" class="dsp-macros__btn" data-art-act="review" aria-pressed="${a.review}">${a.review ? 'Marked for review' : 'Mark for review'}</button>
        <button type="button" class="dsp-macros__btn" data-art-act="preview" aria-expanded="false">Preview</button>
      </div>
      <p class="ex" hidden>${esc(a.title)} — this guide walks through the steps with screenshots and ends with what to check if something still looks wrong. ${fmtN(Math.round(a.views * a.read))} readers reached the end this month.</p></div>
    <div><h4>Votes</h4><p>${pct(a.helpful, 0)} of ${fmtN(a.votes)} voters found it helpful. ${fmtN(Math.round(a.views * a.read))} of ${fmtN(a.views)} readers (${pct(a.read, 0)}) reached the end; ${fmtN(Math.round(a.views * a.ss))} (${pct(a.ss, 0)}) raised no ticket within a day.</p></div>
  </div>`;
}
artsEl.addEventListener('click', (e) => {
  const li = e.target.closest('li[data-id]'); if (!li) return;
  const a = ARTS[+li.dataset.id];
  const act = e.target.closest('[data-art-act]');
  if (act) {
    if (act.dataset.artAct === 'review') {
      a.review = !a.review;
      act.setAttribute('aria-pressed', String(a.review)); act.textContent = a.review ? 'Marked for review' : 'Mark for review';
      $('.t small', li).innerHTML = `${a.team} · updated ${a.updated}${a.review ? ' · <em>due for review</em>' : ''}`;
      kpis();
      toast(a.review ? `“${a.title}” added to the content review list.` : 'Removed from the review list.');
    } else {
      const ex = $('.ex', li), open = ex.hidden;
