/* ---------- render ---------- */
function render(animate) {
  kpis();
  if (view === 'macros') { scatter(animate); table(animate); } else kb();
}
render(true);
let lw = plot.clientWidth, lh = plot.clientHeight;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const w = plot.clientWidth, h = plot.clientHeight;
  if (view === 'macros' && w && (Math.abs(w - lw) > 3 || Math.abs(h - lh) > 3)) { lw = w; lh = h; scatter(false); }
});
ro.observe(plot);

