@property --dsp-survival-a {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.dsp-survival {
  /* re-theme with these four; the segment hues below are optional */
  --dsp-survival-bg: oklch(0.205 0.02 168);
  --dsp-survival-ink: oklch(0.95 0.016 95);
  --dsp-survival-accent: oklch(0.84 0.15 82);
  --dsp-survival-bad: oklch(0.7 0.17 33);
  --dsp-survival-s1: oklch(0.8 0.09 235);
  --dsp-survival-s2: oklch(0.77 0.12 0);
  --dsp-survival-s3: oklch(0.83 0.13 145);
  --dsp-survival-s4: oklch(0.74 0.11 300);
  /* derived */
  --dsp-survival-card: color-mix(in oklch, var(--dsp-survival-bg), var(--dsp-survival-ink) 4.5%);
  --dsp-survival-raise: color-mix(in oklch, var(--dsp-survival-bg), var(--dsp-survival-ink) 9%);
  --dsp-survival-line: color-mix(in oklch, var(--dsp-survival-ink) 14%, transparent);
  --dsp-survival-hair: color-mix(in oklch, var(--dsp-survival-ink) 7.5%, transparent);
  --dsp-survival-mute: color-mix(in oklch, var(--dsp-survival-ink) 68%, var(--dsp-survival-bg));
  --dsp-survival-faint: color-mix(in oklch, var(--dsp-survival-ink) 46%, var(--dsp-survival-bg));
  --dsp-survival-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dsp-survival-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dsp-survival-out: cubic-bezier(.2, .85, .25, 1);
  --dsp-survival-io: cubic-bezier(.65, 0, .35, 1);
  --dsp-survival-spring: linear(0, .07 2.5%, .28 6.6%, .62 12%, .92 18.6%, 1.06 25%, 1.08 31%, 1.04 39%, 1.006 51%, .998 65%, 1);
  width: 100%;
  height: var(--dsp-survival-h, 680px);
  container-type: inline-size;
  container-name: dsp-survival;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  border-radius: 18px;
  background:
    radial-gradient(90% 60% at 100% 0%, color-mix(in oklch, var(--dsp-survival-accent) 7%, transparent), transparent 70%),
    var(--dsp-survival-bg);
  color: var(--dsp-survival-ink);
  font: 13px/1.45 var(--dsp-survival-sans);
  color-scheme: dark;
  accent-color: var(--dsp-survival-accent);
  box-shadow: inset 0 0 0 1px var(--dsp-survival-hair);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, ol, dl, dd, dt) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(button:disabled) { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dsp-survival-accent); outline-offset: 2px; border-radius: 6px; }
  & svg { flex: none; }
}

/* ------------------------------------------------------------------ top bar */
.dsp-survival__top {
  display: flex; align-items: center; gap: 10px 18px; flex-wrap: wrap; padding: 14px 20px 12px;
  border-bottom: 1px solid var(--dsp-survival-hair);
}
.dsp-survival__brand {
  display: flex; align-items: center; gap: 11px; margin-right: auto; min-width: 0;
  & p { font-size: 11.5px; color: var(--dsp-survival-faint); letter-spacing: .01em; }
  & h2 { font-size: clamp(17px, 1.1cqi + 7px, 21px); font-weight: 680; letter-spacing: -.025em; line-height: 1.15; text-wrap: balance; }
}
.dsp-survival__mark {
  width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; flex: none;
  background: var(--dsp-survival-accent); color: var(--dsp-survival-bg);
  & svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
}
.dsp-survival__tabs {
  display: flex; gap: 2px; padding: 3px; border-radius: 11px; background: var(--dsp-survival-card); box-shadow: inset 0 0 0 1px var(--dsp-survival-hair);
  & button { position: relative; display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 12px; border-radius: 8px; font-weight: 600; font-size: 12.5px; color: var(--dsp-survival-mute); transition: color .2s, background-color .2s; }
  & button svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & button:hover { color: var(--dsp-survival-ink); }
  & button[aria-selected="true"] { color: var(--dsp-survival-ink); background: var(--dsp-survival-raise); box-shadow: 0 1px 0 color-mix(in oklch, var(--dsp-survival-ink) 8%, transparent) inset, 0 4px 12px -6px oklch(0 0 0 / .6); }
}
.dsp-survival__count {
  min-width: 22px; height: 18px; padding: 0 6px; border-radius: 99px; display: inline-grid; place-items: center;
  font: 650 10.5px/1 var(--dsp-survival-mono); font-variant-numeric: tabular-nums;
  background: color-mix(in oklch, var(--dsp-survival-bad) 22%, transparent); color: color-mix(in oklch, var(--dsp-survival-bad), var(--dsp-survival-ink) 35%);
}
.dsp-survival__ctl { display: flex; gap: 8px; flex-wrap: wrap; }
.dsp-survival__seg {
  display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dsp-survival-card); box-shadow: inset 0 0 0 1px var(--dsp-survival-hair);
  & button { height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dsp-survival-mute); white-space: nowrap; transition: color .18s, background-color .18s, box-shadow .18s; }
  & button:hover { color: var(--dsp-survival-ink); }
  & button[aria-checked="true"] { background: var(--dsp-survival-ink); color: var(--dsp-survival-bg); }
}
.dsp-survival__seg--sm button { height: 24px; padding: 0 9px; font-size: 11.5px; }

/* ------------------------------------------------------------------ body */
.dsp-survival__body {
  min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; padding: 12px 20px 16px;
  scrollbar-width: thin; scrollbar-color: var(--dsp-survival-line) transparent;
}
.dsp-survival__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-template-rows: auto auto auto; column-gap: 10px;
}
.dsp-survival__kpi {
  grid-row: span 3; display: grid; grid-template-rows: subgrid; row-gap: 1px; min-width: 0;
  padding: 10px 14px 11px; border-radius: 13px; background: var(--dsp-survival-card); box-shadow: inset 0 0 0 1px var(--dsp-survival-hair);
  animation: dsp-survival-up .55s var(--dsp-survival-out) both; animation-delay: calc(var(--i) * 60ms);
  & > span { font-size: 11px; font-weight: 600; letter-spacing: .02em; color: var(--dsp-survival-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & > b { display: flex; align-items: center; gap: 9px; font: 650 clamp(19px, 1.1cqi + 9px, 24px)/1.15 var(--dsp-survival-sans); letter-spacing: -.035em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & > small { font-size: 11px; color: var(--dsp-survival-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .bad { color: color-mix(in oklch, var(--dsp-survival-bad), var(--dsp-survival-ink) 12%); }
}
.dsp-survival__gauge {
  --dsp-survival-a: 0deg;
  width: 22px; height: 22px; border-radius: 50%; flex: none;
  background: conic-gradient(var(--dsp-survival-accent) var(--dsp-survival-a), color-mix(in oklch, var(--dsp-survival-ink) 12%, transparent) 0);
  -webkit-mask: radial-gradient(circle, transparent 50%, #000 52%);
  mask: radial-gradient(circle, transparent 50%, #000 52%);
  transition: --dsp-survival-a .9s var(--dsp-survival-out);
  @starting-style { --dsp-survival-a: 0deg; }
}
@keyframes dsp-survival-up { from { opacity: 0; translate: 0 8px; } }
@keyframes dsp-survival-fade { from { opacity: 0; } }

.dsp-survival__view { min-height: 0; &[hidden] { display: none; } }
.dsp-survival__v-curves {
  display: grid; gap: 12px;
  grid-template-columns: minmax(0, 1fr) clamp(286px, 31cqi, 356px);
  grid-template-areas: "chart side";
}

/* ------------------------------------------------------------------ chart card */
.dsp-survival__chartcard {
  grid-area: chart; min-height: 0; min-width: 0; display: flex; flex-direction: column; gap: 6px;
  padding: 12px 14px 8px; border-radius: 15px; background: var(--dsp-survival-card); box-shadow: inset 0 0 0 1px var(--dsp-survival-hair);
}
.dsp-survival__ch { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px 14px; flex-wrap: wrap; }
.dsp-survival__cht {
  min-width: 0;
  & h3 { font-size: 13.5px; font-weight: 680; letter-spacing: -.01em; text-wrap: balance; }
  & p { font-size: 11px; color: var(--dsp-survival-faint); text-wrap: pretty; display: flex; align-items: center; gap: 5px; flex-wrap: wrap; }
}
.dsp-survival__ckey { width: 2px; height: 10px; background: var(--dsp-survival-mute); border-radius: 1px; display: inline-block; }
.dsp-survival__opts { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.dsp-survival__switch {
  display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 10px 0 6px; border-radius: 9px; font-size: 11.5px; font-weight: 600; color: var(--dsp-survival-mute);
  box-shadow: inset 0 0 0 1px var(--dsp-survival-hair); background: var(--dsp-survival-card); transition: color .18s;
  & i { position: relative; width: 26px; height: 16px; border-radius: 99px; background: color-mix(in oklch, var(--dsp-survival-ink) 16%, transparent); transition: background-color .25s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--dsp-survival-ink); transition: translate .35s var(--dsp-survival-spring); }
  &[aria-checked="true"] { color: var(--dsp-survival-ink); }
  &[aria-checked="true"] i { background: var(--dsp-survival-accent); }
  &[aria-checked="true"] i::after { translate: 10px 0; background: var(--dsp-survival-bg); }
}
.dsp-survival__chart {
  position: relative; flex: 1; min-height: 250px; outline-offset: 3px; cursor: crosshair; touch-action: pan-y; user-select: none; -webkit-user-select: none;
  & > svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
  & .grid line { stroke: var(--dsp-survival-hair); }
  & .grid line.mid { stroke: var(--dsp-survival-line); stroke-dasharray: 3 4; }
  & .grid text, & .xax text { font: 500 10px var(--dsp-survival-mono); fill: var(--dsp-survival-faint); font-variant-numeric: tabular-nums; }
  & .xax line.v { stroke: var(--dsp-survival-hair); }
  & .xax line.base { stroke: var(--dsp-survival-line); }
  & .cap { font: 650 9.5px var(--dsp-survival-sans); letter-spacing: .08em; text-transform: uppercase; fill: var(--dsp-survival-faint); }
  & .midlbl { font: 600 9.5px var(--dsp-survival-sans); fill: var(--dsp-survival-faint); letter-spacing: .04em; }
  & .tgz { fill: color-mix(in oklch, var(--dsp-survival-accent) 6%, transparent); }
  & .tgl { stroke: var(--dsp-survival-accent); stroke-width: 1.5; }
  & .tgd { fill: var(--dsp-survival-bg); stroke: var(--c); stroke-width: 2; }
  & .xhl { stroke: var(--dsp-survival-ink); stroke-opacity: .55; stroke-dasharray: 2 3; }
  & .xhd { fill: var(--c); stroke: var(--dsp-survival-bg); stroke-width: 2; }
  & .risk .rh { font: 650 9.5px var(--dsp-survival-sans); letter-spacing: .08em; text-transform: uppercase; fill: var(--dsp-survival-faint); }
  & .risk .rl { font: 600 10.5px var(--dsp-survival-sans); fill: var(--c); }
  & .risk .rn { font: 500 10px var(--dsp-survival-mono); fill: var(--dsp-survival-mute); font-variant-numeric: tabular-nums; }
  & .risk line { stroke: var(--dsp-survival-hair); }
  & .risk g { transition: opacity .25s; }
  & .risk.is-in g { animation: dsp-survival-fade .5s var(--dsp-survival-out) both; animation-delay: calc(var(--i) * 90ms + 350ms); }
}
.dsp-survival__curve {
  transition: opacity .3s var(--dsp-survival-out);
  & .band { fill: var(--c); fill-opacity: .13; transition: fill-opacity .3s; }
  & .line { fill: none; stroke: var(--c); stroke-width: 2; stroke-linejoin: round; }
  & .cens { fill: none; stroke: var(--c); stroke-width: 1.3; stroke-opacity: .85; }
  & .med line { stroke: var(--c); stroke-dasharray: 2 3; stroke-opacity: .55; }
  & .med circle { fill: var(--dsp-survival-bg); stroke: var(--c); stroke-width: 2; }
  & .med text { font: 650 10.5px var(--dsp-survival-mono); fill: var(--c); paint-order: stroke; stroke: var(--dsp-survival-card); stroke-width: 4px; stroke-linejoin: round; opacity: 0; transition: opacity .25s; }
  &.is-focus .med text { opacity: 1; }
  &.is-focus .line { stroke-width: 2.6; }
  &.is-focus .band { fill-opacity: .2; }
  &.is-in { animation: dsp-survival-wipe 1.15s var(--dsp-survival-io) both; animation-delay: calc(var(--i) * 110ms); }
  &.is-in .med { animation: dsp-survival-fade .4s var(--dsp-survival-out) both; animation-delay: calc(var(--i) * 110ms + 900ms); }
}
@keyframes dsp-survival-wipe { from { clip-path: inset(-6px 100% -6px -6px); } to { clip-path: inset(-6px -6px -6px -6px); } }
.dsp-survival__chart:not([data-band]) .band { fill-opacity: 0; }
.dsp-survival__chart:has(.dsp-survival__curve.is-focus) .dsp-survival__curve:not(.is-focus),
.dsp-survival__chart:has(.dsp-survival__curve.is-peek) .dsp-survival__curve:not(.is-peek) { opacity: .2; }
.dsp-survival__chart:has(.dsp-survival__curve.is-focus) .risk g:not(.is-focus) { opacity: .35; }

.dsp-survival__handle {
  position: absolute; left: 0; top: 0; width: 18px; margin-left: -9px; cursor: ew-resize; touch-action: none; z-index: 2;
  & span {
    position: absolute; left: 50%; top: 0; translate: -50% 0; white-space: nowrap; height: 20px; padding: 0 8px; border-radius: 99px; display: grid; place-items: center;
    font: 700 10.5px/1 var(--dsp-survival-mono); font-variant-numeric: tabular-nums; color: var(--dsp-survival-bg); background: var(--dsp-survival-accent);
    box-shadow: 0 6px 16px -8px oklch(0 0 0 / .8); transition: scale .25s var(--dsp-survival-spring);
  }
  &:hover span, &.is-drag span { scale: 1.08; }
  &:focus-visible { outline: none; }
  &:focus-visible span { outline: 2px solid var(--dsp-survival-ink); outline-offset: 2px; }
}
.dsp-survival__tip {
  position: absolute; left: 0; top: 0; z-index: 3; min-width: 190px; padding: 9px 11px 8px; border-radius: 11px; pointer-events: none;
  background: color-mix(in oklch, var(--dsp-survival-bg), black 30%); box-shadow: 0 0 0 1px var(--dsp-survival-line), 0 14px 30px -12px oklch(0 0 0 / .8);
  font-size: 11.5px; transition: opacity .15s;
  &[hidden] { display: block; opacity: 0; visibility: hidden; }
  & > b { display: block; font-weight: 650; margin-bottom: 5px; font-size: 11.5px; }
  & > div { display: grid; grid-template-columns: 9px minmax(0, 1fr) auto; column-gap: 7px; align-items: baseline; padding: 1px 0; }
  & i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); align-self: center; }
  & em { font: 650 11.5px var(--dsp-survival-mono); font-style: normal; font-variant-numeric: tabular-nums; text-align: right; }
  & small { grid-column: 2 / -1; font-size: 10.5px; color: var(--dsp-survival-faint); margin-top: -2px; }
  & p { margin-top: 5px; padding-top: 5px; border-top: 1px solid var(--dsp-survival-hair); font-size: 10.5px; color: var(--dsp-survival-accent); }
}

/* ------------------------------------------------------------------ side */
.dsp-survival__side {
  grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 12px;
  scrollbar-width: thin; scrollbar-color: var(--dsp-survival-line) transparent; overscroll-behavior: contain;
}
.dsp-survival__segcard, .dsp-survival__detail {
  padding: 12px 14px; border-radius: 15px; background: var(--dsp-survival-card); box-shadow: inset 0 0 0 1px var(--dsp-survival-hair);
}
.dsp-survival__ph {
  display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 6px;
  & h3 { font-size: 13.5px; font-weight: 680; }
  & span { font-size: 11px; color: var(--dsp-survival-faint); }
}
.dsp-survival__segs {
  width: 100%; border-collapse: collapse; font-size: 12px;
  & thead th { text-align: left; padding: 4px 4px 7px; font-size: 10px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--dsp-survival-faint); border-bottom: 1px solid var(--dsp-survival-line); white-space: nowrap; }
  & th button { display: inline-flex; align-items: center; gap: 4px; text-transform: inherit; letter-spacing: inherit; font-weight: inherit; border-radius: 4px; transition: color .15s; }
  & th button:hover { color: var(--dsp-survival-ink); }
  & th button::after { content: ""; border: 3.5px solid transparent; border-top-color: currentColor; translate: 0 2px; opacity: 0; transition: rotate .3s var(--dsp-survival-out), opacity .2s; }
  & th[aria-sort="descending"] button, & th[aria-sort="ascending"] button { color: var(--dsp-survival-ink); }
  & th[aria-sort="descending"] button::after { opacity: 1; }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: 180deg; translate: 0 -2px; }
  & .n { text-align: right; }
  & th.n button { flex-direction: row-reverse; }
  & td { padding: 6px 4px; border-bottom: 1px solid var(--dsp-survival-hair); font-variant-numeric: tabular-nums; }
  & td.n { font: 500 11.5px var(--dsp-survival-mono); white-space: nowrap; }
  & tbody tr { cursor: pointer; transition: background-color .15s, opacity .25s; }
  & tbody tr:hover { background: color-mix(in oklch, var(--dsp-survival-ink) 4%, transparent); }
  & tbody tr.is-focus { background: color-mix(in oklch, var(--c) 12%, transparent); }
  & tbody tr.is-in { animation: dsp-survival-up .4s var(--dsp-survival-out) both; animation-delay: calc(var(--i) * 45ms + 120ms); }
  & tfoot th, & tfoot td { padding: 7px 4px 2px; font-weight: 650; text-align: left; font-size: 11.5px; color: var(--dsp-survival-mute); }
  & tfoot td.n { text-align: right; color: var(--dsp-survival-ink); }
  & .bad { color: color-mix(in oklch, var(--dsp-survival-bad), var(--dsp-survival-ink) 10%); }
}
.dsp-survival__segs:has(tbody tr.is-focus) tbody tr:not(.is-focus) { opacity: .62; }
.dsp-survival__nm {
  display: flex; align-items: center; gap: 8px; min-width: 0;
  & .sw {
    width: 15px; height: 15px; border-radius: 4px; flex: none; display: grid; place-items: center;
    box-shadow: inset 0 0 0 1.5px var(--c); transition: background-color .2s, scale .3s var(--dsp-survival-spring);
  }
  & .sw svg { width: 11px; height: 11px; fill: none; stroke: var(--dsp-survival-bg); stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; opacity: 0; transition: opacity .15s; }
  & .sw[aria-checked="true"] { background: var(--c); }
  & .sw[aria-checked="true"] svg { opacity: 1; }
  & .sw:active { scale: .85; }
  & .sw[aria-disabled="true"] { cursor: not-allowed; }
  & .nb { display: grid; text-align: left; min-width: 0; line-height: 1.25; border-radius: 5px; }
  & .nb b { font-weight: 620; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .nb small { font-size: 10.5px; color: var(--dsp-survival-faint); white-space: nowrap; }
  & .nb small em { font-style: normal; color: color-mix(in oklch, var(--dsp-survival-bad), var(--dsp-survival-ink) 15%); }
}
.dsp-survival__detail {
  display: grid; gap: 10px; align-content: start;
  & .dh { display: flex; align-items: center; gap: 8px; }
  & .dh i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); flex: none; }
  & .dh h3 { font-size: 13.5px; font-weight: 680; }
  & .dh span { margin-left: auto; font-size: 11px; color: var(--dsp-survival-faint); white-space: nowrap; }
  & .say { font-size: 12.5px; line-height: 1.5; color: var(--dsp-survival-mute); text-wrap: pretty; }
  & .say b { color: var(--dsp-survival-ink); font-weight: 650; }
  & dl { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; }
  & dl div { padding: 6px 8px; border-radius: 9px; background: var(--dsp-survival-raise); min-width: 0; }
  & dt { font-size: 9.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--dsp-survival-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font: 650 12px var(--dsp-survival-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & h4 { font-size: 11px; font-weight: 650; letter-spacing: .02em; color: var(--dsp-survival-mute); margin-bottom: 6px; }
  & .bb { display: grid; grid-template-columns: 74px minmax(0, 1fr) auto; align-items: center; gap: 8px; font-size: 11px; color: var(--dsp-survival-mute); margin-top: 4px; }
  & .bb i { height: 8px; border-radius: 99px; background: color-mix(in oklch, var(--dsp-survival-ink) 30%, transparent); width: calc(var(--w) * 100%); transform-origin: left; animation: dsp-survival-grow .8s var(--dsp-survival-out) both; }
  & .bb.km i { background: var(--c); }
  & .bb b { font: 650 11px var(--dsp-survival-mono); color: var(--dsp-survival-ink); font-variant-numeric: tabular-nums; }
  & .bias p { margin-top: 7px; font-size: 11.5px; color: var(--dsp-survival-faint); text-wrap: pretty; line-height: 1.45; }
  & .go {
    display: flex; align-items: center; justify-content: space-between; gap: 8px; height: 34px; padding: 0 12px; border-radius: 10px; font-size: 12px; font-weight: 650;
    background: color-mix(in oklch, var(--c) 16%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 34%, transparent); transition: background-color .2s;
  }
  & .go svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transition: translate .3s var(--dsp-survival-spring); }
  & .go:hover { background: color-mix(in oklch, var(--c) 24%, transparent); }
  & .go:hover svg { translate: 3px 0; }
  & .go:disabled { opacity: .5; }
  & > * { animation: dsp-survival-up .4s var(--dsp-survival-out) both; animation-delay: calc(var(--i, 0) * 50ms); }
}
@keyframes dsp-survival-grow { from { scale: 0 1; } }

/* ------------------------------------------------------------------ tail view */
.dsp-survival__v-tail { height: 100%; }
.dsp-survival__tailcard {
  height: 100%; min-height: 0; display: flex; flex-direction: column; gap: 9px; padding: 12px 14px 6px; border-radius: 15px;
  background: var(--dsp-survival-card); box-shadow: inset 0 0 0 1px var(--dsp-survival-hair);
}
.dsp-survival__th {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 8px 14px; flex-wrap: wrap;
  & h3 { font-size: 13.5px; font-weight: 680; text-wrap: balance; }
  & p { font-size: 11.5px; color: var(--dsp-survival-faint); text-wrap: pretty; }
  & p b { color: var(--dsp-survival-ink); font-weight: 650; }
  & p em { font-style: normal; color: color-mix(in oklch, var(--dsp-survival-bad), var(--dsp-survival-ink) 12%); font-weight: 650; }
}
.dsp-survival__chips {
  display: flex; gap: 6px; flex-wrap: wrap;
