    M.segs.map((s) => '<button type="button" role="radio" style="--c:' + segColor(s.i) + '" aria-checked="' + (st.tailSeg === s.i) + '" tabindex="' + (st.tailSeg === s.i ? 0 : -1) + '" data-v="' + s.i + '"' +
      (counts[s.i] ? '' : ' disabled title="Nothing ' + stillWord() + ' in ' + esc(s.label) + '"') + '><i></i>' + esc(s.label) + '<b>' + counts[s.i] + '</b></button>').join('');
  let list = st.tailSeg >= 0 ? open.filter((o) => o.tk[key] === st.tailSeg) : open.slice();
  if (st.tailSort === 'old') list.sort((a, b) => b.t - a.t);
