  K('tailaxis').textContent = 'Age against the ' + dur(t) + ' target, ' + (st.scale === 'log' ? 'log' : 'linear') + ' scale';
  const [t0, t1] = domain(), log = st.scale === 'log';
  const f = (v) => Math.max(0.012, Math.min(1, log ? (Math.log(Math.max(v, t0)) - Math.log(t0)) / (Math.log(t1) - Math.log(t0)) : v / t1));
  const first = flip ? flipCapture(tailOl, 'li[data-id]', 'data-id') : new Map();
  const PRI = DIMS.priority.segs, PLAN = DIMS.plan.segs, CH = DIMS.channel.segs;
  tailOl.innerHTML = list.length ? list.map((o, n) => {
    const tk = o.tk, segI = tk[key], ex = st.open.has(tk.id), over = o.t - t, w = f(o.t), tp = f(t);
