    return '<li data-id="' + tk.id + '" style="--c:' + segColor(segI) + ';--i:' + n + '">' +
      '<button type="button" class="row" aria-expanded="' + ex + '" aria-controls="dsp-survival-t' + tk.id + '">' +
      '<span class="tt"><b>' + esc(tk.subj) + '</b><small><code>#' + tk.id + '</code>' + CH[tk.ch] + ' · ' + PRI[tk.pr] + ' · ' + PLAN[tk.pl] +
      (tk.esc ? '<em class="flag">Escalated</em>' : '') + (tk.nudged ? '<em class="flag">Nudged</em>' : '') + '</small></span>' +
      '<span class="bar' + (o.t > t1 ? ' over-edge' : '') + '" aria-hidden="true"><i style="--w:' + w.toFixed(3) + ';--tp:' + Math.min(tp, w).toFixed(3) + '"></i><em style="--tp:' + tp.toFixed(3) + '"></em></span>' +
      '<span class="age"><b>' + dur(o.t) + '</b><small' + (over > 0 ? ' class="over">' + dur(over) + ' past' : '>' + dur(-over) + ' to go') + '</small></span>' +
      '<svg class="chev" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg></button>' +
      '<div class="more" id="dsp-survival-t' + tk.id + '"' + (ex ? '' : ' inert') + '><div class="mi"><div class="mw">' +
      '<ol class="tl"><li><b>Opened</b>' + when(tk.at) + ' by ' + CH[tk.ch].toLowerCase() + '</li>' + reply +
      '<li><b>Now</b>' + dur(o.t, true) + ' ' + (res ? 'open' : 'without a reply') + (over > 0 ? ', ' + dur(over, true) + ' past target' : '') + '</li></ol>' +
      '<div class="acts"><button type="button" class="pri" data-act="nudge"' + (tk.nudged ? ' disabled title="' + esc(first2) + ' was nudged at 14:00"' : '') + '>' + (tk.nudged ? 'Nudged at 14:00' : 'Nudge ' + esc(first2)) + '</button>' +
      '<button type="button" data-act="esc"' + (tk.esc ? ' disabled title="Already with the team lead"' : '') + '>' + (tk.esc ? 'With team lead' : 'Escalate to team lead') + '</button></div>' +
      '</div></div></div></li>';
  }).join('') : '<li class="empty">Nothing ' + stillWord() + ' here — every ticket in this range has been ' + verb() + '.</li>';
  flipPlay(tailOl, 'li[data-id]', 'data-id', first);
}
tailOl.addEventListener('click', (e) => {
  const li = e.target.closest('li[data-id]'); if (!li) return;
  const id = +li.dataset.id, tk = T.find((x) => x.id === id);
  const act = e.target.closest('[data-act]');
  if (act) {
    if (act.disabled) return;
    if (act.dataset.act === 'nudge') { tk.nudged = true; toast('Nudged ' + tk.agent + ' about #' + id); }
    else { tk.esc = true; toast('#' + id + ' escalated to the payroll team lead'); }
    const keep = act.dataset.act;
    renderTail(false);
    const b = $('li[data-id="' + id + '"] [data-act="' + (keep === 'nudge' ? 'esc' : 'nudge') + '"]', tailOl);
    if (b && !b.disabled) b.focus({ preventScroll: true }); else { const r = $('li[data-id="' + id + '"] .row', tailOl); if (r) r.focus({ preventScroll: true }); }
    return;
  }
  const row = e.target.closest('.row'); if (!row) return;
  const on = row.getAttribute('aria-expanded') !== 'true';
  row.setAttribute('aria-expanded', on);
  const more = row.nextElementSibling;
  if (on) { more.removeAttribute('inert'); st.open.add(id); } else { more.setAttribute('inert', ''); st.open.delete(id); }
});
tailOl.addEventListener('keydown', (e) => {
  const row = e.target.closest('.row');
  if (e.key === 'Escape') {
    const li = e.target.closest('li[data-id]'); const r = li && $('.row', li);
    if (r && r.getAttribute('aria-expanded') === 'true') { e.preventDefault(); r.click(); r.focus(); }
    return;
