/* ================================================================ radios, tabs, switch */
function check(group, b) {
  $$('[role="radio"]', group).forEach((x) => { const on = x === b; x.setAttribute('aria-checked', on); x.tabIndex = on ? 0 : -1; });
}
function radios(group, pick) {
  group.addEventListener('click', (e) => {
    const b = e.target.closest('[role="radio"]');
    if (!b || b.disabled || b.getAttribute('aria-checked') === 'true') return;
    check(group, b); pick(b.dataset.v);
  });
  group.addEventListener('keydown', (e) => {
    const all = $$('[role="radio"]', group).filter((x) => !x.disabled);
    const i = all.indexOf(e.target); if (i < 0) return;
    let j = i;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (i + 1) % all.length;
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (i - 1 + all.length) % all.length;
    else if (e.key === 'Home') j = 0;
    else if (e.key === 'End') j = all.length - 1;
    else return;
    e.preventDefault();
    const b = all[j]; check(group, b); b.focus(); pick(b.dataset.v);
  });
}
function refreshAll() {
  compute();
  if (st.focus != null && !M.segs[st.focus]) st.focus = null;
  const list = targets();
  if (list.indexOf(tg()) < 0) st.target[st.measure] = snap(tg());
  targetStats();
  xhT = null; pinned = false;
  drawChart(true); renderKpis(); renderSegs(false, true); renderDetail();
  if (st.view === 'tail') renderTail(false);
  const res = st.measure === 'res';
  K('title').textContent = res ? 'How long tickets take to resolve' : 'How long customers wait for a first reply';
  K('charttitle').textContent = res ? 'Share of tickets still unresolved' : 'Share of tickets still waiting for a first reply';
  K('axisnote').textContent = 'Kaplan–Meier · time since opened, ' + (st.scale === 'log' ? 'log' : 'linear') + ' scale';
}
const grp = (g) => $('[data-g="' + g + '"]');
radios(grp('measure'), (v) => { st.measure = v; refreshAll(); });
radios(grp('range'), (v) => { st.range = +v; refreshAll(); });
radios(grp('dim'), (v) => { st.dim = v; st.hidden.clear(); st.focus = null; st.tailSeg = -1; st.sort = { k: 'N', dir: -1 }; refreshAll(); });
radios(grp('scale'), (v) => { st.scale = v; refreshAll(); });
radios(grp('tailsort'), (v) => { st.tailSort = v; renderTail(true); });
radios(chips, (v) => { st.tailSeg = +v; renderTail(true); });

const bandSw = $('[data-sw="band"]');
bandSw.addEventListener('click', () => {
