const tabs = $$('[role="tab"]');
function setView(v) {
  st.view = v;
  tabs.forEach((t) => { const on = t.dataset.view === v; t.setAttribute('aria-selected', on); t.tabIndex = on ? 0 : -1; });
  $$('.dsp-survival__view').forEach((p) => { p.hidden = p.dataset.view !== v; });
  if (v === 'tail') { renderTail(false); tailOl.scrollTop = 0; }
  else requestAnimationFrame(() => { if (!root.isConnected) return; drawChart(true); });
}
tabs.forEach((t) => t.addEventListener('click', () => { if (t.getAttribute('aria-selected') !== 'true') setView(t.dataset.view); }));
$('.dsp-survival__tabs').addEventListener('keydown', (e) => {
  const i = tabs.indexOf(e.target); if (i < 0) return;
  let j = i;
  if (e.key === 'ArrowRight') j = (i + 1) % tabs.length;
  else if (e.key === 'ArrowLeft') j = (i - 1 + tabs.length) % tabs.length;
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = tabs.length - 1;
  else return;
  e.preventDefault(); tabs[j].focus(); setView(tabs[j].dataset.view);
