/* ================================================================ mount */
let rzT = 0, lastW = 0, lastH = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const w = chartEl.clientWidth, h = chartEl.clientHeight;
  if (!w || (w === lastW && h === lastH)) return;
  const firstDraw = !lastW;
  lastW = w; lastH = h;
  cancelAnimationFrame(rzT);
  rzT = requestAnimationFrame(() => { if (!root.isConnected) return; drawChart(firstDraw); });
});
compute();
renderKpis(); renderSegs(false, true); renderDetail();
drawChart(true);
lastW = chartEl.clientWidth; lastH = chartEl.clientHeight;
ro.observe(chartEl);
